void init(int recordsNum, int range, unsigned seed) {
    if (recordsNum < 1 || recordsNum > max_limit) {
        printf("Invalid record number input\n");
        return;
    }
    num_of_records = recordsNum;

    offsets = malloc(sizeof(long) * 10000); // allocate memory for at least 10,000 records
    if (offsets == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    keys = calloc(num_of_records, sizeof(int)); // initialize to zero
    if (keys == NULL) {
        printf("Memory allocation failed\n");
        free(offsets);
        return;
    }

    records = malloc(sizeof(record) * num_of_records);
    if (records == NULL) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    srand(seed); // seed for reproducible random numbers

    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_of_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = rand() % range + 1; // generate random number in the given range
        int index = rand() % (sizeof(names)/sizeof(char*)); // generate a random index for name list
        records[i].name = names[index];

        if (!external_log_init(&records[i])) { // log initialization of each record structure
            printf("Logging failed\n");
            break;
        }
    }
    pthread_mutex_unlock(&lock);

    free(offsets);
    free(keys);
    free(records);
}
