['Here is a C program that does what you requested:
```C
#include <stdio.h>
#include <stdlib.h>
#define MAX_LINE_LEN 1024

int main() {
    FILE *file = fopen("data.csv", "r");
    if (file == NULL) {
        printf("Error opening file!\n");
        return -1;
    }

    int *array = malloc(sizeof(*array)); // Start with space for 1 int
    size_t used = 0;                   // Total allocated items we have
    size_t size = 1;                   // Total amount of space we have

    char line[MAX_LINE_LEN];
    while (fgets(line, sizeof(line), file) != NULL) {
        int value;
        if (sscanf(line, "%d", &value) == 1) { // If a number was successfully read
            if (used == size) {  // Check if we need to resize the array
                size *= 2;       // Double our available space each time we run out of it
                array = realloc(array, sizeof(*array)*size);

                if (array == NULL) {
                    printf("Memory allocation failed!\n");
                    return -1;  // Or break or do something else to handle this error
                }
            }

            array[used++] = value; // Add the number to our array and increment used amount
        } else {
            printf("Error: Invalid data format!\n");
        }
    }

    if (ferror(file)) {
        printf("Error reading file!\n");
        return -1;  // Or break or do something else to handle this error
    }

    if (used > 0) {  // If we actually read any numbers...
        int max = array[0];
        for (size_t i = 1; i < used; ++i) {
            if (array[i] > max) {
                max = array[i];
            }
        }

        printf("Max: %d\n", max);
    } else {
        printf("No data in file!\n");
    }

    free(array);  // Don't forget to clean up after ourselves
    fclose(file);
}
```
This program first opens the CSV file and allocates an initial block of memory for our integer array. It then reads the file line by line, each time checking if the line it read is a valid integer. If so, it adds the number to the array, and resizes the array if needed using `realloc`. If any lines fail to be parsed into integers or there's an I/O error while reading the file, it reports this back to the user. After finishing up with the file, it finds the maximum value in our array (if any) and prints this to the console before cleaning up after itself by freeing memory and closing the file.
']

