import java.util.*;
import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;

public class PokemonReportGenerator {
    private final ApiClient apiClient; // Assume we have this injected into our constructor
    private Cache<String, Type> cache = CacheBuilder.newBuilder()
        .maximumSize(10_000)
        .build(); 

    public PokemonReportGenerator(ApiClient apiClient) {
        this.apiClient = apiClient;
    }

    public String generatePokemonReport(Pokemon pokemon) {
        try {
            Type primaryType = getCachedOrFetchTypeData(pokemon.getPrimaryTyping());
            Type secondaryType = Optional.ofNullable(pokemon.getSecondaryTyping())
                .map(this::getCachedOrFetchTypeData)
                .orElse(null); 

            // ... generate your report here
        } catch (Exception e) {
            return "Failed to generate report for Pokemon: " + pokemon.getName();
        }
    }

    private synchronized Type getCachedOrFetchTypeData(String typeName) {
        try {
            Type cachedType = cache.getIfPresent(typeName);

            if (cachedType != null) {
                return cachedType;
            } else {
                // Fetch from API
                Type fetchedType = apiClient.fetchTypeData(typeName); 

                // Update cache
                cache.put(typeName, fetchedType);

                return fetchedType;
            }
        } catch (Exception e) {
            throw new RuntimeException("Failed to get or fetch type data", e);
        }
    }
}
```
This is a simplified example where we are using Guava's cache library for caching, and synchronized block for making sure our methods are thread-safe. 

You should also consider how to handle failures when fetching from the API, network delays, invalidating cache etc. You could use RetryTemplate or similar libraries available in Spring for such cases.
