['Here is a basic implementation of a semaphore in C. This is a simple version without logging and error handling for the sake of simplicity.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

typedef struct {
    int initial_value;
    sem_t* semaphore;
} Semaphore;

Semaphore* create_semaphore(int value) {
    Semaphore* sem = malloc(sizeof(Semaphore));
    if (sem == NULL) {
        return NULL;
    }

    sem->initial_value = value;
    sem->semaphore = malloc(sizeof(sem_t));

    if (sem_init(sem->semaphore, 0, value) == -1) {
        free(sem);
        return NULL;
    }

    return sem;
}

void modify_semaphore(Semaphore* sem, int newValue) {
    if (newValue >= 0 && sem->initial_value != newValue) {
        int currentValue = newValue - sem->initial_value;

        for (; currentValue > 0; --currentValue) {
            sem_post(sem->semaphore);
        }
        for (; currentValue < 0; ++currentValue) {
            sem_wait(sem->semaphore);
        }
    }
}

void destroy_semaphore(Semaphore* sem) {
    if (sem == NULL) {
        return;
    }

    sem_destroy(sem->semaphore);
    free(sem->semaphore);
    free(sem);
}
```

This is a simple implementation of a semaphore management system in C. 
It provides functions to create, modify and destroy semaphores with initial values. The modify_semaphore function allows adjusting the value of an existing semaphore by incrementing or decrementing it using sem_post and sem_wait. If you need a more advanced implementation or additional features, please specify them in your task description.
']

