        string dt = ctime(&now);

        file << "Time: "<< dt;
        file << "Request Count: " << requestCount << endl;
        file << "Active Sessions: " << activeProxySessions << endl;
        file << "Internal Errors: " << internalErrors << endl;

        file.close();
    }
};
```
5. Implement a rate-limiting feature to prevent overloading the server:

```cpp
class RateLimiter {
private:
    int requestLimit;
    int currentRequests = 0;

public:
    void Acquire() {
        if (currentRequests >= requestLimit) {
            throw runtime_error("Rate limit exceeded.");
        }

        currentRequests++;
    }

    void Release() {
        if(currentRequests > 0){
            currentRequests--;
        }
    }
};
```
