const app = express();
app.use(bodyParser.json());

// Connect to Redis cache
let client = redis.createClient();
client.on('error', (err) => console.log("Error " + err));

// Middleware for logging all API calls
app.use((req, res, next) => {
  console.info(`${new Date()} - ${req.method} request for ${req.url}`);
  next();
});

app.put('/resource/:id', async (req, res) => {
  try {
    // Validate the incoming data
    if (!req.params.id || !req.body || Object.keys(req.body).length === 0) {
      return res.status(400).json({ error: 'Invalid request' });
    }

    // Check if resource exists in cache, if not fetch from database and update cache
    client.get(`resource_${req.params.id}`, async (err, data) => {
      if (data !== null) {
        res.status(200).json({ message: 'Resource updated' });
      } else {
        // Perform the update operation on the database
        const response = await performUpdateOperation(req.params.id, req.body); 

        // Update cache with new data after successful update
        client.setex(`resource_${req.params.id}`, 3600, JSON.stringify(response));

        // Send notification to external message service
        axios.post('http://external-message-service/notify', { type: 'update' })
          .catch((error) => console.error('Failed to send update notification', error));
      }
    });
  } catch (err) {
    // Handle errors gracefully and do not expose sensitive information
    console.error(err);
    res.status(500).json({ error: 'An unexpected error occurred' });
  }
});

app.delete('/resource/:id', async (req, res) => {
  try {
    // Perform delete operation on the database
    await performDeleteOperation(req.params.id);

    // Remove resource from cache after successful delete
    client.del(`resource_${req.params.id}`);

    // Send notification to external message service
    axios.post('http://external-message-service/notify', { type: 'delete' })
      .catch((error) => console.error('Failed to send delete notification', error));

    res.status(200).json({ message: 'Resource deleted' });
  } catch (err) {
    // Handle errors gracefully and do not expose sensitive information
    console.error(err);
    res.status(500).json({ error: 'An unexpected error occurred' });
  }
});

app.listen(3000, () => console.log('Server is running'));
```
This example assumes you have a performUpdateOperation and performDeleteOperation function that interacts with your database. You will need to replace these with your actual data persistence logic. Also remember to replace 'http://external-message-service/notify' with the actual URL of your external message service.
