public class PageUpdateService : IPageUpdateService
{
    private readonly ICacheService _cacheService;
    private readonly IDatabaseService _databaseService;

    public PageUpdateService(ICacheService cacheService, IDatabaseService databaseService)
    {
        _cacheService = cacheService;
        _databaseService = databaseService;
    }

    public async Task<bool> UpdatePageAsync(string pageSectionId, string elementId, string htmlContent)
    {
        var isValidHtml = await ValidateHTML(htmlContent);

        if (!isValidHtml)
            throw new Exception("Invalid HTML content");

        // Retrieve page state from database
        var currentPageState = await _databaseService.GetPageSectionAsync(pageSectionId);

        // Update element's HTML content
        var updatedElementContent = currentPageState.Elements[elementId].HtmlContent = htmlContent;

        // Attempt to update page state in cache with new content, retry if necessary
        for (int i = 0; i < 3; i++)
        {
            try
            {
                await _cacheService.UpdatePageSectionAsync(pageSectionId, updatedElementContent);
                break;
            }
            catch (Exception ex) when (ex is CacheUnavailableException || ex is DatabaseWriteFailedException)
            {
                if (i == 2) throw; // Max retries reached
                await Task.Delay((int)Math.Pow(2, i)); // Exponential backoff
            }
        }

        return true; // Indicating the page should be refreshed
    }

    private async Task<bool> ValidateHTML(string htmlContent)
    {
        // Parse HTML and check for validity, here is a simplified example using HtmlAgilityPack library. 
        var doc = new HtmlDocument();
        doc.LoadHtml(htmlContent);

