```javascript
const fs = require('fs').promises;
const path = require('path');
const Ajv = require("ajv");
const ajv = new Ajv();

async function validateDirectory(directoryPath, schema) {
    const files = await fs.readdir(directoryPath);
    for (let file of files) {
        try{
            let configContents = await fs.readFile(path.join(directoryPath,file), 'utf8');
            let parsedConfig = JSON.parse(configContents); 
            const valid = ajv.validate(schema, parsedConfig);
            if (!valid) console.error('Failed validation for: ', file, '. Errors: ', ajv.errors);
        } catch (err){
            console.log('File not found or error processing file:', file, '. Error: ', err);
        }
    }
}
```
