import java.util.*;
import org.apache.commons.configuration.PropertiesConfiguration;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DataStreamService {
    private static final Logger logger = LoggerFactory.getLogger(DataStreamService.class);
    private final PropertiesConfiguration config;
    private List<DataSource> dataSources;
    private ScheduledExecutorService executor;

    public DataStreamService() throws ConfigurationException {
        this.config = new PropertiesConfiguration("config.properties");
        int numThreads = config.getInt("numThreads", 10);
        this.executor = Executors.newScheduledThreadPool(numThreads);
    }

    public void start() {
        dataSources.forEach(dataSource -> {
            executor.scheduleWithFixedDelay(dataSource, 0, config.getInt("pollInterval"), TimeUnit.SECONDS);
        });
    }

    public void stop() {
        // notify event bus of service stop event

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException ex) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public void addDataSource(DataSource dataSource) {
        dataSources.add(dataSource);
    }
}
```

