```javascript
const cluster = require('cluster');
const http = require('http');
const os = require('os');

if (cluster.isMaster) {
  const cpuCount = os.cpus().length;

  // Fork workers.
  for (let i = 0; i < cpuCount; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died with code: ${code}, and signal: ${signal}`);
    console.log('Starting a new worker');
    cluster.fork();
  });
} else {
  // Workers can share any TCP connection
  http.createServer((req, res) => {
    let data = '';

    req.on('data', chunk => {
      data += chunk;

      // If data size exceeds certain limit, reject the stream
      if (data.length > MAX_DATA_SIZE) {
        res.statusCode = 413;
        res.end(`Data size exceeded ${MAX_DATA_SIZE} bytes.`);
        req.connection.destroy();
      }
    });

    req.on('error', error => {
      console.log(`Error occurred: ${error.message}`);
    })

    req.on('end', () => {
      // Handle data here...

      res.statusCode = 200;
      res.setHeader('Content-Type', 'text/plain');
      res.end('Data received successfully.\n');
    });
  }).listen(8080);
}
```
This code snippet uses the `cluster` module to create child processes that all share the same server port. It sets up an HTTP server that aggregates data from incoming streams and handles network timeouts, server errors, and data corruption. The process of handling stream data is simplified for brevity. You can further refactor it according to your own requirements like using `async/await` in Node.js 8+ for handling multiple promises or events.

