let isPaused = false;

async function generateCombinedCertificate() {
  const limit = pLimit(5); // Limit concurrency to 5 requests

  while (currentIndex < userKeys.length) {
    if (!isPaused) {
      await new Promise((resolve, reject) => setTimeout(() => resolve(), currentIndex * 100)); // simulate network latency 

      const userKey = userKeys[currentIndex];
      limit(async () => {
        try {
          let certificate = null;
          for (let attempts = 0; !certificate && attempts < 3; attempts++) {
            try {
              certificate = await getCertificateFromAPI(userKey);
            } catch (error) {
              if (!axios.isCancel(error)) { // ignore cancellation errors
                console.log('Retry due to network error, attempt: ', attempts + 1);
                await new Promise((resolve) => setTimeout(() => resolve(), Math.pow(2, attempts) * 1000)); // exponential backoff
              } else {
                throw error;
              }
            }
          }

          if (!certificate) {
            console.log('Failed to fetch certificate for user: ', userKey);
          } else {
            certificateArray[currentIndex] = certificate;
            currentIndex++;
          }
        } catch (error) {
          console.log('Unexpected error: ', error);
        }
      });
    } else {
      await new Promise((resolve) => setTimeout(() => resolve(), 100)); // Pause execution for a while to prevent tight looping
    }
  }

  return certificateArray;
}

async function getCertificateFromAPI(userKey, cancelTokenSource) {
  const url = `https://example.com/api/certificates?key=${encodeURIComponent(userKey)}`; // replace with real API endpoint and necessary parameters

  try {
    const response = await axios.get(url);

    return response.data;
  } catch (error) {
    if (axios.isCancel(error)) {
      throw error;
    } else {
      console.log('Network error: ', error);

      // If we have a cancel token source, cancel it to prevent future attempts
      if (cancelTokenSource) {
        cancelTokenSource();
      }

      throw error;
    }
  }
}
