$oauth_server = 'https://example.com/oauth';
$app_name = 'myApp';
$api_endpoint = 'https://example.com/api';
$access_token_cache_key = $app_name . '_access_token';
$rate_limit_count = 0;
$client = new Client(['base_uri' => $oauth_server]);
$cache = CacheManager::getInstance('apcu', new ApcuConfig());

function authenticate($username, $password) {
    global $client, $app_name, $api_endpoint, $access_token_cache_key, $rate_limit_count;

    $retries = 3;
    $delay = 1000000; // 1 second

    while ($retries-- > 0) {
        try {
            $response = $client->post('/oauth/token', [
                'json' => [
                    'username' => $username,
                    'password' => $password,
                    'grant_type' => 'password',
                    'client_id' => $app_name,
                ]
            ]);

            $data = json_decode($response->getBody(), true);
            $access_token = $data['access_token'];
            $cache->set($access_token_cache_key, $access_token);

            return $access_token;
        } catch (RequestException $e) {
            usleep($delay); // wait for the specified microseconds before retrying
        }
    }

    throw new Exception('Failed to authenticate after ' . $retries . ' attempts.');
}

function resolve_hostname($hostname) {
    $ip = gethostbyname($hostname);
    if ($ip == $hostname) { // If the hostname was not resolved into an IP address, it returns the original input
        throw new Exception('Failed to resolve hostname.');
    } else {
        return $ip;
    }
}

function get_user_info($username, $password) {
    $access_token = $cache->get($access_token_cache_key);

    if ($access_token === null) {
        $access_token = authenticate($username, $password);
    } elseif (++$rate_limit_count >= 10) { // Limit the rate of API calls to prevent abuse
        usleep(60 * 1000000); // wait for one minute before allowing further requests
        $rate_limit_count = 0;
    }

    $response = $client->get($api_endpoint . '/user', [
        'headers' => ['Authorization' => 'Bearer ' . $access_token]
    ]);

    $data = json_decode($response->getBody(), true);

    return [
        'email' => $data['email'],
        'ip_address' => resolve_hostname(parse_url($api_endpoint, PHP_URL_HOST))
    ];
}
?>
