['Here is a basic implementation of `RandomValueGenerator` class with the requested functionality:

```csharp
using System;
using System.Globalization;

public class RandomValueGenerator
{
    private readonly int minimumValue;
    private readonly int maximumValue;

    public RandomValueGenerator(int min, int max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value should be strictly less than Maximum value");

        this.minimumValue = min;
        this.maximumValue = max;
    }

    public string Range => $"{this.minimumValue} - {this.maximumValue}";

    private Random _random => new Random(); // Create a single instance of Random for the lifetime of an object.

    public float GenerateRandomFloat()
    {
        return (float)(this._random.NextDouble() * (this.maximumValue - this.minimumValue) + this.minimumValue);
    }

    public int GenerateRandomInt()
    {
        return this._random.Next(this.minimumValue, this.maximumValue + 1); // Add 1 to make the range inclusive.
    }

    public float GenerateRandomExclusiveFloat()
    {
        return (float)(this._random.NextDouble() * (this.maximumValue - this.minimumValue) + this.minimumValue);
    }

    public int GenerateRandomExclusiveInt()
    {
        return this._random.Next(this.minimumValue, this.maximumValue); // Exclude the upper bound.
    }
}
```
Please note that floating point precision issues and possible overflows have not been handled in these methods. You may need to implement additional checks or handle these cases based on your specific requirements.
