['Here is a robust asynchronous reduction function implemented in JavaScript which handles large datasets efficiently:

```javascript
const asyncReduce = (arrays, initialValue, callback, options) => {
  const defaultOptions = { timeout: null, maxRetries: Infinity, retryInterval: 0 };
  let { timeout, maxRetries, retryInterval } = { ...defaultOptions, ...options };

  return new Promise((resolve, reject) => {
    let count = 0;
    let results = {};

    const processArray = (index, array) => {
      return new Promise(async (res, rej) => {
        try {
          const value = await callback(index, initialValue, array[0], arrays.length);
          res([index, value]);
        } catch (error) {
          if (maxRetries > 0) {
            maxRetries--;
            setTimeout(() => processArray(index, array).then(res).catch(rej), retryInterval);
          } else {
            reject(`Error processing array ${index}: ${error.message}`);
          }
        }
      });
    };

    const timeoutPromise = new Promise((_, rej) => setTimeout(() => rej("Timeout Error"), timeout));

    let promises = [];

    for (let i = 0; i < arrays.length; i++) {
      promises[i] = Promise.race([processArray(i, arrays[i]), timeoutPromise]);
      promises[i].then((result) => {
        results[result[0]] = result[1];
        if (++count === arrays.length) resolve(results);
      }).catch(reject);
    }
  });
};
```

This function uses Promise.race to handle timeouts and retries for each array. The timeout option, if present in the options object, sets a timeout for processing an array. If a timeout occurs before the promise resolves, it will reject with a "Timeout Error". The maxRetries option allows developers to specify how many times the function should retry failed reductions. If the maximum number of retries is exceeded, the function rejects with an error message.

Please note that this implementation assumes that the callback function returns a promise if it's asynchronous, or a value directly if it's synchronous. You may need to adjust your code if the callback isn't designed in such a way. Also, you might need to adjust it according to how Promises resolve/reject in your environment.
']

['Here is the C code for managing dynamic list of configuration settings from a file:
```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>

typedef struct Settings {
    char* key;
    char* value;
    struct Settings* next;
} Settings;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Settings* head = NULL;

void addSetting(char* key, char* value) {
    pthread_mutex_lock(&lock);

    Settings* newNode = malloc(sizeof(Settings));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new setting");
        return;
    }

    newNode->key = strdup(key);
    newNode->value = strdup(value);
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void deleteSetting(char* key) {
    pthread_mutex_lock(&lock);

    Settings** pp = &head;
    while (*pp != NULL) {
        if (strcmp((*pp)->key, key) == 0) {
            Settings* deleteMe = *pp;
            *pp = deleteMe->next;

            free(deleteMe->key);
            free(deleteMe->value);
            free(deleteMe);
        } else {
            pp = &(*pp)->next;
        }
    }

    pthread_mutex_unlock(&lock);
}

char* getSetting(char* key) {
    static char error[64] = "Setting not found";
    pthread_mutex_lock(&lock);

    for (Settings* p = head; p != NULL; p = p->next) {
        if (strcmp(p->key, key) == 0) {
            char* result = strdup(p->value);
            pthread_mutex_unlock(&lock);
            return result;
        }
    }

    pthread_mutex_unlock(&lock);
    return error;
}

void saveSettingsToFile(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open configuration file for writing");
        return;
    }

    pthread_mutex_lock(&lock);
    for (Settings* p = head; p != NULL; p = p->next) {
        if (fprintf(file, "%s=%s\n", p->key, p->value) < 0) {
            perror("Failed to write configuration setting to file");
            fclose(file);
            return;
        }
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

void readSettingsFromFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open configuration file for reading");
        return;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        char* equals = strchr(buffer, '=');
        if (equals != NULL) {
            *equals = '\0';
            ++equals;
            char* newline = strchr(equals, '\n');
            if (newline != NULL) {
                *newline = '\0';
            }

            addSetting(buffer, equals);
        } else {
            perror("Invalid configuration setting format in file");
        }
    }

    fclose(file);
}
```
This is a basic implementation. To improve performance and limit memory usage, you could implement a cache that stores recently accessed settings in an associative array or hash table to reduce the need for disk access for frequently accessed values. For error handling, you may want to return specific error codes instead of just printing errors with perror(). Additionally, there is no support for network timeouts or disk space limitations, which would require additional code. Lastly, this implementation does not include tests and doesn't scale well with more features, such as type checking for setting values or automatic handling of changes to the configuration file outside of these functions. For testing, you can use a unit test framework like cmocka, or write simple tests yourself with assert() statements.
']

['```javascript
function optimizeNodeContent(node, sizeLimit, selector, performanceBudget) {
    const start = performance.now();

    function traverseNode(currentNode) {
        if (performance.now() - start > performanceBudget) return null;

        currentNode.querySelectorAll(selector).forEach((element) => {
            let text = element.innerText;

            if (text.length > sizeLimit) {
                const splitPoint = sizeLimit;

                // Try to truncate at a whitespace if possible, else cut off at the limit
                let truncatedIndex = text.slice(0, sizeLimit).lastIndexOf(" ");
                if (truncatedIndex === -1) {
                    truncatedIndex = splitPoint;
                }

                element.innerText = text.substring(0, truncatedIndex);
            } else if (!text.endsWith(" ")) {
                element.innerText += " ";
            }
        });

        Array.from(currentNode.children).forEach((child) => traverseNode(child));
    }

    traverseNode(node);
}
``` 
Please note that this code assumes you're running in an environment with a performance object like the one provided by modern browsers and NodeJS versions 8+. This also does not handle elements without text, or non-text nodes correctly, which might be necessary based on your specific use case.
