    if (pthread_mutex_init(&lock, NULL) != 0) {
        // handle error...
    }

    // Assume each filename can have a maximum of 256 characters
    char** processedFilenames = malloc(count * sizeof(char*));
    if (processedFilenames == NULL) {
        // handle memory allocation failure...
    }

    for (int i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);  // lock to prevent synchronization issues

        const char* filename = filenames[i];
        int length = strlen(filename);

        // Calculate number of digits in filename
        int digitCount = 0;
        for (int j = 0; j < length; ++j) {
            if (filename[j] >= '0' && filename[j] <= '9') {
                ++digitCount;
            }
        }

        // Create new filename with appended digit count and type "log"
        int processedLength = length + digitCount + 4;  // +4 for "_", digit count, ".log" and null terminator
        if (processedLength > 15) {
            processedLength = 15 - digitCount - 4;  // truncate to fit within limit
        }

        char* processedFilename = malloc(processedLength + 1);
        if (processedFilename == NULL) {
            // handle memory allocation failure...
        }

        snprintf(processedFilename, processedLength+1, "%.*s_%d.log", processedLength - 4, filename, digitCount);
        processedFilenames[i] = processedFilename;

        pthread_mutex_unlock(&lock);  // unlock to allow other threads to access the data source
    }

    *resultCount = count;
    return processedFilenames;
}
