    private List<HealthCheckable> servicesToMonitor = new ArrayList<>(); // add all dependent services here

    public void updateSchema(String schema) throws SQLException{
        if(!isAllServicesRunning()){
            System.out.println("All dependent services must be running for schema updates");
            return;
        }

        Statement stmt = dbConnection.createStatement();
        try {
            dbConnection.setAutoCommit(false);

            // Perform the actual update here, e.g., by executing some SQL scripts
            // Be prepared for partial failures and use transactions to roll back in case of an error

            stmt.executeUpdate("UPDATE schema SET current_schema='" + schema + "'");
            dbConnection.commit();
        } catch(Exception ex){
            System.out.println("Error while updating the database: " + ex);
            dbConnection.rollback(); // Roll back in case of any error to ensure data consistency
        } finally {
            stmt.close();
            dbConnection.setAutoCommit(true);
        }
    }

    private boolean isAllServicesRunning() throws SQLException{
        for(HealthCheckable service : servicesToMonitor){
            if(!service.isHealthy()) return false;
        }

        return true;
    }
}
