public class MD5Hasher : IMD5Hasher
{
    private static readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();

    public string GetHash(string input)
    {
        return _cache.GetOrAdd(input, CalculateHash);
    }

    public bool VerifyHash(string input, string hashToVerify)
    {
        var calculatedHash = GetHash(input);
        return StringComparer.InvariantCultureIgnoreCase.Equals(calculatedHash, hashToVerify);
