                        dataSegment.Data = reader.ReadBytes(/* replace with your segment size */);

                        if (!IsCorrupted(dataSegment))
                        {
                            lock (Cache)  // synchronize access to cache for thread safety
                            {
                                Cache[filePath] = dataSegment;  
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError("Failed to read corrupted data segment", ex);
                        continue;
                    }

                    list.Add(dataSegment);
