struct Args {
    /// The type of data to retrieve.
    #[clap(short, long)]
    data_type: String,
    /// User ID.
    #[clap(short, long)]
    user_id: String,
}

#[tokio::main]
async fn main() -> Result<(), ReqwestError> {
    let args = Args::parse();

    let (tx, rx) = mpsc::channel(100);
    let mut handles = Vec::new();

    for _ in 0..5 {
        let (api_sender, api_receiver) = oneshot::channel();
        handles.push((spawn_api_caller(api_sender), api_receiver));
    }

    tokio::task::spawn(async move {
        for _ in 0..1000 {
            let args_clone = args.clone();
            if tx.send((args_clone.data_type, args_clone.user_id)).is_err() {
                break;
            }
        }
    });

    while let Some(m) = rx.recv().await {
        match m {
            Ok((api_sender, api_receiver)) => {
                let (data_type, user_id) = api_receiver;
                api_sender.send((data_type, user_id)).unwrap();
            }
            Err(_) => break,
        }
    }

    for (handle, _) in handles {
        handle.await.expect("Failed to wait on handle");
    }

    Ok(())
}

async fn api_caller(mut data: mpsc::Receiver<(String, String)>) {
    while let Some((data_type, user_id)) = data.recv().await {
        let start = Instant::now();
        let client = reqwest::Client::new();
        match client.get("http://api.com")
            .header(reqwest::header::CONTENT_TYPE, "application/json")
