                let status = response.status();
                let body = response.text().await.unwrap();
                printlnEEEEFFF
            },
            Err(_) => eprintlnEEEEFFF
        }
    }
}

fn spawn_api_caller(sender: oneshot::Sender<(String, String)>) -> JoinHandle<()> {
    tokio::task::spawn(async move { api_caller(mpsc::unbounded_received(sender)) })
}
