```python
import json
from abc import ABCMeta, abstractmethod

# Base class for all JSON objects
class JsonObject(metaclass=ABCMeta):
    _registry = {}

    @abstractmethod
    def __init__(self, json_data: str):
        pass

    # Register subclasses based on their version
    @classmethod
    def register(cls, version):
        def decorator(subclass):
            cls._registry[version] = subclass
            return subclass
        return decorator

    # Create an instance of a registered JsonObject subclass based on its version
    @classmethod
    def create_instance(cls, json_data: str):
        data = json.loads(json_data)

        if 'version' in data:
            version = data['version']

            if version in cls._registry:
                return cls._registry[version](json_data)

        raise ValueError('Unsupported JSON object version')

    # Parse a JSON string and create an appropriate JsonObject instance
    @classmethod
    def parse(cls, json_string):
        data = json.loads(json_string)

        if 'version' in data:
            version = data['version']

            if version in cls._registry:
                return cls._registry[version](json_string)

        raise ValueError('Unsupported JSON object version')
```

You can then define specific versions of your JsonObject subclasses using the `@register` decorator, as follows:

