class RandomHashGenerator {
public:
    static std::mt19937 generator; // Static member variable for random number generator
    static boost::mutex gen_mutex, hash_mutex; // Mutexes for thread safety

    RandomHashGenerator() {}
    ~RandomHashGenerator() {}

    void setSeed(unsigned int seed) {
        try {
            boost::lock_guard<boost::mutex> lock(gen_mutex);
            generator.seed(seed);
        } catch (const std::exception& e) {
            std::cerr << "Exception: " << e.what() << "\n";
        }
    }

    unsigned int generateRandomNumber() {
        try {
            boost::lock_guard<boost::mutex> lock(gen_mutex);
            return generator();
        } catch (const std::exception& e) {
            std::cerr << "Exception: " << e.what() << "\n";
            return 0;
        }
    }

    static std::string md5(const std::string& data) {
        try {
            boost::lock_guard<boost::mutex> lock(hash_mutex);
            unsigned char digest[MD5_DIGEST_LENGTH];
            MD5((unsigned char*)data.c_str(), data.length(), (unsigned char*)&digest);    
            char mdString[33];
            for(int i = 0; i < 16; ++i)
                sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

            return std::string(mdString);
        } catch (const std::exception& e) {
            std::cerr << "Exception: " << e.what() << "\n";
            return "";
        }
    }
};

