<?php
class PasswordManager {
    private $logger;

    public function __construct($logger) {
        $this->logger = $logger;
    }

    public function generateRandomStringAndHashPassword($password, $length = 16, $salt = null, $hashAlgorithm = 'sha512', $iterations = 5000) {
        try {
            $startTime = microtime(true);
            $randomStr = $this->generateRandomString($length);
            $hashedPassword = $this->hashPasswordWithSaltAndIterations($password, $salt ?? uniqid(), $hashAlgorithm, $iterations);

            $endTime = microtime(true);
            $executionTimeInMilliseconds = ($endTime - $startTime) * 1000;

            $this->logger->info("Random String Generated: '{$randomStr}' in {$executionTimeInMilliseconds} ms");
            $this->logger->info("Password Hashed: '{$hashedPassword}' in {$executionTimeInMilliseconds} ms");

            return ['randomString' => $randomStr, 'hashedPassword' => $hashedPassword];
        } catch (Exception $e) {
            $this->logger->error("Error occurred: " . $e->getMessage());
            throw new Exception('An error has occurred while generating a random string and/or hashing the password.');
        }
    }

    private function generateRandomString($length) {
        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ~`@#$%^&*()_-+={[}]|\:;"<,>.?/';
        $charactersLength = strlen($characters);

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, $charactersLength - 1)];
        }

        return $randomString;
    }

    private function hashPasswordWithSaltAndIterations($password, $salt, $hashAlgorithm, $iterations) {
        $hashedPassword = '';
        for ($i = 0; $i < $iterations; $i++) {
            $hashedPassword = hash_hmac($hashAlgorithm, $password . $salt, '');
        }

        return $hashedPassword;
    }
}
?>
