    private float minValue, maxValue;
    private bool enableCertificateValidation;
    private HttpClient httpClient;

    public DynamicValueGenerator(float minValue, float maxValue, bool enableCertificateValidation = true) {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.enableCertificateValidation = enableCertificateValidation;

        HttpClientConfig clientConfig = new HttpClientConfig();
        clientConfig.NoVerifySsl = !enableCertificateValidation;
        this.httpClient = new HttpClient(clientConfig);
    }

    public float GetRandomFloat() {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInteger() {
        return (int)UnityEngine.Random.Range(Mathf.CeilToInt(minValue), Mathf.FloorToInt(maxValue));
    }

    public HttpClient CreateHttpRequestBuilder(string url) {
        return httpClient.get_request(url);
    }

    public override string ToString() {
        return $"Dynamic Value Generator: [{minValue}, {maxValue}] - Certificate Validation: {enableCertificateValidation}";
    }

    public void Dispose() {
        this.httpClient.close();
    }
}
```

Please note that creating an HTTP client with certificate validation disabled may be considered a security risk and should only be used for testing or development purposes where it's acceptable to not validate the server's SSL certificate. For production code, always ensure certificate validation is enabled.

