    if (newSize > 1e7 || newSize <= 0) {
        printf("Invalid size, aborting\n");
        exit(EXIT_FAILURE);
    }

    int oldSize = size;
    size = newSize;

    sessions = realloc(sessions, size * sizeof(session_t));
    values = realloc(values, size * sizeof(float));
    timestamps = realloc(timetamps, size * sizeof(double));

    if (!sessions || !values || !timestamps) {
