import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.logging.Logger;

public class StringHasher {
    private static final String MISSING_DATA = "MISSING DATA";
    private MessageDigest md5;
    private Logger logger;

    public StringHasher() throws NoSuchAlgorithmException {
        this.md5 = MessageDigest.getInstance("MD5");
        this.logger = Logger.getLogger(StringHasher.class.getName());
    }

    synchronized public String hashString(String s) {
        if (s == null) return MISSING_DATA;

        byte[] digest = md5.digest(s.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b & 0xff));
        }

        String hashValue = sb.toString();
        // Track duplicate hash values using logging framework
        if (hashValuesTracker.containsKey(hashValue)) {
            logger.warning("Duplicate hash value: " + hashValue);
        } else {
            hashValuesTracker.put(hashValue, s);
        }

        return hashValue;
    }

    private static HashMap<String, String> hashValuesTracker = new HashMap<>();
}
