public class HashCalculator {
    private static final Logger logger = LoggerFactory.getLogger(HashCalculator.class);
    private boolean isAsynchronousEnabled; // Enable/Disable asynchronous processing 

    public String calculateMD5HashJava(String input) {
        try{
            if (isAsynchronousEnabled){
                CompletableFuture.supplyAsync((Supplier<String>) () -> DigestUtils.md5Hex(input))
                    .thenAccept(hash -> System.out.println("The hash is: " + hash));
            } else {
                return DigestUtils.md5Hex(input);
            }
        } catch (Exception e) {
           logger.error("Failed to calculate MD5 hash", e);
        }
    }
}
