C Implementation:
```c
#include <openssl/md5.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#define SEMAPHORE_COUNT 10 // Adjust based on system performance and concurrency requirements

static pthread_mutex_t hashLock = PTHREAD_MUTEX_INITIALIZER;
static sem_t semaphore;

void* calculateMD5HashC(void* input) {
    unsigned char digest[16];
    MD5_CTX context;

    sem_wait(&semaphore); // Acquire the semaphore before calculating hash to avoid becoming a bottleneck

    pthread_mutex_lock(&hashLock); // Ensure thread safety 
    MD5_Init (&context);
    MD5_Update (&context, input, strlen((char*)input));
    MD5_Final (digest, &context);

    pthread_mutex_unlock(&hashLock); // Release the lock after calculating hash 

    sem_post(&semaphore); // Release the semaphore after processing to allow other threads to proceed
}

int main() {
    if (sem_init(&semaphore, 0, SEMAPHORE_COUNT) == -1){
        perror("Failed to initialize semaphore");
    }

    char* input = "Your string here"; // Replace with your actual input data
    pthread_t thread;

    if(pthread_create(&thread, NULL, &calculateMD5HashC, (void*)input)){
        perror("Failed to create a thread");
        return errno;
    }

    if(pthread_join(thread, NULL)){
        perror("Error while joining the threads");
        return errno;
    }

    sem_destroy(&semaphore); // Cleanup after use
    printf("\nMD5 hash calculated successfully\n");
}
```
This code handles thread safety by using a mutex lock around the MD5 calculation part to ensure that only one thread can access it at any given time. It also uses a semaphore with `SEMAPHORE_COUNT` set based on system performance and concurrency requirements, ensuring that the hash calculation is not overloaded with too many threads which could become a bottleneck.
']

