    for (int i = 0; i < n; ++i) {
        if (!isPrime(arr[i])) {
            printf("Error: %d is not a prime number\n", arr[i]);
            return;
        }

        pdu[i].ueInfoTag.rnti = arr[i];
        pdu[i].crcIndicationTag.crcflag = generateCRCFlag();
    }

    // Free the dynamically allocated array here if it's not needed elsewhere
    free(arr);
}
