void addOrUpdateConfig(int id, MACEntityConfig* config) {
    int index = hash(id);

    // Lock the global configs table before accessing it
    pthread_mutex_lock(&configsLock);

    // Check if a configuration with this ID already exists
    for (size_t i = 0; i < configs[index]->count; ++i) {
        MACEntityConfig* existing = configs[index][i];

        if (existing->id == id && paramEqual(config, existing)) {
            // Update the configuration and unlock the lock
            pthread_mutex_unlock(&configsLock);
            return;
        }
    }

    // If no update was performed, add a new configuration
    config->id = id;
    pthread_mutex_init(&config->lock, NULL);
    ++configs[index]->count;
    configs[index] = realloc(configs[index], configs[index]->count * sizeof(*configs[index]));
    configs[index][configs[index]->count - 1] = config;

    // Unlock the global configs table
    pthread_mutex_unlock(&configsLock);
}

// Retrieve a configuration by its ID
