#include <random>
#include <chrono>
#include <iostream>
#include <stdexcept>

namespace MathUtils {
    class RandomGenerator {
        std::mt19937 engine;

        public:
            RandomGenerator(unsigned long long seed = std::chrono::system_clock::now().time_since_epoch().count()) : engine(seed) {}

            int getRandomIntegerInRange(int min, int max){
                if (min > max) {
                    throw std::invalid_argument("The minimum value cannot be greater than the maximum value");
                }
                std::uniform_int_distribution<int> distribution(min, max);
                return distribution(engine);
            }

            double getRandomDoubleInRange(double min, double max){
                if (min > max) {
                    throw std::invalid_argument("The minimum value cannot be greater than the maximum value");
                }
                std::uniform_real_distribution<double> distribution(min, max);
                return distribution(engine);
            }

            bool getRandomBoolean(){
                std::bernoulli_distribution distribution;
                return distribution(engine);
            }

            int getNextNumberFromUniformDistribution(int a, int b){
                std::uniform_int_distribution<int> distribution(a, b - 1);
                return distribution(engine);
            }

            double getNextNumberFromNormalDistribution(double mean, double standardDeviation){
                std::normal_distribution<double> distribution(mean, standardDeviation);
                return distribution(engine);
            }

            double getNextNumberFromExponentialDistribution(double lambda){
                std::exponential_distribution<double> distribution(lambda);
                return distribution(engine);
            }
    };
}

int main() {
    MathUtils::RandomGenerator rg;

    for (int i = 0; i < 10; ++i) {
        std::cout << "Random integer: " << rg.getRandomIntegerInRange(1, 10) << '\n';
    }

    for (int i = 0; i < 10; ++i) {
        std::cout << "Random double: " << rg.getRandomDoubleInRange(1.0, 2.0) << '\n';
    }

    for (int i = 0; i < 10; ++i) {
        std::cout << "Random boolean: " << rg.getRandomBoolean() << '\n';
    }

    for (int i = 0; i < 10; ++i) {
        std::cout << "Next number from uniform distribution: " << rg.getNextNumberFromUniformDistribution(5, 20) << '\n';
    }

    for (int i = 0; i < 10; ++i) {
        std::cout << "Next number from normal distribution: " << rg.getNextNumberFromNormalDistribution(5.0, 2.0) << '\n';
    }

    for (int i = 0; i < 10; ++i) {
        std::cout << "Next number from exponential distribution: " << rg.getNextNumberFromExponentialDistribution(0.5) << '\n';
    }
}
