        this.endOfStream = false;
        this.paused = false;
        this.maxBufferSize = maxBufferSize || 1024 * 1024; // default to 1MB buffer if not specified
    }

    push(chunk) {
        if (this.endOfStream || !chunk || this.paused) return;
        let data = chunk instanceof Buffer ? chunk : new Buffer(chunk);
        this.buffer.push({
            data: data,
            byteOffset: this.byteOffset
        });
        this.byteOffset += data.length;
        this._trimBuffer(); // trim buffer if it exceeds max size
    }

    read(startByte, endByte) {
        let output = new Buffer(endByte - startByte);
        let offset = 0;
        for (let i = 0; i < this.buffer.length && this.buffer[i].byteOffset <= endByte; ++i) {
            if (this.buffer[i].byteOffset + this.buffer[i].data.length > startByte) {
                let sourceStart = Math.max(startByte - this.buffer[i].byteOffset, 0);
                let sourceEnd = Math.min((endByte + 1) - this.buffer[i].byteOffset, this.buffer[i].data.length);
                if (sourceEnd > sourceStart) {
                    this.buffer[i].data.copy(output, offset, sourceStart, sourceEnd);
                    offset += sourceEnd - sourceStart;
                }
            }
        }
        return output;
    }

    _trimBuffer() {
        while (this.byteOffset > this.maxBufferSize) {
            let excessBytes = this.byteOffset - this.maxBufferSize;
            if (excessBytes >= this.buffer[0].data.length) {
                this.byteOffset -= this.buffer[0].data.length;
                this.buffer.shift(); // discard the first buffer entry
            } else {
                let trimmedData = new Buffer(this.buffer[0].data.slice(excessBytes));
                this.buffer[0] = { data: trimmedData, byteOffset: this.byteOffset - trimmedData.length };
            }
        }
    }
}
``` 

This class maintains a list of buffered chunks in order and their relative offsets. It efficiently aggregates the bytes from these chunks into a new buffer using Buffer's `copy` method to minimize memory allocation and copying operations. The `push` method adds data chunks, and the `read` method allows retrieving a specified byte range. 

This class also manages an end-of-stream flag, pause functionality, and discards buffered data when the total size exceeds a maximum limit to prevent excessive memory consumption. It gracefully handles invalid byte ranges or incomplete data segments by returning an empty buffer for these cases. It's designed to minimize latency while maximizing throughput, with careful handling of system dependencies like network latency affecting overall performance.
"]

