use std::env;
use tokio::sync::Mutex;
use tokio::task::spawn_blocking;

struct User {
    username: String,
    password: String,
    email: String,
    role: String,
}

struct DAO {
    // In real world scenario this would be a database connection or network client
    users: Mutex<Vec<User>>,
}

impl DAO {
    async fn update_password(&self, username: &str, new_password: String) {
        let mut users = self.users.lock().await;
        if let Some(user) = users.iter_mut().find(|user| user.username == username) {
            user.password = new_password;
        }
    }

    async fn update_email(&self, username: &str, new_email: String) {
        let mut users = self.users.lock().await;
        if let Some(user) = users.iter_mut().find(|user| user.username == username) {
            user.email = new_email;
        }
    }

    async fn update_role(&self, username: &str, new_role: String) {
        let mut users = self.users.lock().await;
        if let Some(user) = users.iter_mut().find(|user| user.username == username) {
            user.role = new_role;
        }
    }
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 4 {
        println Ан incorrect number of arguments provided.";
        return;
    }

    // Assuming the first argument is the username, second is password and third is email
    let dao = DAO { users: Mutex::new(vec!) };
    let handle1 = tokio::spawn(async move {
        dao.update_password(&args[1], args[2]).await;
    });
    let handle2 = tokio::spawn(async move {
        dao.update_email(&args[1], args[3]).await;
    });

    // await for all tasks to finish
    tokio::join(handle1, handle2);
}
```
