    pthread_mutex_lock(&lock);
    ++counter;
    printf("Thread ID: %lu, Counter Value: %d\n", pthread_self(), counter);
    pthread_mutex_unlock(&lock);
}

int main() {
    pthread_t thread1, thread2;

    if (pthread_create(&thread1, NULL, &threadFunc, NULL) != 0) {
        perror("Failed to create the first thread");
        return 1;
    }

    if (pthread_create(&thread2, NULL, &threadFunc, NULL) != 0) {
        perror("Failed to create the second thread");
        return 1;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    printf("Final counter value: %d\n", counter);
    return 0;
}
