        job = queue->job;
        QueueNode* temp = queue;
        queue = queue->next;
        free(temp);
        queue_size--;
    }
    pthread_mutex_unlock(&mutexQueue);

    return job;
}

ImageMetadata processTIFF(char* filename) {
    TIFF* tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        printf("Error opening file: %s\n", filename);
        return (ImageMetadata){-1, -1};
    }

    uint32 w, h;
    tdata_t buf = _TIFFmalloc(TIFFScanlineSize(tiff));
    ImageMetadata metadata = {0, 0};

    TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &w);
    TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &h);
    uint16 sampleFormat = PHOTOMETRIC_MINISWHITE;  // default value

    for (uint32 row = 0; row < h; row++) {
        TIFFReadScanline(tiff, buf, row);

        if (!metadata.samples_per_pixel) {
            metadata.bits_per_sample = TIFFGetField(tiff, TIFFTAG_SAMPLEFORMAT) & 0xff;

            sampleFormat = TIFFGetField(tiff, TIFFTAG_PHOTOMETRIC);
            if (sampleFormat == PHOTOMETRIC_MINISWHITE || sampleFormat == PHOTOMETRIC_MINISBLACK) {
                metadata.samples_per_pixel = TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL);
            } else if (sampleFormat == PHOTOMETRIC_SEPARATED || sampleFormat == PHOTOMETRIC_YCBCR) {
                metadata.samples_per_pixel = 3;  // RGB or YCbCr
            } else {
                printf("Unsupported photo metric: %d\n", sampleFormat);
                TIFFClose(tiff);
                return (ImageMetadata){-1, -1};
            }
        }
    }

    _TIFFfree(buf);
    TIFFClose(tiff);

    return metadata;
}

void* processFile(void* arg) {
    JobData job = *((JobData*)arg);
    ImageMetadata metadata = processTIFF(job.filename);
    if (metadata.bits_per_sample > 0 && metadata.samples_per_pixel > 0) {
        printf("Processed file: %s\n", job.filename);
    }

    pthread_exit(NULL);
}

void processQueue() {
    while (queue_size) {
        JobData job = dequeue();

        pthread_t thread;
        int result = pthread_create(&thread, NULL, processFile, &job);
        if (result != 0) {
            printf("Error creating thread: %d\n", result);
            continue;
        }
    }
}
```
']

