#include <unistd.h>

struct random_generator {
    int (*generate)(int min, int max);
};

typedef struct random_generator random_gen;

random_gen rand_gen = { 
    .generate = [] (int min, int max) {
        srand(time(NULL));
        return rand() % (max - min + 1) + min;
    }
};

#define MAXDNSLEN 256
#define BUFSIZE 4096
char dns_cache[MAXDNSLEN][BUFSIZE];
int last_dns = -1;

void error(const char *msg) { perror(msg); exit(0); }

struct hostent *gethostbynamecached(char* name) {
    int i;
    for (i = 0; i <= last_dns; ++i) {
        if (strncmp(dns_cache[i], name, BUFSIZE) == 0) return gethostbyname(name); 
    }
    if (last_dns < MAXDNSLEN - 1) strncpy(dns_cache[++last_dns], name, BUFSIZE - 1);
    dns_cache[last_dns][BUFSIZE-1] = 0;
    return gethostbyname(name);
}

int main(void) {
    char buf[4096];
    FILE *file = fopen("records.csv", "r");
    if (file == NULL) error("Error opening file");
    while (fgets(buf, sizeof(buf), file)) {
        char* saveptr;
        char* token = strtok_r(buf, ",", &saveptr);
        double sum = 0.0;
        int count = 0;
        while (token != NULL) {
            errno = 0;
            char *endptr;
            double val = strtod(token, &endptr);
            if (!errno && endptr != token) sum += val, ++count;
            token = strtok_r(NULL, ",", &saveptr);
        }
        double avg = count > 1 ? sum / (double)(count - 1) : 0.0;
        printf("%s%f\n", buf, avg);
    }
    fclose(file);
    char* hostname = "www.example.com";
    struct hostent *server = gethostbynamecached(hostname);
    if (server == NULL) error("ERROR, no such host");
    printf("IP Address: %s\n", inet_ntoa(*((struct in_addr*) server->h_addr)));

    int randomNum = rand_gen.generate(10, 50);
    printf("Random Number Generated: %d\n", randomNum);

    return 0;
}
```
