    unsigned int integer;
    struct Entry *next;
} Entry;

// Function to initialize the entry and link it with the next one in list.
Entry* init_entry(char* array, float number, unsigned int integer, Entry* next) {
    Entry* new_entry = (Entry*) malloc(sizeof(Entry)); // Dynamically allocate memory for each entry.

    new_entry->array = malloc(strlen(array) + 1); 
    strcpy(new_entry->array, array); 
    new_entry->number = number; 
    new_entry->integer = integer; 
    new_entry->next = next; // Point to the next entry in list.

    return new_entry;
}

// Function to generate entries with random data and link them together.
Entry* generate_entries(int count) {
    Entry *head, *tail;

    for (int i = 0; i < count; i++) {
        char array[10]; // Generate a random string of length 10
        float number = rand() % 10 + ((float)(rand() % 100)) / 100.0f; // Random float between 0 and 9.99
        unsigned int integer = rand(); // Unsigned random integer

        snprintf(array, sizeof array, "%d", i); // Convert loop index to string for testing

        Entry* new_entry = init_entry(array, number, integer, NULL); 

        if (i == 0) {
            head = tail = new_entry;
        } else {
            tail->next = new_entry; // Point the last entry to this new one.
            tail = new_entry; // Update tail pointer.
        }
    }

    return head;
}
