typedef struct Node {
    UEStatusReport data;
    struct Node* next;
} Node;

Node *head = NULL;  // Head of the list.

// Function to check if an element exists in the list.
int Exists(UEStatusReport report) {
    Node *temp = head;
    while (temp != NULL) {
        if (temp->data.CellIdentity == report.CellIdentity && temp->data.RNTI == report.RNTI) return 1;
        temp = temp->next;
    }
    return 0;
}

// Function to add a new element to the list.
void Add(UEStatusReport report) {
    if (Exists(report)) return; // Don't add duplicate elements.

    Node *newNode = malloc(sizeof(Node));  // Allocate memory for new node.
    newNode->data = report;  // Set data of the new node as provided UEStatusReport structure.

    if (head == NULL || head->data.ChannelQualityIndication < report.ChannelQualityIndication) {
        newNode->next = head;  // Insert at the beginning for empty list or when report has highest ChannelQualityIndication.
        head = newNode;
    } else {
        Node *current = head;

        while (current->next != NULL && current->next->data.ChannelQualityIndication > report.ChannelQualityIndication) {
            current = current->next; // Go to the next node if it's ChannelQualityIndication is larger than new report.
        }

        newNode->next = current->next;  // Insert between current and previous nodes.
        current->next = newNode;
    }
}

