["The C language doesn't support thread-safe data structures directly, but you can use locks (mutexes) manually if you want to ensure that multiple threads don't access shared memory at the same time. Here is a simplified code example on how you might do it using POSIX threads and error handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

typedef struct {
    int val;
} record_t;

void *allocateAndInitializeMemory(void *hostname) {
    char **addr = (char**)malloc(2 * sizeof(char*));
    if (addr == NULL) return NULL; // Error handling: allocation failure.

    long *offsets = malloc(100 * sizeof(long)); // Allocate memory for offsets array.
    int *keys = calloc(100, sizeof(int)); // Allocate and zero-initialize keys array.

    u_char ip[4]; // Assume IPv4 address. Adjust if required.
    struct hostent *hostInfo;
    char tempBuffer[256];

    strncpy(tempBuffer, (const char*)hostname, sizeof(tempBuffer) - 1);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Create a mutex.

    if ((pthread_mutex_lock(&mutex)) != 0) return NULL; // Lock mutex before accessing shared memory.

    hostInfo = gethostbyname(tempBuffer); // Perform DNS resolution for the given hostname.
    struct in_addr **addr_list = (struct in_addr **)hostInfo->h_addr_list;

    if (!inet_aton(*addr_list[0]->h_addr, ip)) return NULL; // Convert IP address to u_char array.

    record_t *records = malloc(100 * sizeof(record_t)); // Allocate memory for records array.
    if (records == NULL) return NULL; // Error handling: allocation failure.

    srand(time(NULL)); // Seed the random number generator.
    for (int i = 0; i < 100; i++) {
        records[i].val = rand() % 100 + 1; // Set value of each record to a random value within specified range.
    }

    if ((pthread_mutex_unlock(&mutex)) != 0) return NULL; // Unlock mutex after accessing shared memory.

    free(records); // Free dynamically allocated memory before the function ends.
    pthread_exit(NULL); // Exit thread.
}
```
This code sample doesn't handle all the requirements of your problem, because it lacks the necessary error handling and does not use all the required libraries or functions. It only serves as a basic example to illustrate how you might solve this task in C using POSIX threads and manual locking for thread-safe memory access.
