```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <aio.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <stdatomic.h>

typedef struct {
    char* filePath;
    atomic_int lineCount;
} FileInfo;

void *countLines(void *arg) {
    FileInfo *info = (FileInfo *) arg;
    int fd, count = 0;

    if ((fd = open(info->filePath, O_RDONLY)) == -1) {
        printf("Could not open file %s\n", info->filePath);
        return NULL;
    }

    struct stat st;
    fstat(fd, &st);

    off_t size = st.st_size;
    char *buffer = malloc(size + 1);

    if (read(fd, buffer, size) == -1) {
        printf("Could not read file %s\n", info->filePath);
        free(buffer);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        if (buffer[i] == '\n') {
            ++count;
        }
    }

    info->lineCount = count;

    free(buffer);
    close(fd);
    return NULL;
}

void processFilesAsync(char** filePaths, int numOfFiles) {
    pthread_t* threads = malloc(numOfFiles * sizeof(pthread_t));
    FileInfo* infos = malloc(numOfFiles * sizeof(FileInfo));

    clock_t begin = clock();  // start timer

    for (int i = 0; i < numOfFiles; ++i) {
        infos[i].filePath = filePaths[i];
        if (pthread_create(&threads[i], NULL, countLines, &infos[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    int totalCount = 0;
    for (int i = 0; i < numOfFiles; ++i) {
        pthread_join(threads[i], NULL);
        totalCount += infos[i].lineCount;
    }

    clock_t end = clock();  // end timer
    double timeSpent = (double)(end - begin) / CLOCKS_PER_SEC;

    printf("Total line count: %d\n", totalCount);
    printf("Average processing time per file: %f\n", timeSpent/numOfFiles);

    free(infos);
    free(threads);
}
```
You can use this function by calling `processFilesAsync` with an array of file paths and the number of files. This program assumes that all file paths are valid, i.e., no validation is performed for simplicity. Error handling for invalid file paths or network failures is minimal in this example. Also, the code does not retry on failure to read a file, nor does it skip over invalid files.
']

