["Here is an example of how you could implement this task in C using POSIX threads (pthreads) for synchronization and error checking in the allocation/deallocation part.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

typedef struct Record {
    int value;
    long *offset;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void fillRecords(Record *records, size_t numRecords, long *offsets, size_t numOffsets, int minVal, int maxVal) {
    assert(maxVal >= minVal);

    for (size_t i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&mutex);

        records[i].value = rand() % (maxVal - minVal + 1) + minVal;

        if (records[i].value % 3 == 0 && numOffsets > 0) {
            if (!records[i].offset) {
                records[i].offset = malloc(sizeof(long));
                assert(records[i].offset != NULL);
            }
            *records[i].offset = i % numOffsets;
        } else {
            if (records[i].offset) {
                free(records[i].offset);
                records[i].offset = NULL;
            }
        }

        pthread_mutex_unlock(&mutex);
    }
}

void* threadFunc(void *arg) {
    Record **recordsPair = (Record **)arg;
    size_t recordsSize = ((size_t *)recordsPair)[1];
    Record *records = recordsPair[0];

    fillRecords(records, recordsSize, NULL, 0, 0, RAND_MAX);

    return NULL;
}

#define MAX_RECORDS 1e6
#define MAX_MEMORY (50.0 / 100 * sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE))
int main() {
    size_t numOffsets = (size_t)(MAX_MEMORY / sizeof(long));
    long *offsets = malloc(numOffsets * sizeof(long));
    assert(offsets != NULL);

    pthread_attr_t attr;
    pthread_attr_init(&attr);

    int numThreads = 10; // Adjust as necessary
    pthread_t threads[numThreads];
    size_t recordsPerThread = MAX_RECORDS / numThreads;

    for (int i = 0; i < numThreads; ++i) {
        Record *records = malloc(recordsPerThread * sizeof(Record));
        assert(records != NULL);

        size_t recordsPair[2] = {(size_t)records, recordsPerThread};
        pthread_create(&threads[i], &attr, threadFunc, (void *)&recordsPair);
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(offsets);

    return 0;
}
```
