#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node *head = NULL;  // Initialize head as empty.

void insert(int rnti, /* Other fields */) {
    if (search(rnti)) {
        printf("Error: Duplicate RNTI\n");
        return;
    }

    Node* new_node = (Node*) malloc(sizeof(Node));  // Create a new node.

    if (new_node == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    new_node->data.RNTI = rnti;
    // Set other fields...

    new_node->next = head;  // Point the new node to where head is pointing.
    head = new_node;        // Now head points to the new node.
}

int search(int rnti) {
    Node* current = head;

    while (current != NULL) {
        if (current->data.RNTI == rnti) return 1;  // RNTI found, return true.

        current = current->next;  // Go to the next node in the list.
    }

    return 0;  // RNTI not found, return false.
}

void delete(int rnti) {
    if (head == NULL || head->data.RNTI == rnti) {
        Node* next_node = NULL;

        if (head != NULL) {  // If the node to be deleted is not the last one.
            next_node = head->next;
        }

        free(head);  // Deallocate memory of current node.
        head = next_node;  
    } else {
        Node* prev = head;
        Node* current = head->next;

        while (current != NULL) {
            if (current->data.RNTI == rnti) {  // If RNTI is found, break the link.
                prev->next = current->next;

                free(current);  // Deallocate memory of current node.
                return;
            }

            prev = current;
            current = current->next;  
        }
    }
}
```
Please note that this is a simple and basic linked list implementation, which has linear search time complexity O(n) in worst case for insertion and deletion operations. A more efficient solution could involve using balanced binary search trees or hash maps (with proper collision handling). Also error checking and memory management should be handled more carefully in production code.
