#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

Record* recordArray = NULL; 
int* keyArray = NULL; 
long* offsetArray = NULL; 

size_t arraySize = 0; 
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

void setupArrays(size_t size) {
    if (arraySize != size) {
        pthread_mutex_lock(&lock);

        // Allocate memory for arrays
        recordArray = calloc(size, sizeof(Record));
        keyArray = malloc(size * sizeof(int));
        offsetArray = malloc(size * sizeof(long));

        if (recordArray == NULL || keyArray == NULL || offsetArray == NULL) {
            printf("Failed to allocate memory.\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        arraySize = size;

        pthread_mutex_unlock(&lock);
    }
}

void initializeArrays(int start, int end) {
    if (start < 0 || end >= arraySize || start > end) {
        printf("Invalid range.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    for (size_t i = start; i <= end; ++i) {
        recordArray[i].value = keyArray[i] = i * 10;
    }

    pthread_mutex_unlock(&lock);
}

void* loggingThread(void* arg) {
    int index = *((int*)arg);

    printf("Accessing record at index %d\n", index);

    if (index < 0 || index >= arraySize) {
        printf("Index out of range.\n");
        return NULL; 
    }

    pthread_mutex_lock(&lock);
    int value = recordArray[index].value;
    pthread_mutex_unlock(&lock);

    printf("Record value at index %d is %d\n", index, value);

    return NULL; 
}
```

This code creates three arrays (recordArray, keyArray and offsetArray) with a specific size. It also provides an initializer for these arrays in a thread-safe manner. A logging function logs accesses to the record array. 

