void* initialize(long offset[], int keys[], record_t **records, size_t count) {
    srand(time(NULL));  // Seed the random number generator

    *offset = malloc(sizeof(long)*count);
    if (*offset == NULL) return "Memory allocation error";

    *keys = malloc(sizeof(int)*count);
    if (*keys == NULL) return "Memory allocation error";

    *records = malloc(sizeof(record_t)*count);
    if (*records == NULL) return "Memory allocation error";

    // Initialize offset and keys arrays
    for (size_t i = 0; i < count; ++i) {
        (*offset)[i] = rand() % RAND_MAX;  // Random long value

        int key;
        do {
            key = rand();  // Random unique integer key
        } while (bsearch(&key, *keys, i, sizeof(int), cmpfunc));

        (*keys)[i] = key;
    }

    // Initialize records array
    for (size_t i = 0; i < count; ++i) {
        char buffer[16];  // Arbitrary buffer size for string representation of integer keys
        sprintf(buffer, "KEY-%d", (*keys)[i]);

        (*records)[i].value = rand() % RAND_MAX;  // Random int value

        (*records)[i].key = malloc(strlen(buffer) + 1);
        if ((*records)[i].key == NULL) return "Memory allocation error";

        strcpy((*records)[i].key, buffer);  // Copy null-terminated string into record
    }

    return NULL;
}

void copy(record_t *dest, const record_t *src) {
    pthread_mutex_lock(&lock);
    memcpy(dest, src, sizeof(record_t));  // Use bitwise operations for copying structs
