    hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

// Hash table entry for RNTI
typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    unsigned long key;
    struct Entry* next;
} Entry;

// Initialize the hashtable and the lock
#define SIZE 211
Entry** hashTable = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int size = 0; // Current number of entries

void initHashTable() {
    hashTable = malloc(SIZE * sizeof(Entry*));
    assert(hashTable != NULL);
    memset(hashTable, 0, SIZE * sizeof(Entry*));
}

// Add an entry to the hashtable
int addToHashtable(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    unsigned long key = hash(pdu->RNTI); // Compute the hash key
    int index = key % SIZE; // Get the array index using modulus

    pthread_mutex_lock(&lock); // Lock the table
    Entry* entry = malloc(sizeof(Entry)); 
    assert(entry != NULL);
    entry->pdu = pdu;
    entry->key = key;
    entry->next = hashTable[index]; // Add the new entry at the start of the list
    hashTable[index] = entry;
    ++size; 
    pthread_mutex_unlock(&lock); // Unlock the table
    return 1;
}

// Remove an entry from the hashtable by RNTI value
int removeFromHashtable(int rnti) {
    unsigned long key = hash(rnti); // Compute the hash key
    int index = key % SIZE; // Get the array index using modulus

    pthread_mutex_lock(&lock); // Lock the table
    Entry** prev = &hashTable[index]; 
    while (*prev) {
        if ((*prev)->pdu->RNTI == rnti) {
            Entry* next = (*prev)->next;
            free(*prev);
            *prev = next; // Remove the entry from the list
            --size; 
            pthread_mutex_unlock(&lock); // Unlock the table
            return 1;
        }
        prev = &((*prev)->next);
    }
    pthread_mutex_unlock(&lock); // Unlock the table
    return 0;
}
```
This is a simplified example of how you can create a hash table to manage your data structure in C. It doesn't include all the features you mentioned, such as dynamic resizing of the hashtable or garbage collection for stale entries, but it should give you a good starting point. For a full solution, you would need to implement these features and integrate with an external source for periodic updates and synchronization. 

