Node* create_node(char* data) {
    Node* new_node = malloc(sizeof(Node));

    if (new_node == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        exit(-1);
    }

    new_node->data = strdup(data); // duplicate the string
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Node* node_to_insert) {
    if (*head == NULL) {
        *head = node_to_insert;
    } else {
        Node* current = *head;

        // avoid duplicates
        while (current != NULL && strcmp(current->data, node_to_insert->data) != 0) {
            if (current->next == NULL) {
                break;
            } else {
                current = current->next;
            }
        }

        // insert at the end
        if (strcmp(current->data, node_to_insert->data) != 0) {
            printf("Duplicate found '%s'. Skipping...\n", node_to_insert->data);
            free(node_to_insert->data); // free duplicated string
            free(node_to_insert); // free duplicated node
        } else {
            current->next = node_to_insert;
        }
    }
}
```
