['This is quite an extensive task with many sub-tasks which are beyond the capacity of this text-based system to solve comprehensively. However, I can give you a very basic example of how you might approach fetching data over HTTP in C and parsing JSON using only standard library functions. 

```c
#include <stdio.h>
#include <curl/curl.h>
#include <string.h>
#include <json-c/json.h>

struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(!ptr) {
        printf("not enough memory\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

char* fetch_data(const char *url) {
    CURL *curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        return NULL;
    }

    struct MemoryStruct chunk;
    chunk.memory = malloc(1);  /* will be grown as needed by the realloc above */
    chunk.size = 0;    /* no data at this point */

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);
    curl_easy_perform(curl);

    return chunk.memory;
}

int main() {
    char *response = fetch_data("https://api.github.com/users/octocat");

    struct json_object *parsed_json;
    struct json_object *name;
    parsed_json = json_tokener_parse(response);

    json_object_object_get_ex(parsed_json, "login", &name);
    printf("The login of the user is: %s\n", json_object_get_string(name));

    /* don't forget to free resources */
    curl_global_cleanup();
    free(response);
    return 0;
}
```
