#include <openssl/sha.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define the ICD structure
typedef struct {
    char* id;
    long timestamp;
    int* sensor_readings;
} ICD;

// Use OpenSSL SHA256 as custom hash function for rapid lookups
unsigned char* hash(const char *str) {
    unsigned char *md = malloc(SHA256_DIGEST_LENGTH);
    SHA256((unsigned char*) str, strlen(str), md);
    return md;
}

// Use pthread mutex to protect against data races and corruption
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ICD* icd_collection[1000000] = {NULL}; // 1 million slots for ICDs

// Function to insert or update an ICD
int insert_or_update(const char *id, long timestamp, int* sensor_readings) {
    unsigned char* key = hash(id);

    pthread_mutex_lock(&lock);

    // Check if id already exists in collection
    for (size_t i = 0; i < 1000000; ++i) {
        if (icd_collection[i] != NULL && memcmp(hash(icd_collection[i]->id), key, SHA256_DIGEST_LENGTH) == 0) {
            // Update existing ICD
            icd_collection[i]->timestamp = timestamp;
            free(icd_collection[i]->sensor_readings);
            icd_collection[i]->sensor_readings = sensor_readings;

            pthread_mutex_unlock(&lock);
            return 0; // Updated existing ICD
        }
    }

    // Create new ICD if id doesn't exist in collection yet
    for (size_t i = 0; i < 1000000; ++i) {
        if (icd_collection[i] == NULL) {
            icd_collection[i] = malloc(sizeof(ICD)); // Allocate memory safely
            if (icd_collection[i] == NULL) {
                pthread_mutex_unlock(&lock);
                return -1; // Failed to allocate memory
            }

            icd_collection[i]->id = strdup(id); // Duplicate string safely
            if (icd_collection[i]->id == NULL) {
                free(icd_collection[i]);
                pthread_mutex_unlock(&lock);
                return -1; // Failed to duplicate string
            }

            icd_collection[i]->timestamp = timestamp;
            icd_collection[i]->sensor_readings = sensor_readings;

            pthread_mutex_unlock(&lock);
            return 1; // Inserted new ICD
        }
    }

    pthread_mutex_unlock(&lock);
    return -2; // No space left in collection
}
```

