#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    size_t* offset;
    time_t timestamp;
} Record;

typedef struct DataManager {
    Record** records;
    int* keys;
    pthread_mutex_t lock;
    size_t recordCount;
    size_t keyCount;
    size_t memoryLimit;
    size_t peakMemoryUsage;
} DataManager;

void initializeData(DataManager* manager, int initialSize) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->records = (Record**)calloc(initialSize, sizeof(Record*));
    manager->keys = (int*)calloc(initialSize, sizeof(int));
    manager->recordCount = 0;
    manager->keyCount = 0;
    manager->memoryLimit = 1024 * 1024 * 512; // 512MB limit
    manager->peakMemoryUsage = 0;
}

void addRecord(DataManager* manager, int key, Record* record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->recordCount >= manager->memoryLimit || manager->keyCount == manager->recordCount) {
        // If memory limit is reached or collision occurs, expand the arrays.
        size_t newSize = manager->recordCount * 2;
        Record** newRecords = (Record**)realloc(manager->records, newSize * sizeof(Record*));
        int* newKeys = (int*)realloc(manager->keys, newSize * sizeof(int));

        if (!newRecords || !newKeys) {
            // Not enough memory to expand. Clean up and return.
            free(newRecords);
            free(newKeys);
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->records = newRecords;
        manager->keys = newKeys;
    }

    // Add the record.
    manager->records[manager->recordCount] = record;
    manager->keys[manager->keyCount++] = key;
    manager->recordCount++;

    size_t currentMemoryUsage = manager->recordCount * sizeof(Record*) + manager->keyCount * sizeof(int);
    if (currentMemoryUsage > manager->peakMemoryUsage) {
        manager->peakMemoryUsage = currentMemoryUsage;
    }

    pthread_mutex_unlock(&manager->lock);
}

Record* createRandomRecord() {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    srand(time(NULL));
    int randomValue = rand();

    // Assuming that offset is set somewhere else.
    // This function doesn't manage it because it depends on your design and requirements.

    record->value = randomValue;
    record->timestamp = time(NULL);

    return record;
}
