```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdio.h>

typedef struct Node {
    char data;
    struct Node* next;
} Node;

Node *head = NULL, *tail = NULL;
int size = 0, max_size;

void init(char ch) {
    head = tail = (Node*)malloc(sizeof(Node));
    head->data = ch;
    head->next = NULL;
    size = 1;
}

void insert(int position, char data){
   if (position < 0 || position > size) return;  // Edge case handling

   Node* temp = (Node*)malloc(sizeof(Node));
   temp->data = data;

   if(position == 0){
      temp->next = head;
      head = temp;
   } else {
      Node *current = head;
      for(int i=0;i<position-1;i++) current = current->next;
      temp->next = current->next;
      current->next = temp;
   }

   size++;
}

void deleteNode(int position){
   if (position < 0 || position >= size) return; // Edge case handling
   Node *temp = head, *prev = NULL;

   for(int i=0;i<position;i++){
      prev = temp;
      temp = temp->next;
   }

   if(!prev) { 
      head = temp->next;
   } else {
      prev->next = temp->next;
   }

   free(temp);
   size--;
}

void printReverse(Node* node){
    if (node == NULL) return;

    printReverse(node->next);
    printf("%c ", node->data);
}

int main() {
    srand((unsigned int)time(NULL));
    max_size = 50; // Set maximum size for testing purposes
    init('a'); 

    char ch = 'b';
    insert(1,ch++);
    insert(2,ch++);

    printReverse(head);
}
```

Note: This code assumes a zero-based indexing scheme for position. It also assumes that we want to add nodes before the node at given position and not after it. The delete function removes the node from the specified position, if such a node exists, and adjusts surrounding links accordingly.
