['```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

pid_t childPid;
int status = 0;

void handleTermination() {
    if (childPid > 0) {
        kill(childPid, SIGTERM);
        waitpid(childPid, &status, 0);
    }
}

int executeCommand(char* command) {
    childPid = fork();

    if (childPid == -1) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (childPid == 0) {
        if (execl("/bin/sh", "sh", "-c", command, NULL) < 0) {
            perror("exec failed");
            exit(EXIT_FAILURE);
        }
    } else {
        signal(SIGINT, handleTermination);
        signal(SIGHUP, handleTermination);
        while (waitpid(-1, &status, WNOHANG) == 0) {
            usleep(500000); // sleep for 0.5s to reduce CPU usage
        }
    }

    return status;
}
```
This C function `executeCommand` handles executing a given command in the background using fork and waitpid. The child process is properly detached from the parent, and resources are properly managed on termination or unexpected events. Resource exhaustion errors can be handled by setting up signal handlers that kill the child process when the parent receives an interrupt (SIGINT) or hangup (SIGHUP). This function also includes a sleep mechanism to reduce CPU usage during the wait period.
