```c
#include <jansson.h>
#include <string.h>

int validate_json(const char *payload, int minData, int maxData, int metadataRange) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return 0;
    }

    // Check for mandatory fields
    if(!json_is_object(root)) {
        fprintf(stderr, "Root is not an object\n");
        json_decref(root);
        return 0;
    }

    json_t *request_id = json_object_get(root, "request_id");
    if(!json_is_string(request_id)) {
        fprintf(stderr, "'request_id' is not a string\n");
        json_decref(root);
        return 0;
    }

    json_t *status = json_object_get(root, "status");
    if(!json_is_string(status) || 
       (strcmp(json_string_value(status), "success") && strcmp(json_string_value(status), "error") && strcmp(json_string_value(status), "warning"))) {
        fprintf(stderr, "'status' is not a valid string\n");
        json_decref(root);
        return 0;
    }

    json_t *data = json_object_get(root, "data");
    if(!json_is_integer(data) || json_integer_value(data) < minData || json_integer_value(data) > maxData) {
        fprintf(stderr, "'data' is not an integer or out of range\n");
        json_decref(root);
        return 0;
    }

    // Check optional field metadata
    json_t *metadata = json_object_get(root, "metadata");
    if(metadata) {
        if(!json_is_object(metadata)) {
            fprintf(stderr, "'metadata' is not an object\n");
            json_decref(root);
            return 0;
        }

        const char *key;
        json_t *value;
        size_t index = 0;
        json_object_foreach(metadata, key, value) {
            if(!json_is_string(value) && !json_is_integer(value)) {
                fprintf(stderr, "Metadata contains invalid values\n");
                json_decref(root);
                return 0;
            } else if(json_is_integer(value) && (json_integer_value(value) < -metadataRange || json_integer_value(value) > metadataRange)) {
                fprintf(stderr, "Metadata contains out-of-range values\n");
                json_decref(root);
                return 0;
            }

            if(++index > 5) {
                fprintf(stderr, "Too many metadata entries\n");
                json_decref(root);
                return 0;
            }
        }
    }

    // If we've made it this far, the JSON is valid.
    json_decref(root);
    return 1;
}
```
This function first checks if the root of the JSON object is an object and then checks for each mandatory field: `request_id` as a string, `status` as either "success", "error" or "warning", and `data` as an integer. It also checks if optional fields `metadata` exists and if its values are strings or integers within a specified range.
