using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;

public class UrlVerificationService : IUrlVerificationService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<UrlVerificationService> _logger;

    public UrlVerificationService(HttpClient httpClient, ILogger<UrlVerificationService> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task VerifyUrlsAsync(IEnumerable<string> urls)
    {
        var tasks = urls.Select(VerifyUrlAsync).ToList();

        try
        {
            await Task.WhenAll(tasks);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while verifying URLs.");
        }
    }

    private async Task VerifyUrlAsync(string url)
    {
        var host = new Uri(url).Host;

        try
        {
            using (var requestMessage = new HttpRequestMessage(HttpMethod.Head, url))
            {
                var response = await _httpClient.SendAsync(requestMessage);

                if (!response.IsSuccessStatusCode) 
                    throw new Exception("Unsuccessful status code");

                using (var cert = new X509Certificate2(await response.Content.ReadAsByteArrayAsync()))
                {
                    if (!cert.Verify()) 
                        throw new InvalidOperationException("Certificate verification failed.");

                    _logger.LogInformation($"Successfully verified SSL/TLS certificate for host: {host}");
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to verify URL: {url}");
        }
    }
}
```
This code creates an asynchronous service that verifies SSL/TLS certificates for a list of URLs using the `X509Certificate2` class from the `System.Security.Cryptography.X509Certificates` namespace. It uses a `HttpClient` instance to make HEAD requests to each URL, and then reads the response content as byte array to create an X509Certificate2 object.

