```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class CryptoManager : IDisposable
{
    private readonly ILogger _logger;
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly HMAC _hmac;

    public CryptoManager(ILogger logger, byte[] key, byte[] iv)
    {
        _logger = logger;
        _key = key;
        _iv = iv;
        _hmac = new HMACSHA256(_key);
    }

    public void Dispose()
    {
        _hmac.Dispose();
    }

    public byte[] DecryptCbc(byte[] ciphertext)
    {
        using (var aes = new AesCryptoServiceProvider())
        {
            aes.Key = _key;
            aes.IV = _iv;

            var decrypter = aes.CreateDecryptor(aes.Key, aes.IV);
            using (var memoryStream = new MemoryStream(ciphertext))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, decrypter, CryptoStreamMode.Read))
                {
                    var plainTextBytes = new byte[ciphertext.Length];
                    var byteCount = cryptoStream.Read(plainTextBytes, 0, plainTextBytes.Length);
                    _logger.Debug("Decrypted: " + Encoding.UTF8.GetString(plainTextBytes, 0, byteCount));

                    // Validate HMAC
                    var receivedHmac = new byte[32];
                    memoryStream.Read(receivedHmac, 0, 32);
                    var computedHmac = _hmac.ComputeHash(plainTextBytes, 0, plainTextBytes.Length - 32);

                    if (!computedHmac.SequenceEqual(receivedHmac))
                        throw new CryptographicException("MAC validation failed.");

                    return plainTextBytes;
                }
            }
        }
    }
}
```

