        exec(command, (error, stdout, stderr) => {
            if (error) {
                console.warn(error);
                reject(error);
            } else {
                resolve(stdout ? stdout : stderr);
            }
        });
    });
}
```

Using Redis as a cache and setting up an express server to handle http requests:
```javascript
const redis = require('redis');
const client = redis.createClient();
const app = require('express')();

app.get('/uptime', (req, res) => {
    // Check Redis cache first
    client.get('uptime', async (err, reply) => {
        if(reply){ 
            return res.send(JSON.parse(reply));
        } else {
            try{
                const uptime = await executeShellCommand('uptime');
                // Cache for 5 minutes (300 seconds)
                client.setex('uptime', 300, JSON.stringify(uptime));
                return res.send(uptime);
            } catch(e){
                console.error("Error fetching uptime", e);
                return res.status(500).send();
            }
        }
    });
});

app.listen(3000, () => {
    console.log('Server running on http://localhost:3000');
});
```
This is a very simplified example and doesn't cover all the points you requested but hopefully it gives an idea of how to approach your request. For more detailed solutions, consider dividing tasks between different microservices (uptime retrieval service, monitoring dashboard, etc.) using RESTful API calls. 

