    void parseJson(const nlohmann::json &jsonData) override {
        // Implementation specific to version 1
    }
};

class V2JsonParser : public JsonParserFactory {
    void parseJson(const nlohmann::json &jsonData) override {
        // Implementation specific to version 2
    }
};

// Dynamic registry of JSON parser factories, using Boost.Thread for thread safety
class Registry {
public:
    static JsonParserFactory* get(int version){
        boost::lock_guard<boost::mutex> lock(m); // Locking to ensure thread-safety
        if (!registry_.count(version)) { 
            switch (version) {
                case 1: registry_[version] = new V1JsonParser(); break;
                case 2: registry_[version] = new V2JsonParser(); break;
                default: throw std::invalid_argument("Invalid version");
            }
        }
        return registry_[version];
    }
private:
    static boost::mutex m; // Mutex for thread safety
    static std::unordered_map<int, JsonParserFactory*> registry_;  // Dynamic registry of factories
};
```
