#define MAX_RETRY_ATTEMPTS 10
#define MIN_SEED 1
#define MAX_MAXCRCFLAG 1.0f
#define RETRY_INTERVAL 1 // seconds

int allocateFAPI_CRC_INDICATION_PDU(unsigned int numStructs, unsigned int seed, float maxCrflag) {
    if (numStructs == 0 || errno == EINVAL) return -1;
    else if (seed < MIN_SEED || errno == ERANGE) return -2;
    else if (maxCrflag > MAX_MAXCRCFLAG || errno == ERANGE) return -3;

    srand(seed);

    int retryAttempts = 0;
    FAPI_CRC_INDICATION_PDU_T *pduList = NULL;

    while (retryAttempts < MAX_RETRY_ATTEMPTS) {
        pduList = malloc(numStructs * sizeof(FAPI_CRC_INDICATION_PDU_T));

        if (pduList == NULL && errno == ENOMEM) {
            sleep(RETRY_INTERVAL);
            ++retryAttempts;
        } else break;
    }

    if (pduList != NULL) {
        for (int i = 0; i < numStructs; ++i) {
            pduList[i].crcTag.CRCFLAG = rand() % ((int)(maxCrflag * 1000) + 1); // Random number between 0 and maxCrflag
        }
    } else return -4; // Failed to allocate memory after MAX_RETRY_ATTEMPTS

    // Handle pduList as needed...

    free(pduList);
}
