                                           size_t offsets_size, 
                                           size_t records_size, 
                                           int min, 
                                           int max) {
    data_structures_t *data = malloc(sizeof(*data));
    if (!data) return NULL; // handle allocation failure gracefully

    // allocate memory and initialize keys array
    atomic_int *keys = calloc(keys_size, sizeof(atomic_int));
    if (!keys) { free(data); return NULL; } 

    // do the same for offsets array
    long *offsets = malloc(offsets_size * sizeof(*offsets));
    if (!offsets) { free(keys); free(data); return NULL; }

    // and records array
    record_t *records = calloc(records_size, sizeof(*records));
    if (!records) { free(offsets); free(keys); free(data); return NULL; }

    srand(time(NULL));

    // initialize each record with a random value within the specified range
    for (int i = 0; i < records_size; ++i)
        records[i].value = rand() % (max - min + 1) + min;

    data->keys = keys;
    data->offsets = offsets;
    data->records = records;
