        records[i].value = value;
    }

    fwrite(records, sizeof(Record), recordCount, file); // Write to file
    fflush(file); // Flush the data to be sure it's written to disk
    flock(fileno(file), LOCK_UN); // Unlock file before closing it

    fclose(file); // Close file

    pthread_mutex_unlock(mtx); // Release lock after modifying shared resource

