typedef struct {
    float f_value;
    char* buffer;
    void* data;
} CustomObject;

void* allocateAndInitialize(void *arg) {
    // Obtain arguments
    int objectSize = *((int*) arg);

    // Allocate memory
    CustomObject *obj = (CustomObject *) malloc(objectSize);
    if (obj == NULL) return NULL;  // Memory allocation failed

    srand(time(NULL));
    obj->f_value = ((float) rand() / RAND_MAX) * (max - min) + min;  // Random float value in range [min, max]

    char alphabet[] = "abcdefghijklmnopqrstuvwxyz";
    obj->buffer = malloc(objectSize);
    if (obj->buffer == NULL) {
        free(obj);  // Memory allocation failed
        return NULL;  
    }

    for (int i = 0; i < objectSize - sizeof(float) - sizeof(void*); ++i) {
        obj->buffer[i] = alphabet[rand() % (sizeof(alphabet) - 1)];  // Random character from alphabet
    }

    return obj;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int threadArgs[NUM_THREADS] = {OBJECT_SIZE_1, OBJECT_SIZE_2, ...};  // Replace with actual sizes

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, allocateAndInitialize, &threadArgs[i]);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        void* returnValue;
        pthread_join(threads[i], &returnValue);

        if (returnValue == NULL) {
            // Handle memory allocation error
        } else {
            CustomObject *obj = (CustomObject *) returnValue;

            // Use the object...

            free(obj->buffer);  // Remember to cleanup allocated resources
            free(obj);
        }
    }

    return 0;
}
```

