["Here's an implementation in C that meets the requirements you have specified. Note that this code uses `pthread_mutex` for synchronization, but it assumes that the record structure is thread-safe itself, as there isn't a lock around every operation on the record data (e.g., setting value or offset). This example also ignores system memory pointers and focuses entirely on the allocation of `record` objects:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
    long* offset;
} record_t;

typedef struct list {
    pthread_mutex_t mutex;
    record_t* records;
    size_t count;
    size_t capacity;
} list_t;

list_t* createList(size_t initialCapacity) {
    list_t* list = malloc(sizeof(list_t));
    list->records = calloc(initialCapacity, sizeof(record_t));
    list->count = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroyList(list_t* list) {
    clearList(list);
    free(list->records);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int reserveSpaceInList(list_t* list, size_t newCapacity) {
    record_t* records = realloc(list->records, newCapacity * sizeof(record_t));
    if (records == NULL) return 0; // Allocation failed

    list->records = records;
    list->capacity = newCapacity;
    return 1; // Success
}

int growList(list_t* list, size_t minSize) {
    if (minSize > list->capacity * 2) {
        if (!reserveSpaceInList(list, minSize)) return 0; // Failed to allocate
    } else if (list->capacity < 16) {
        if (!reserveSpaceInList(list, 16)) return 0; // Failed to allocate
    } else if (!reserveSpaceInList(list, list->capacity * 2)) {
        return 0; // Failed to allocate
    }

    return 1; // Success
}

void clearList(list_t* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i].offset); // Assuming offset is heap-allocated memory
        list->records[i].value = 0;
        list->records[i].offset = NULL;
    }

    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

int addRecordToList(list_t* list, int value) {
    if (list->count == list->capacity && !growList(list, list->count + 1)) return 0; // Failed to grow

    pthread_mutex_lock(&list->mutex);
    list->records[list->count].value = value;
    list->records[list->count].offset = NULL;
    ++list->count;
    pthread_mutex_unlock(&list->mutex);
    return 1; // Success
}
```

This code provides the basic functionality for a dynamic list of `record` objects. You can enhance it to meet your specific needs (e.g., setting offsets, handling edge cases). This is just a starting point and could be extended with more error checking and optimizations as needed. The key idea here is managing memory in a safe and efficient manner while allowing for dynamic growth and shrinking of the list.
"]

