To add a bundle:

```c
void addBundle(BundleManager* mgr, ResourceBundle *bundle) {
    if (!bundle || !bundle->mac_entity_id){
        printf("Invalid bundle or mac entity id");
        return;
    }
    pthread_mutex_lock(&mgr->lock);
    int index = hash(bundle->mac_entity_id) % TABLE_SIZE; // assuming hash function is defined 
    while (mgr->bundles[index] != NULL && mgr->bundles[index]->mac_entity_id != NULL){
        index = (index + 1) % TABLE_SIZE;
    }
    mgr->bundles[index] = bundle;
    pthread_mutex_unlock(&mgr->lock);
}
