            Map<String, Integer> hashCounts = new HashMap<>();

            for (int i = 0; i < strings.size(); i += BATCH_SIZE) {
                List<String> batch = strings.subList(i, Math.min(i + BATCH_SIZE, strings.size()));

                int uniqueHashCount = 0;
                int duplicateHashCount = 0;
                for (String string : batch) {
                    if (!filterByRegexPatterns(string)) continue; // skip string if it does not pass regex filter

                    String hash = getSHA256Hash(string);
                    if (hash != null) {
                        Integer count = hashCounts.getOrDefault(hash, 0);
                        if (count == 1) duplicateHashCount++; // skip duplicates

                        uniqueHashCount++;
                        hashCounts.put(hash, count + 1);
