```csharp
using System;
using System.IO;
using System.Xml.Linq;
using System.Threading;
using System.Collections.Generic;

public class WorkspaceManager
{
    private static readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public void ManageWorkspace(XDocument document, string elementName)
    {
        string logLevel = Environment.GetEnvironmentVariable("LOG_LEVEL");
        Logger logger;

        try 
        {
            logger = new Logger(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "pipeline.log"), logLevel);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error creating logger: " + ex.Message);
            return;
        }

        var element = document.Element(elementName);

        if (element == null)
        {
            logger.LogError($"Element '{elementName}' not found in the XML document");
            return;
        }

        string workspacePath = Environment.GetEnvironmentVariable("WORKSPACE_PATH") ?? "/var/opt/workspace";
        string uniqueWorkspace = $"{DateTime.Now:yyyyMMddHHmmssfff}-{element.Value}";

        try 
        {
            if (!Directory.Exists(Path.Combine(workspacePath, uniqueWorkspace)))
            {
                Directory.CreateDirectory(Path.Combine(workspacePath, uniqueWorkspace));
                logger.LogInfo($"Created workspace directory '{uniqueWorkspace}' in path: {workspacePath}");

                _lock.EnterWriteLock();
                Environment.SetEnvironmentVariable("WORKSPACE_PATH", Path.Combine(workspacePath, uniqueWorkspace));
                _lock.ExitWriteLock();
            } 
        } 
        catch (Exception ex) 
        {
            logger.LogError($"Error creating workspace directory: {ex.Message}");
            return;
        }

        logger.LogInfo("Workspace setup completed successfully");
    }
}
```

You'll need to define the Logger class as a simple wrapper around file-based logging for simplicity:

```csharp
public class Logger 
{
    private string _logFilePath;
    private string _logLevel;

    public Logger(string logFilePath, string logLevel)
    {
        if (string.IsNullOrEmpty(logFilePath))
            throw new ArgumentException("Log file path cannot be null or empty");

        _logFilePath = logFilePath;
        _logLevel = logLevel;
    }

    public void LogInfo(string message) 
    {
        if (_logLevel != "INFO") return;

        WriteLogEntry($"[INFO] {DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}");
    }

    public void LogDebug(string message) 
    {
        if (_logLevel != "DEBUG") return;

        WriteLogEntry($"[DEBUG] {DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}");
    }

    public void LogError(string message) 
    {
        if (_logLevel != "ERROR") return;

        WriteLogEntry($"[ERROR] {DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}");
    }

    private void WriteLogEntry(string entry) 
    {
        File.AppendAllLines(_logFilePath, new List<string>() {entry});
    }
}
```
