typedef struct {
    int value;
    char* str;
} Element;

int randomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generateRandomString(const char* prefix, size_t len) {
    size_t prefixLen = strlen(prefix);
    char* str = malloc((prefixLen + len + 1) * sizeof(char)); // Allocate memory for the string and a null terminator.
    if (str == NULL) return NULL; 

    strncpy(str, prefix, prefixLen);
    for (size_t i = prefixLen; i < len; ++i) {
        str[i] = 'a' + rand() % ('z' - 'a' + 1); // Generate a random lowercase character.
    }
    str[len] = '\0';

    return str;
}

Element* resizeArray(Element** array, size_t currentCapacity, size_t newCapacity) {
    Element* newArray = realloc(*array, newCapacity * sizeof(Element)); // Resize the array.
    if (newArray == NULL && newCapacity > 0) return NULL; 

    *array = newArray;
    return *array;
}

void cleanupElements(Element* elements, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(elements[i].str); // Free dynamically allocated strings.
    }
    free(elements); 
}

int generateArray(const char* prefix, size_t minLen, size_t maxLen, int minValue, int maxValue, size_t count, Element** outElements) {
    srand((unsigned int) time(NULL)); // Seed the random number generator.

    *outElements = malloc(count * sizeof(Element)); // Allocate memory for the initial array.
    if (*outElements == NULL) return -1; 

    size_t currentCapacity = count, newCapacity = 2 * count;
    Element* elements = *outElements;

    for (size_t i = 0; i < count; ++i) {
        if (i >= currentCapacity && !resizeArray(&elements, currentCapacity, newCapacity)) { // Resize the array when necessary.
            cleanupElements(*outElements, i); // Clean up previously allocated memory and return on failure.
            return -1; 
        }

        size_t len = randomInt(minLen, maxLen);
        elements[i].str = generateRandomString(prefix, len);
        if (elements[i].str == NULL) { // Handle memory allocation failure for a string.
            cleanupElements(*outElements, i + 1);
            return -1; 
        }

        elements[i].value = randomInt(minValue, maxValue);
    }

    *outElements = elements;
    return 0; // Return success status.
}
```
