#define DEFAULT_SIZE 1024*1024 // Assume default size for memory pool

typedef struct {
    long offset;
    int key;
    char *name;
} record;

int allocateMemory(long **offsets, int **keys, record ***records, int size) {
    if (size <= 0 || size > DEFAULT_SIZE / sizeof(long)) return -1; // Check for invalid size

    *offsets = malloc(size * sizeof(long)); // Allocate memory for offset values
    if (*offsets == NULL) return -2; // Memory allocation failed

    *keys = malloc(size * sizeof(int)); // Allocate memory for keys
    if (*keys == NULL) {
        free(*offsets); // Free already allocated memory
        return -2; // Memory allocation failed
    }

    *records = malloc(size * sizeof(record*)); // Allocate memory for record pointers
    if (*records == NULL) {
        free(*keys);  // Free already allocated memory
        free(*offsets);
        return -2; // Memory allocation failed
    }

    memset(*offsets, 0, size * sizeof(long)); // Initialize offset values to zero
    memset(*keys, 0, size * sizeof(int)); // Initialize keys to zero

    for (int i = 0; i < size; ++i) {
        (*records)[i] = malloc(sizeof(record)); // Allocate memory for each record pointer
        if ((*records)[i] == NULL) {
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; ++j)
                free((*records)[j]); // Free already allocated memory
            return -2; // Memory allocation failed
        }

        (*records)[i]->offset = 0; // Initialize offset to zero
        (*records)[i]->key = 0;  // Initialize key to zero
    }

    return size; // Return the allocated size
}
