        (*records)[i].name = strdup(names[index]);
        if ((*records)[i].name == NULL) {
            perror("Error duplicating string");
            return -1; // Return an error code
        }

        logInit(&(*records)[i]);
    }

    fclose(fp);
    num_bundles++;

    pthread_mutex_unlock(&mutex);
    return size;
}
