} Node;

typedef struct linkedList {
    pthread_mutex_t lock; // for thread safety
    Node *head;
} LinkedList;

LinkedList *list = NULL;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER; 

// Function to add a record in the linkedList ensuring keys are unique and offsets fall within boundary.
void addRecord(int key, long offset) {
    pthread_mutex_lock(&listLock); // thread safety for list operations

    if (list == NULL) {
        list = (LinkedList*)malloc(sizeof(LinkedList));
        list->head = NULL;
    }

    Node *node = malloc(sizeof(Node));
    node->record = malloc(sizeof(Record));
    node->record->key = key;
    node->record->offset_value = offset;
    node->next = NULL;

    pthread_mutex_init(&node->lock, NULL); // for thread safety for individual nodes

    Node *currNode = list->head;
    while (currNode != NULL) {
        if (currNode->record->key == key || currNode->record->offset_value > offset) {
            // handle error: duplicate keys or offsets out of boundary
        }
        currNode = currNode->next;
    }

    Node *lastNode = list->head;
    if (list->head == NULL || lastNode->record->key > key) {
        node->next = list->head;
        list->head = node;
    } else {
        while(lastNode->next != NULL && 
               lastNode->next->record->offset_value < offset) {
            lastNode = lastNode->next;
        }
        node->next = lastNode->next;
        lastNode->next = node;
    }

    pthread_mutex_unlock(&listLock); // releasing the lock after operation
}
