['Below is a simple example of how you might implement such functionality in C. Note that this only provides a very basic structure and does not cover all the considerations you specified (e.g., third-party library integrations, error handling strategies, graceful degradation under load etc.). A real-world implementation would be significantly more complex and would require much more robust error checking and management of resources to ensure performance, scalability, and stability.

```c
#include <stdlib.h>
#include <assert.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t count;
    size_t capacity;
    size_t max_offset;
} StateManager;

int isUnique(StateManager* sm, int key) {
    for (size_t i = 0; i < sm->count; ++i) {
        if (sm->keys[i] == key) return 0;
    }
    return 1;
}

void updateRecord(StateManager* sm, int key, int value) {
    for (size_t i = 0; i < sm->count; ++i) {
        if (sm->keys[i] == key) {
            sm->records[i]->value = value;
            return;
        }
    }
}

int addRecord(StateManager* sm, long offset, int key, int value) {
    assert(offset < sm->max_offset && "Offset exceeds maximum allowed value");
    if (sm->count == sm->capacity) return 0; // No more space

    if (!isUnique(sm, key)) return 0; // Key not unique

    sm->records[sm->count] = malloc(sizeof(record));
    assert(sm->records[sm->count] != NULL && "Memory allocation failed");

    sm->offsets[sm->count] = offset;
    sm->keys[sm->count] = key;
    sm->records[sm->count]->value = value;

    ++(sm->count);
    return 1; // Success
}

StateManager* createStateManager(size_t capacity, size_t max_offset) {
    StateManager* sm = malloc(sizeof(StateManager));
    assert(sm != NULL && "Memory allocation failed");

    sm->records = calloc(capacity, sizeof(record*));
    assert(sm->records != NULL && "Memory allocation failed");

    sm->offsets = malloc(sizeof(long) * capacity);
    assert(sm->offsets != NULL && "Memory allocation failed");

    sm->keys = malloc(sizeof(int) * capacity);
    assert(sm->keys != NULL && "Memory allocation failed");

    sm->count = 0;
    sm->capacity = capacity;
    sm->max_offset = max_offset;
    return sm;
}

void destroyStateManager(StateManager* sm) {
    for (size_t i = 0; i < sm->count; ++i) {
        free(sm->records[i]);
    }

    free(sm->offsets);
    free(sm->keys);
    free(sm->records);
}
```
This code provides a basic structure for managing state in an application that includes offset values, unique keys and record structures. The `addRecord` function adds new records to the manager, checking for uniqueness of keys and ensuring all offsets fall within a predefined boundary. The `updateRecord` function allows you to update individual records by key while maintaining efficient access patterns.
