            continue;
        }

        strcpy(records[i].name, names[nameIndex]); // Copy the name from the list.

        log_record(&records[i], i); // Log the record initialization.
    }

    for (int i = 0; i < numRecords; ++i) {
        free(records[i].name); // Free the memory allocated for each name.
    }

    free(records); // Free the memory allocated for the records array.

    return 0;
}
```
