  Session(boost::asio::io_context& io_context) : socket_(io_context) {}

  tcp::socket& socket() { return socket_; }

  void start() {
    // Add code to handle GET requests here.
    std::cout << "Starting session..." << std::endl;
  }

private:
  tcp::socket socket_;
};

class Server {
public:
  Server(boost::asio::io_context& io_context, short port) : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)) {
    accept();
  }

private:
  void accept() {
    auto new_connection = std::make_shared<Session>(acceptor_.get_executor().context());

    acceptor_.async_accept(new_connection->socket(), [this, new_connection](boost::system::error_code ec) {
      if (!ec) {
        new_connection->start();
      } else {
        std::cout << "Error accepting connection: " << ec.message() << std::endl;
      }

      accept(); // Continue to accept connections.
    });
  }

  tcp::acceptor acceptor_;
};

int main() {
  try {
    boost::asio::io_context io_context;

    Server server(io_context, 12345); // Listen on port 12345.

    io_context.run();
  } catch (std::exception& e) {
    std::cerr << "Exception: " << e.what() << "\n";
  }

  return 0;
}
```
