["Here is an implementation of such system in C using pthreads for synchronization. This solution has a naive hash function which you would need to replace with a more efficient one for your use case. Also, keep in mind this code needs to be adjusted based on the exact requirements and constraints of your project. It's recommended that you have a good understanding of C programming and multithreading before using this.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct node {
    char *key;
    int value;
} Node;

typedef struct bucket {
    pthread_mutex_t lock; //for thread safety
    Node **nodes; 
    size_t count; 
    size_t size; 
} Bucket;

Bucket *buckets = NULL;
size_t num_of_buckets = 0;
pthread_mutex_t bucket_lock = PTHREAD_MUTEX_INITIALIZER; //for thread safety

Node* create_node(const char *key, int value) {
    Node *node = malloc(sizeof(Node));
    if (!node) return NULL; 

    node->key = strdup(key);
    node->value = value;
    return node;
}

void destroy_node(Node *node) {
    free(node->key);
    free(node);
}

Bucket* create_bucket() {
    Bucket *bucket = malloc(sizeof(Bucket));
    if (!bucket) return NULL; 

    bucket->count = 0;
    bucket->size = 1; //start with a small size for efficiency
    bucket->nodes = calloc(bucket->size, sizeof(Node*));
    pthread_mutex_init(&bucket->lock, NULL); 
    return bucket;
}

void destroy_bucket(Bucket *bucket) {
    for (size_t i = 0; i < bucket->count; ++i) {
        destroy_node(bucket->nodes[i]);
    }
    free(bucket->nodes);
    pthread_mutex_destroy(&bucket->lock); 
    free(bucket);
}

size_t hash_function(const char *key) {
    size_t hash = 0;
    while (*key) {
        hash = hash << 1 ^ *key++;
    }
    return hash % num_of_buckets; //naive hash function for example, replace it with a more efficient one
}

int add_node(const char *key, int value) {
    Node *node = create_node(key, value);
    if (!node) return -1; 

    size_t index = hash_function(key); 
    Bucket *bucket;
    pthread_mutex_lock(&bucket_lock); 
    {
        bucket = &buckets[index]; 
        pthread_mutex_lock(&bucket->lock); 
        ++bucket->count;
        if (bucket->size < bucket->count) { //check if we need to resize the array
            bucket->size *= 2;
            bucket->nodes = realloc(bucket->nodes, bucket->size * sizeof(Node*));
        }
        bucket->nodes[bucket->count - 1] = node; //add the node at the end of the array
    }
    pthread_mutex_unlock(&bucket->lock); 
    pthread_mutex_unlock(&bucket_lock); 
    return 0; 
}
```
This code only provides a basic structure, you would need to implement additional functions like remove node, resize buckets, etc. Also, handle error conditions and edge cases according to your needs. This is just a starting point for further development.
