    struct addrinfo hints = {}, *servinfo = NULL; 
    hints.ai_family   = AF_INET; // IPv4 only for simplicity.
    hints.ai_socktype = SOCK_STREAM; 

    if (getaddrinfo(serviceName, NULL, &hints, &servinfo) != 0) {
        snprintf("DNS resolution failed for service %s\n", serviceName);
        errorCode = 1; // DNS resolution failure code.
        goto cleanup;
    } 

    int sockfd = socket(servinfo->ai_family, servinfo->ai_socktype, servinfo->ai_protocol);
    if (connect(sockfd, servinfo->ai_addr, servinfo->ai_addrlen) == -1) {
        snprintf("TCP connection setup failed for service %s\n", serviceName);
        errorCode = 2; // TCP connection failure code.
        goto cleanup;
    } 

    if(globalConfig.logLevel > 0){
       // Logging related code here using snprintf and va_start/va_end.  
    }

cleanup:
    freeaddrinfo(servinfo); // Clean up allocated memory.
    close(sockfd); 
    pthread_mutex_unlock(&netInitLock); // Unlock after network initialization.
    va_end(args); // End processing of variable arguments.

    return errorCode;
}
