#ifdef __linux__
  dlclose(handle);
#elif _WIN32
  FreeLibrary((HMODULE)handle);
#endif
}

// Function to add an algorithm to our list in the desired order of fallback.
void addAlgorithmToList(CryptoAlgorithm *algorithm, int position){
  pthread_mutex_lock(&lock);
  Node_t* newNode = malloc(sizeof(Node_t));
  newNode->algorithm = *algorithm;
  if (head == NULL || position == 0) { //Insert at beginning
    newNode->next = head;
    head = newNode;
  } else{
    Node_t* current = head;
    for(int i = 1; i < position && current->next != NULL; ++i){
      current = current->next;
    }
    //insert the node
    newNode->next = current->next;
    current->next = newNode;
  }
  pthread_mutex_unlock(&lock);
}
```
