function authenticateUser($clientId, $clientSecret, $redirectUri) {
    $provider = new \League\OAuth2\Client\Provider\GenericProvider([
        'clientId'                => $clientId,    // The client ID assigned to you by the provider
        'clientSecret'            => $clientSecret,   // The client password assigned to you by the provider
        'redirectUri'             => $redirectUri,
        'urlAuthorize'            => 'https://provider.com/oauth2/authorize',
        'urlAccessToken'          => 'https://provider.com/oauth2/token',
        'urlResourceOwnerDetails' => 'https://provider.com/oauth2/resource'
    ]);

    // If we don't have a code then get one and store it in session variable.
    if (!isset($_GET['code'])) {
        $authorizationUrl = $provider->getAuthorizationUrl();
        session_start();
        $_SESSION['oauth2state'] = $provider->getState();
        header('Location: '.$authorizationUrl);
        exit;
    } elseif (empty($_GET['state']) || (isset($_SESSION['oauth2state']) && $_GET['state'] !== $_SESSION['oauth2state'])) {
        if (isset($_SESSION['oauth2state'])) unset($_SESSION['oauth2state']);
        exit('Invalid state');
    } else {
        try {
            // Try to get an access token using the authorization code grant.
            $accessToken = $provider->getAccessToken('authorization_code', [
                'code' => $_GET['code']
            ]);

            // Store the access token securely in a session variable, ensuring it is kept safe and accessible only to authorized users.
            $_SESSION['access_token'] = $accessToken;

            // Using the access token, get user details from the provider's API.
            $request = $provider->getAuthenticatedRequest(
                'GET',
                'https://provider.com/oauth2/resource',
                $accessToken
            );
        } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
            // Failed to get the access token or user details.
            exit($e->getMessage());
        }
    }
}
