["Here's some basic code to implement the first part of your task. This involves creating a custom memory allocator with fixed-size blocks. It does not include all error checking and other features as they would add significantly to the complexity. You might also want to consider using an existing memory management library like glibc's malloc if you need a real world solution, this is just a simple example for illustrative purposes.

```C
#include <stdlib.h>
#include <string.h>

#define BLOCK_SIZE sizeof(void*)
#define MAX_BLOCKS 10000

typedef struct MemoryPool {
    void* memory;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool create_memory_pool() {
    MemoryPool pool;
    pool.capacity = BLOCK_SIZE * MAX_BLOCKS;
    pool.used = 0;
    pool.memory = malloc(pool.capacity);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL; // out of memory
    } else {
        void* block = (char*)pool->memory + pool->used;
        pool->used += size;
        return block;
    }
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->memory);
    pool->capacity = 0;
    pool->used = 0;
    pool->memory = NULL;
}
```
