['Here's a basic implementation example of what you might need.

In this case, we will use `std::unordered_map` from C++ standard library which provides thread safety and efficient lookup capabilities. Also we are using a custom hash function for string key distribution.

```c++
#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <unordered_map>

typedef struct node {
    std::string* str;
    int value;
} node;

typedef struct bucket {
    std::vector<node*> nodes;
    std::mutex mtx;
} bucket;

std::hash<std::string> hash_fn;
size_t BUCKETS = 1024;
bucket buckets[1024];

void insertNode(const std::string& key, int value) {
    size_t index = hash_fn(key) % BUCKETS;

    // Lock the bucket to ensure thread-safety
    std::lock_guard<std::mutex> lock(buckets[index].mtx);

    for (node* n : buckets[index].nodes){
        if (*n->str == key) {
            n->value = value;
            return;
        }
    }

    node *newNode = new node();
    newNode->str = new std::string(key);
    newNode->value = value;
    buckets[index].nodes.push_back(newNode);
}

int getValue(const std::string& key) {
    size_t index = hash_fn(key) % BUCKETS;

    // Lock the bucket to ensure thread-safety
    std::lock_guard<std::mutex> lock(buckets[index].mtx);

    for (node* n : buckets[index].nodes){
        if (*n->str == key) {
            return n->value;
        }
    }
    throw std::runtime_error("No such key in the map");
}
```
