typedef struct {
    int value;
} record;

struct bucket_t {
    pthread_mutex_t mutex;
    long offset;
    int key;
    record rec;
};

typedef struct bucket_t Bucket;

Bucket* hashTable = NULL;
size_t tableSize = 0;
pthread_rwlock_t lock; // used for concurrent read/write access
int loadFactor = 0; // customize this to your needs

void logError(const char *message) {
    /* Integrate with logging framework here. */
}

Bucket* allocateHashTable() {
    Bucket* table = (Bucket*) calloc(tableSize, sizeof(Bucket));

    if (!table) {
        logError("Failed to allocate memory for hash table.");
        return NULL;
    } 

    for (size_t i = 0; i < tableSize; ++i) {
        pthread_mutex_init(&(table[i].mutex), NULL);
    }

    return table;
}

void initializeHashTable() {
    if (!hashTable) {
        hashTable = allocateHashTable();
        pthread_rwlock_init(&lock, NULL);
    }
}

size_t hash(int key) {
    // Choose a suitable hash function. 
    return key % tableSize;
}

void insertRecord(int key, record rec) {
    size_t index = hash(key);

    pthread_rwlock_wrlock(&lock);
    if (hashTable[index].offset != 0) {
        // collision resolution strategy here.
        logError("Collision detected in the hash table.");
    } else {
        hashTable[index].key = key;
        hashTable[index].rec = rec;
    }
    pthread_rwlock_unlock(&lock);
}

record* findRecord(int key) {
    size_t index = hash(key);

    pthread_rwlock_rdlock(&lock);
    if (hashTable[index].key == key) {
        record* rec = &(hashTable[index].rec);
        pthread_rwlock_unlock(&lock);
        return rec;
    } else {
        logError("Record not found.");
        pthread_rwlock_unlock(&lock);
        return NULL;
    }
}
```
This code is a simple implementation of hash table in C. It uses separate chaining as collision resolution strategy which means it chains together records with same hash value. For load factor and hashing function, you have to customize according to your needs. To handle memory leak issue, this code uses `calloc` instead of `malloc` to initialize all elements to 0 in the allocated memory space. Also it protects table accesses with `pthread_rwlock_t lock;` to prevent thread interference and data race.
']

