['```cpp
#include <vector>
#include <string>
#include <algorithm>
#include <cctype>

void processStrings(std::vector<std::string>& strVec, const std::string& target, int* firstIntPtr, int* secondIntPtr) {
    if (!firstIntPtr || !secondIntPtr) {
        return;
    }

    bool found = false;
    for (const auto& str : strVec) {
        // Ignore non-string elements
        if (str.find(target, 0) != std::string::npos) {
            *firstIntPtr *= static_cast<int>(target.length());
            found = true;
            break;
        }
    }

    if (!found) {
        for (char c : target) {
            *firstIntPtr += static_cast<int>(c);
        }
    }

    std::sort(strVec.begin(), strVec.end(), [](const std::string& a, const std::string& b){
        return std::lexicographical_compare(a.begin(), a.end(), b.begin(), b.end(), 
            [](char a, char b) {return std::tolower(a) < std::tolower(b);});
    });
}
```

This function first checks if the integer pointers are null. If they are not, it scans through each string in the vector and if it finds the target string, it multiplies the current value of the first pointer by the length of the target string and sets found flag to true. If no match is found after scanning all strings, it adds the ASCII values of all characters in the target string to the first integer pointer. Afterwards, it sorts the vector alphabetically (ignoring case). It uses a lambda function for sorting that converts each character to lowercase before comparison, ensuring case-insensitive sorting. The function also handles edge cases like empty vectors or non-matching target strings by checking if the target string was found and handling accordingly.
']

