} PacketData;

class Metrics {
private:
    std::unordered_map<int, int> frequencyMap;
    std::queue<PacketData> windowQueue;
    unsigned int MAX_WINDOW_SIZE = 50000; // 50 milliseconds worth of packets @ 10kpps rate
    int errorCount = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
public:
    void addPacket(PacketData packet) {
        // TODO handle checksum verification and increase error count if failed

        pthread_mutex_lock(&lock);
        while (windowQueue.size() >= MAX_WINDOW_SIZE) {
            PacketData &oldestPacket = windowQueue.front();
            frequencyMap[oldestPacket.packetId]--;
            if (frequencyMap[oldestPacket.packetId] == 0)
                frequencyMap.erase(oldestPacket.packetId);
            windowQueue.pop();
        }

        frequencyMap[packet.packetId]++;
        windowQueue.push(packet);
        pthread_mutex_unlock(&lock);
    }

    // TODO implement method to calculate priority score

    int getErrorCount() { return errorCount; }
};

void processPackets(void *arg) {
    PacketData packet = *((PacketData *) arg);
    static Metrics metrics;
    metrics.addPacket(packet);
}
``` 
This function will handle asynchronous processing of packets using pthreads, with each packet processed in a separate thread. It will also maintain a queue to track the most recent packets (upto `MAX_WINDOW_SIZE`) and a map for calculating frequencies. For checksum verification, it assumes that it is done externally beforehand and increases error count if failed.

