#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
} record_t;

// Struct to hold the hash table and its associated locks
typedef struct hash_table {
    pthread_mutex_t lock;
    long *offsets;
    int *keys;
    record_t *records;
} hash_table_t;

static hash_table_t* create_hash_table(size_t size) {
    hash_table_t *ht = malloc(sizeof(*ht));
    if (!ht) goto error1;

    ht->offsets = calloc(size, sizeof(long));
    if (!ht->offsets) goto error2;

    ht->keys = calloc(size, sizeof(int));
    if (!ht->keys) goto error3;

    ht->records = calloc(size, sizeof(record_t));
    if (!ht->records) goto error4;

    pthread_mutex_init(&ht->lock, NULL);
    return ht;

error4: free(ht->keys);
error3: free(ht->offsets);
error2: free(ht);
error1: /* log error */;
}
```
In this code, a `hash_table_t` structure is allocated and initialized with dynamic memory. A mutex lock is also created to enable thread safety in the hash table operations.

