    stat(inputJPEG, &st);
    off_t size = st.st_size;

    unsigned char *jpegBuf = malloc(size);
    fread(jpegBuf, size, 1, file);
    fclose(file);

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
