```csharp
public static void SetKeys(Record[] records, int min, int max)
{
    if (min >= max) throw new ArgumentException("Invalid range");

    Random rng;
    try
    {
        RNGCryptoServiceProvider rngProv = new RNGCryptoServiceProvider();
        byte[] randomBytes = new byte[4];
        rngProv.GetBytes(randomBytes);
        int seed = BitConverter.ToInt32(randomBytes, 0);
        rng = new Random(seed);
    }
    catch (CryptographicException)
    {
        // Fallback to system clock if RNG is not available
        rng = new Random();
    }

    for (int i = 0; i < records.Length; i++)
    {
        int key = rng.Next(min, max);
        records[i].Key = key;
    }
}
