Record* setupRecords(int size, int keyMin, int keyMax) {
    srand((unsigned int) time(NULL)); // seed random number generator

    long *offsets = malloc(sizeof(long) * size);
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return NULL;
    }

    Record *records = calloc(size, sizeof(Record)); // initialize all elements to 0
    if (records == NULL) {
