        free(offsets);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        offsets[i] = rand(); // fill offset array with random long values

        int nameIndex = abs((int)rand()) % num_names; // hash function to distribute names evenly
        records[i].name = malloc(strlen(names[nameIndex]) + 1); 
        if (records[i].name == NULL) {
            fprintf(stderr, "Failed to allocate memory for name\n");
            free(offsets); // free all previously allocated memory on failure
            for (int j = 0; j < i; j++) { 
                free(records[j].name);
