["Here's a basic implementation using pthread library for thread-safe access and locking mechanisms. This is a simplified version to get the idea across. The actual code would be more complex and require handling many other aspects such as error checking, input validation, recovery from data corruption, etc. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int id;
    char* name;
    double timestamp;
} Record;

typedef struct Database {
    Record** records;
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    // Other fields as needed...
} Database;

Database* createDB() {
    Database* db = malloc(sizeof(Database));
    db->records = NULL;
    pthread_mutex_init(&db->lock, NULL);
    db->size = 0;
    db->capacity = 0;
    // Initialize other fields...
    return db;
}

void addRecord(Database* db, Record* record) {
    pthread_mutex_lock(&db->lock);
    if (db->size == db->capacity) {
        db->records = realloc(db->records, sizeof(Record*) * (db->capacity + 1024));
        db->capacity += 1024;
    }
    db->records[db->size] = record;
    db->size++;
    pthread_mutex_unlock(&db->lock);
}

Record* getRecord(Database* db, int id) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < db->size; i++) {
        if (db->records[i]->id == id) {
            Record* record = db->records[i];
            pthread_mutex_unlock(&db->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return NULL; // Record not found
}

void updateRecord(Database* db, int id, char* newName, double newTimestamp) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < db->size; i++) {
        if (db->records[i]->id == id) {
            free(db->records[i]->name); // Free old name string
            db->records[i]->name = newName;
            db->records[i]->timestamp = newTimestamp;
        }
    }
    pthread_mutex_unlock(&db->lock);
}

void deleteRecord(Database* db, int id) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < db->size; i++) {
        if (db->records[i]->id == id) {
            // Delete record...
            free(db->records[i]);

            // Shift remaining records...
            for (int j = i + 1; j < db->size; j++) {
                db->records[j - 1] = db->records[j];
            }
            db->size--;
        }
    }
    pthread_mutex_unlock(&db->lock);
}
```
This is a simplified version and does not handle persistent storage or data corruption detection. Also, it uses a global lock for all operations which can be inefficient when there are many threads. In a real application you would need to implement more sophisticated mechanisms like using fine-grained locks or even read/write locks depending on the use case.
