        } else {
            fprintf(stderr, "Index out of bounds\n");
            exit(1);
        }
    }
}

void readCSVFile(char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening the file");
        return;
    }

    // Read and parse CSV data here

    fclose(file);
}

void freeAllMemory(weather_data* array, int size) {
    for (int i = 0; i < size; ++i) {
        if (array[i].location_name != NULL && array[i].location_name != cityList[indices[i]]) { // If we allocated a new string, free it. 
            free(array[i].location_name);
        }
    }
    free(array);
}
```
