// Use a mutex to ensure thread-safe access in multi-threaded environment
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void allocate_records(record_t** records, size_t num_records) {
    // Lock the mutex before accessing shared data to ensure atomicity
    pthread_mutex_lock(&lock);

    *records = malloc(num_records * sizeof(record_t));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator

    int prev_value = rand(); // Use a random value as starting point

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = (prev_value + rand()) % RAND_MAX + 1;
        prev_value = (*records)[i].value;

        // Initialize offset_ptr if needed
        (*records)[i].offset_ptr = NULL;
    }

    pthread_mutex_unlock(&lock); // Unlock the mutex after accessing shared data
}

void deallocate_records(record_t** records, size_t num_records) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = 0; // Reset to default state
        if ((*records)[i].offset_ptr != NULL) {
            free((*records)[i].offset_ptr); // Free memory pointed by offset_ptr
            (*records)[i].offset_ptr = NULL;
        }
    }

    free(*records); // Deallocate records
    *records = NULL;

    pthread_mutex_unlock(&lock);
}
```

