import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.codec.digest.DigestUtils;

public class RecordProcessor {
    private static final int THRESHOLD = Integer.getInteger("duplicateThreshold", 5);

    private ConcurrentHashMap<String, AtomicInteger> hashCounts = new ConcurrentHashMap<>();
    private Set<String> duplicateHashes = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private List<Exception> errors = Collections.synchronizedList(new ArrayList<>());

    public void processAndHashRecords(Stream<String> records) {
        records.parallel().forEach(record -> {
            try {
                String hash = DigestUtils.sha256Hex(record);
                AtomicInteger count = hashCounts.computeIfAbsent(hash, k -> new AtomicInteger(0));
                if (count.incrementAndGet() >= THRESHOLD) {
                    duplicateHashes.add(hash);
                }
            } catch (Exception ex) {
                errors.add(ex);
            }
        });
    }
}
```

