import java.util.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;
import org.apache.commons.configuration.*;
import org.slf4j.*;
import com.externalLoggingService.*; // assuming the external logging service is available for import 

public class DataProcessor {
    private Properties properties = new Properties();
    private Logger logger = LoggerFactory.getLogger(DataProcessor.class);
    private ExternalLoggingService externalLoggingService;

    public void initialize() throws ConfigurationException, IOException{
        CompositeConfiguration config = new CompositeConfiguration();
        config.addConfiguration(new SystemConfiguration());
        config.addConfiguration(new PropertiesConfiguration("config.properties"));

        properties.putAll(config.subset("dataProcessor."));

        externalLoggingService = new ExternalLoggingService();
    }

    public Report processAndManageData(List<String> strings) {
        Set<byte[]> hashes = Collections.synchronizedSet(new HashSet<>());
        AtomicInteger duplicateCount = new AtomicInteger(0);
        Pattern pattern = Pattern.compile(properties.getProperty("skipPattern"));

        for (String string : strings) {
            if (string == null || string.isEmpty() || pattern.matcher(string).find()) 
                continue; // skip empty or null strings and those matching a skipping pattern

            byte[] hash = getHash(string);
            if (hashes.add(hash)) {
                externalLoggingService.logUniqueHash(hash, string);
            } else {
                duplicateCount.incrementAndGet();
                externalLoggingService.logDuplicateHash(hash, string);
            }
        }

        int uniqueCount = hashes.size(); // number of unique hashes is equal to the size of hash set
        return new Report(uniqueCount, duplicateCount.get(), Collections.emptyList()); 
    }

    private byte[] getHash(String string) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256"); // use SHA-256 as hash function
            return digest.digest(string.getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException e) {
            logger.error("Failed to generate hash", e);
            throw new IllegalStateException(e); // rethrow as runtime exception
        }
    }
}
