file_entry* initFileEntries(int num_entries) {
    file_entry* entries = malloc(num_entries * sizeof(file_entry));
    if (entries == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_entries; ++i) {
        entries[i].size = 0.0;
        entries[i].path = NULL;
        entries[i].encrypted = false;
        entries[i].timestamp = 0;
    }

    return entries;
}

// Function to set the path of a file entry
void setFilePath(file_entry* entry, char* directory) {
    if (directory == NULL) {
        fprintf(stderr, "Invalid directory.\n");
        exit(EXIT_FAILURE);
    }

    size_t len = strlen(directory);
    entry->path = malloc((len + 1) * sizeof(char));
    if (entry->path == NULL) {
        fprintf(stderr, "Failed to allocate memory for path.\n");
        exit(EXIT_FAILURE);
    }

    strcpy(entry->path, directory);
