typedef struct record {
    int value;
    long *offset;
} record;

// Allocate memory for a dynamic list of records
record* alloc_records(int count, int max_value) {
    if (count < 0 || count > INT_MAX / sizeof(record)) {
        return NULL; // Invalid input: handle error gracefully
    }

    record *list = malloc(count * sizeof(record));
    if (list == NULL) {
        return NULL; // Memory allocation failed: handle error gracefully
    }

    srand((unsigned int)time(NULL)); // seed the random number generator

    for (int i = 0; i < count; ++i) {
        list[i].value = rand() % max_value + 1; // Initialize each record with a random value between 1 and max_value

        // check if current record value is the same as previous one, if so re-randomize it
        for (int j = 0; j < i; ++j) {
            while (list[i].value == list[j].value) {
                list[i].value = rand() % max_value + 1; 
            }
        }
    }

    return list;
}

// Reset all records in the list to default state and free memory
void reset_records(record *list, int count) {
    if (list == NULL) {
        return; // Invalid input: handle error gracefully
    }

    for (int i = 0; i < count; ++i) {
        list[i].value = 0; // Set value to default state

        if (list[i].offset != NULL) {
            free(list[i].offset); // Free memory pointed by offset pointer
            list[i].offset = NULL; 
        }
    }

    free(list); // Free the entire list of records
}
