```c
#include <stdlib.h>
#define CHUNK_SIZE 1024 // Define the size of each chunk here
typedef struct MemChunk {
    unsigned char data[CHUNK_SIZE];
    struct MemChunk *next;
} MemChunk;
static MemChunk *head = NULL;
void *myMalloc(size_t size) {
    if (size > CHUNK_SIZE) return NULL; // If the requested size is too large, return null. 
    if (head == NULL || head->data + CHUNK_SIZE - (size_t)head < size) {
        MemChunk *new = malloc(sizeof(MemChunk)); // Allocate a new chunk.
        new->next = head;
        head = new;
    }
    void *ret = head->data + head->used;
    head->used += size;
    return ret;
}
```

