#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define a struct for record
typedef struct Record {
    long offset;
    int key;
    char name[11];  // allocate space for 10 characters plus null terminator
    double timestamp;
} Record;

// Create an array of predefined names
char* names[] = {"Alice", "Bob", "Charlie", "David"};
int num_names = sizeof(names) / sizeof(names[0]);

// Define a function to generate a record with random key and current timestamp
Record* create_record(long offset, int min_key, int max_key){
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        return NULL;  // handle memory allocation failure
    }

    rec->offset = offset;
    rec->key = rand() % (max_key - min_key + 1) + min_key;
    strncpy(rec->name, names[rand() % num_names], 10);  // truncate name if too long

    time_t t = time(NULL);
    rec->timestamp = (double)t;

    return rec;
}

// Define a function to initialize the dynamic array of records
Record** initialize_records(int num_records, int min_key, int max_key){
    srand((unsigned int)time(NULL));  // seed random number generator

    Record** arr = (Record**)malloc(num_records * sizeof(Record*));
    if (!arr) {
        return NULL;  // handle memory allocation failure
    }

    for (int i = 0; i < num_records; i++){
        Record* rec = create_record(i, min_key, max_key);
        if (!rec) {
            // free previously allocated records before returning on error
            while (--i >= 0) {
                free(arr[i]);
            }
            free(arr);
            return NULL;  // handle record creation failure
        }

        arr[i] = rec;
    }

    return arr;
}
```

