void processData(PGconn *conn, char *query) {
    PGresult *res = PQexec(conn, query);

    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        printf("Failed to execute query: %s", PQerrorMessage(conn));
        PQclear(res);
        return;
    }

    int nRows = PQntuples(res);

