    long *offsetValues = malloc(nRows * sizeof(long));
    if (offsetValues == NULL) {
        printf("Memory allocation failed\n");
        PQclear(res);
        return;
    }

    int *keys = malloc(nRows * sizeof(int));
    if (keys == NULL) {
        printf("Memory allocation failed\n");
        free(offsetValues);
        PQclear(res);
        return;
    }

    Record *records = malloc(nRows * sizeof(Record));
    if (records == NULL) {
        printf("Memory allocation failed\n");
        free(offsetValues);
        free(keys);
        PQclear(res);
        return;
    }

    // Initialize data structures
    for (int i = 0; i < nRows; i++) {
        offsetValues[i] = atol(PQgetvalue(res, i, 0));
