['Here is an example C implementation:

```c
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

void init_arrays(long **offsets, int **keys, Record ***records, size_t size, unsigned seed) {
    srand(seed); // set the random seed for reproducibility

    *offsets = malloc(sizeof(long) * size);
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(sizeof(int) * size);
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for array of records in one block to minimize fragmentation.
    *records = malloc(sizeof(Record*) + sizeof(Record) * size);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Adjust the pointer to point after the array of pointers.
    *records = (Record**)(*records + 1);

    for(size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand(); // initialize with random long values
        (*keys)[i] = rand(); // initialize with random int values
        (*records)[i].value = rand(); // initialize record values
    }
}

void free_arrays(long *offsets, int *keys, Record **records) {
    if (offsets != NULL)
        free(offsets);

    if (keys != NULL)
        free(keys);

    // Adjust the pointer to point before the array of pointers.
    records = (Record**)records - 1;

    if (records != NULL)
        free(records);
}
```

This code does not handle multithreading or locking, which would greatly complicate the function and increase its maintenance cost. However, it demonstrates how to optimize memory allocation, add error handling, and use a seed for reproducibility. The function has a low impact on overall system performance as it only allocates and deallocates memory.

