typedef struct task_node {
    char *task_name;
    struct timeval last_execution;
} task_node;

typedef struct linked_list {
    task_node* head;
    task_node* tail;
    int size;
} linked_list;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

task_node* createNode(char *name, struct timeval tv) {
    task_node* newNode = malloc(sizeof(task_node));
    if (newNode == NULL) {
        return NULL;  // Handle memory allocation failure
    }

    newNode->task_name = strdup(name);
    newNode->last_execution = tv;
    return newNode;
}

void insertNode(linked_list *list, task_node* node) {
    pthread_mutex_lock(&lock);  // Acquire the lock for thread safety

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;

    pthread_mutex_unlock(&lock);  // Release the lock
}
```
