// Global variables for tracking memory usage and operation count
int max_memory = 1024 * 1024 * 1024; // Maximum allowed size in bytes (1GB)
int current_size = 0;
long long operation_count = 0;
FILE* log_file = NULL;
Record* records = NULL;

// Function to allocate memory for a new record array
void allocateMemory(int count) {
    if ((current_size + count * sizeof(Record)) > max_memory) {
        printf("Error: Out of memory.\n");
        exit(1);
    } else {
        records = (Record*) realloc(records, current_size + count * sizeof(Record));

        if (records == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        current_size += count * sizeof(Record);
    }
}

// Function to handle the resizing of records array when memory usage reaches 90% of max limit
void resizeRecords() {
    if (current_size >= 0.9 * max_memory) {
        int new_count = (max_memory - current_size) / sizeof(Record);

        // Pause for 1 second to let other processes use system resources effectively
        sleep(1);

        allocateMemory(new_count);
    }
}

// Function to generate a random number and set it as the record value
void setRandomValue(Record* record) {
    srand(time(NULL)); // Initialize seed for generating random numbers
    record->value = rand();
}

