    if (log_file == NULL) {
        perror("Failed to open the log file");
        exit(EXIT_FAILURE);
    }

    // Allocate initial memory for records array
    allocateMemory(1024 * 1024); // Start with 1MB

    while (operation_count < 5000) {
        // Set random values to records
        for (int i = 0; i < current_size / sizeof(Record); ++i) {
            setRandomValue(&records[i]);
