typedef struct Node {
    float value;
    struct Node *next;
} Node;

void initAndProcess(void) {
    static long largeArray[LARGE_SIZE];
    static void* mediumArray[MEDIUM_SIZE];
    static int smallArray[SMALL_SIZE];

    // Allocate memory for linked list
    Node *head = malloc(sizeof(Node));
    if (head == NULL) {
        printf("Failed to allocate memory for head node.\n");
        return;
    }
    head->next = NULL;

    // Populate large array with random values and calculate medium pointers in a complex manner
    for(int i = 0; i < LARGE_SIZE; ++i) {
        largeArray[i] = rand();
        if (i % 1024 == 0) { // every time we encounter 1024th element, calculate the medium pointer
            int *mediumPointer = &smallArray[largeArray[i] >> 5]; // bitwise shift for complexity
            mediumArray[(int)((void*)mediumPointer - (void*)&smallArray) / sizeof(int)] = mediumPointer;
        }
    }

    Node *currentNode = head;
    float value = 0.0f;

    // Populate linked list and calculate node values in a complex manner
    for(int i = 1; i < NODES_COUNT; ++i) { 
        currentNode->next = malloc(sizeof(Node));
        if (currentNode->next == NULL) {
            printf("Failed to allocate memory for node.\n");
            return;
        }

        // Use bitwise operations and arithmetic operations to calculate node values.
        value += 0.1f + (float)((i << 3) ^ i); 
        currentNode->value = value;

        currentNode = currentNode->next;
    }

    // Process the linked list...
}
