['This problem is quite complex and involves multiple aspects like dynamic allocation, random number generation, thread safety, error handling, serialization/deserialization, logging and unit testing. Here's a simplified version of how you could implement this in C using pthread for multithreading, time.h for timestamps, stdio.h for file handling, and stdlib.h for malloc/free operations:

```C
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

Record* records = NULL;
int record_count = 0, max_size = 1024 * 1024, operation_count = 0;
FILE* log_file = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long random_num() {
    srand(time(NULL));
    return rand();
}

void initialize(int initial_size) {
    records = malloc(initial_size * sizeof(Record));

    for (int i = 0; i < initial_size; i++) {
        records[i].offset = random_num();
        records[i].key = random_num() % 1000000;
        record_count++;
        operation_count++;
    }

    log_file = fopen("log.txt", "a");
}

void resize(int new_size) {
    records = realloc(records, new_size * sizeof(Record));
    max_size = new_size;
}

void add_record() {
    pthread_mutex_lock(&lock);

    if (record_count >= max_size) {
        resize(max_size * 2);
    }

    records[record_count].offset = random_num();
    records[record_count].key = random_num() % 1000000;
    record_count++;
    operation_count++;

    if (operation_count % 10000 == 0) {
        double usage = 100.0 * record_count / max_size;

        fprintf(log_file, "Operation count: %d, Memory usage: %f%%\n", operation_count, usage);

        if (usage > 80) {
            sleep(2);
        }
    }

    pthread_mutex_unlock(&lock);
}

void serialize() {
    FILE* file = fopen("data.bin", "wb");

    for (int i = 0; i < record_count; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

void deserialize() {
    FILE* file = fopen("data.bin", "rb");
    Record record;

    while (fread(&record, sizeof(Record), 1, file)) {
        add_record(record);
    }

    fclose(file);
}
```

This is a simplified implementation and doesn't include the unit tests. Also, you may need to adjust some parts according to your specific requirements such as thread safety, memory allocation handling, logging mechanism or serialization/deserialization method. 

Moreover, it's recommended to use dynamic allocators like jemalloc or tcmalloc for better efficiency and stability compared to system's default malloc/free in terms of speed and stability.
']

