        int cityIndex = json_object_get_int(json_object_array_get_idx(jobj, i+1));  // Assume the next index contains city index.
        if (cityIndex < 0 || cityIndex >= sizeof(cityNames) / sizeof(char*)) {
            printf("Invalid city index: %d\n", cityIndex);
            return -1;
        }
        wd[i].location = strdup(cityNames[cityIndex]);

        int timestampRangeMin = json_object_get_int(json_object_array_get_idx(jobj, i+2));  // Assume next index contains min timestamp.
        int timestampRangeMax = json_object_get_int(json_object_array_get_idx(jobj, i+3));  // And the following one max timestamp.
        if (timestampRangeMin > timestampRangeMax) {
            printf("Invalid timestamp range: %d to %d\n", timestampRangeMin, timestampRangeMax);
