['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <semaphore.h>
#define MAX_LOG_ENTRIES 1024
typedef struct {
    long offset;
    int key;
    char* name;
} record;

// Predefined names list
char *names[] = {"Alice", "Bob", "Charlie"};
int numNames = sizeof(names) / sizeof(names[0]);
sem_t semaphore;
FILE *logfile;
record logBuffer[MAX_LOG_ENTRIES];
int logIndex = 0;

void flushLogEntries() {
    // Flush the buffer of log entries to file asynchronously
    for(int i = 0; i < logIndex; i++) {
        fprintf(logfile, "Record: offset=%ld key=%d name=%s\n", 
                logBuffer[i].offset, logBuffer[i].key, logBuffer[i].name);
    }
    logIndex = 0; // reset the buffer index
}

void *create_shared_memory(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void logRecordInit(record *rec){
    assert(logIndex < MAX_LOG_ENTRIES);
    memcpy(&logBuffer[logIndex++], rec, sizeof(*rec)); // copy record to buffer

    if (logIndex == MAX_LOG_ENTRIES) {
        sem_wait(&semaphore); // Lock for flushing log entries
        flushLogEntries(); 
        sem_post(&semaphore); // Unlock after flushing
    }
}

void initFunction(long *offsets, int *keys, record *records, long numOffsets, int numKeys, int numRecords){
    if (numKeys > numOffsets) {
        printf("Number of keys cannot exceed number of offsets\n");
        exit(EXIT_FAILURE);
    }

    // Validate that total size does not exceed 2GB per process
    assert((numRecords * sizeof(record)) <= 1L << 31); // 2GB in bytes

    // Allocate memory for and initialize offsets array
    long* offsets = (long*) create_shared_memory(sizeof(long) * numOffsets);
    memset(offsets, 0, sizeof(long) * numOffsets);

    // Allocate memory for and initialize keys array
    int* keys = (int*) create_shared_memory(sizeof(int) * numKeys);
    memset(keys, 0, sizeof(int) * numKeys);

    // Allocate memory for records array
    record* records = (record*) create_shared_memory(sizeof(record) * numRecords);
    for(long i = 0; i < numRecords; i++){
        long nameIndex = rand() % numNames; 
        records[i].name = strndup(names[nameIndex], 256); // ensure all names fit within buffer of 256 bytes

        logRecordInit(&records[i]); // Log record initialization
    }

    // Initialize semaphore for logging operations
    if (sem_init(&semaphore, 0, 1) == -1) {
        perror("Sem init");
        exit(EXIT_FAILURE);
    }

    logfile = fopen("log.txt", "a"); // open log file
    if (logfile == NULL) {
        printf("Error opening logfile\n");
        exit(EXIT_FAILURE);
    }

    for(long i = 0; i < numRecords; i++){
        records[i].key = rand() % 1e9; // set key to a random value within range (0-1e9)
    }
}
```
Please note, the above code is just a skeleton and will not work as expected without more input parameters. For example, you need to define the user input for `numOffsets`, `numKeys`, `numRecords`, and a range for random number generation. In addition, logging errors is not covered in this code. You should implement it according to your requirements.
']

