#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset;
} record_t;

record_t *records = NULL;
size_t records_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int generate_unique_key() {
    // This is a simple way to ensure uniqueness, it might not be efficient for large datasets.
    int key;
    pthread_mutex_lock(&mutex);
    do {
        key = rand();  // Generate random integer for key
    } while (get_record(key) != NULL);  // Retry if key is not unique
    pthread_mutex_unlock(&mutex);
    return key;
}

record_t *get_record(int key) {
    for (size_t i = 0; i < records_count; ++i) {
        if (records[i].key == key) {
            return &records[i];  // Record found, return pointer to it
        }
    }
    return NULL;  // Record not found
}

int add_record(long offset) {
    record_t *new_record = malloc(sizeof(record_t));  // Allocate memory for new record
    if (new_record == NULL) {
        return -1;  // Memory allocation failed
    }

    int key = generate_unique_key();

    new_record->key = key;
    new_record->offset = offset;

    pthread_mutex_lock(&mutex);
    records = realloc(records, (records_count + 1) * sizeof(record_t));  // Reallocate memory for records array
    if (records == NULL) {
        free(new_record);  // Memory allocation failed, free allocated memory
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    memcpy(&records[records_count], new_record, sizeof(record_t));  // Copy new record to the end of records array
    ++records_count;
    pthread_mutex_unlock(&mutex);
    free(new_record);  // Free allocated memory for new record

    return key;
}
```
This code includes a simple way to generate unique keys and manages concurrent access using mutex. However, it does not include any error handling or optimization techniques that you might need in a production environment. Also, this implementation assumes that the external data source can be accessed quickly and reliably without delays. In a real-world scenario, you would need to consider these factors.
