// Define custom error codes
enum ErrorCode {
    INVALID_SIZE = -1,
    MEMORY_ALLOCATION_FAILURE = -2,
};

// Custom memory pool manager
typedef struct MemoryPoolManager {
    void* memory;
    size_t totalSize;
    size_t usedSize;
} MemoryPoolManager;

MemoryPoolManager* createMemoryPool(size_t initialSize) {
    if (initialSize <= 0) return INVALID_SIZE;

    MemoryPoolManager* manager = malloc(sizeof(MemoryPoolManager));
    if (!manager) return MEMORY_ALLOCATION_FAILURE;

    manager->memory = malloc(initialSize);
    if (!manager->memory) {
        free(manager);
        return MEMORY_ALLOCATION_FAILURE;
    }

    manager->totalSize = initialSize;
    manager->usedSize = 0;
    return manager;
}

void* allocateMemoryFromPool(MemoryPoolManager* manager, size_t size) {
    if (manager->usedSize + size > manager->totalSize) {
        // Handle pool overflow here - for example by doubling the pool size.
        return NULL;
    }

    void* block = manager->memory + manager->usedSize;
    manager->usedSize += size;
    return block;
}
```
2. Record Management:
