#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

// Define cache line size for alignment
#define CACHE_LINE_SIZE 64

typedef struct {
    int* data;
    size_t used;
    size_t size;
} Array;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initArray(Array* a, size_t initialSize) {
    assert(initialSize > 0);
    a->data = aligned_alloc(CACHE_LINE_SIZE, initialSize * sizeof(int));
    if (a->data == NULL) exit(-1); // Memory allocation failed.
    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array* a, int element) {
    pthread_mutex_lock(&lock); 
    if (a->used == a->size) {
        a->size *= 2;
        a->data = realloc(a->data, a->size * sizeof(int));
        if (a->data == NULL) exit(-1); // Memory allocation failed.
    }
    a->data[a->used++] = element;
    pthread_mutex_unlock(&lock); 
}

void freeArray(Array* a) {
    free(a->data);
    a->data = NULL;
    a->used = a->size = 0;
}

int main() {
    Array a;
    int i;
    initArray(&a, 5); // Initial size of array is 5.
    for (i=1;i<20;++i) insertArray(&a, i); // Inserting elements into the array.
    freeArray(&a); // Free up resources when done.
}
```
