ConfigManager *initConfigManager() {
    ConfigManager *manager = (ConfigManager *) malloc(sizeof(ConfigManager));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    manager->size = 0;
    manager->configs = NULL;
    return manager;
}

void addConfiguration(ConfigManager *manager, int userID, char *L1Parameters, char *accessToken) {
    pthread_mutex_lock(&manager->lock);  // Lock to prevent data races

    Config **oldConfigs = manager->configs;
    int oldSize = manager->size;

    manager->size++;
    manager->configs = (Config **) malloc(sizeof(Config *) * manager->size);

    for(int i = 0; i < oldSize; i++) {
        manager->configs[i] = oldConfigs[i];
    }

    Config *newConfig = (Config *) malloc(sizeof(Config));
    newConfig->userID = userID;
    newConfig->L1Parameters = L1Parameters;
    newConfig->accessToken = accessToken;
    manager->configs[oldSize] = newConfig;

    free(oldConfigs);  // Free the old config array

    pthread_mutex_unlock(&manager->lock);  // Unlock after modification
}

