["```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct sensor_data {
    float temperature;
    int humidity;
    int pressure;
    time_t lastUpdateTime;  // For tracking clean up
} SensorData;

typedef struct node {
    SensorData* data;
    struct node* next;
} Node;

Node* sensors = NULL;  
int sensorCount = 0;

void initializeSensor(SensorData* s) {
    if (s == NULL) return;  // Error checking

    s->temperature = ((float)rand() / RAND_MAX) * 50.0f - 10.0f;  // Random temperature between -10 and 40
    s->humidity = rand() % 101;  // Random humidity percentage
    s->pressure = 900 + (rand() % 31);  // Random pressure within a certain range
    s->lastUpdateTime = time(NULL);  
}

SensorData* addNewSensor() {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return NULL;  // Error checking memory allocation failure

    SensorData* sensorData = malloc(sizeof(SensorData));
    if (sensorData == NULL) {  // Error checking memory allocation failure
        free(newNode);
        return NULL;  
    }

    initializeSensor(sensorData);

    newNode->data = sensorData;
    newNode->next = sensors;
    sensors = newNode;
    sensorCount++;

    return sensorData;  // Returning pointer to the newly created SensorData struct for easy access
}

void updateSensor(int index) {
    Node* node = sensors;

    for (int i = 0; i < index && node != NULL; ++i) {
        node = node->next;
    }

    if (node == NULL || node->data == NULL) return;  // Error checking invalid sensor index

    initializeSensor(node->data);
}

float getLatestMeasurement(int index, char measurementType) {
    Node* node = sensors;

    for (int i = 0; i < index && node != NULL; ++i) {
        node = node->next;
    }

    if (node == NULL || node->data == NULL) return -1.0f;  // Error checking invalid sensor index

    switch(measurementType) {
        case 'T': return node->data->temperature;
        case 'H': return node->data->humidity;
        case 'P': return node->data->pressure;
        default: return -1.0f;  // Error checking invalid measurement type
    }
}

void periodicCleanUp() {
    time_t currentTime = time(NULL);

    Node* prevNode = NULL;
    Node* node = sensors;

    while (node != NULL) {
        if (currentTime - node->data->lastUpdateTime > 60 * 5) {  // Clean up sensor if it hasn't been updated for more than 5 minutes
            if (prevNode == NULL) {  
                sensors = node->next;
            } else {
                prevNode->next = node->next;
            }

            free(node->data);
            Node* temp = node;
            node = node->next;
            free(temp);  // Free memory of the sensor's node as well
            sensorCount--;
        } else {
            prevNode = node;
            node = node->next;
        }
    }
}
```
This is a basic implementation. You would need to adjust and add further error handling, potentially add additional features, etc. based on your specific requirements. This includes using different data types or struct members as needed by the actual sensors you're working with, setting up separate threads for periodic cleanup if it's not running continuously (i.e., in a loop), adding synchronization measures where necessary, and more.
"]

