void* xmalloc(size_t size) {
    void *ptr = malloc(size);

    if (ptr == NULL) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    return ptr;
}

void cleanup() {
    // Clean up any allocated memory and other resources here
}

void signalHandler(int signum) {
    printf("Interrupt signal (%d) received.\n", signum);

    // Perform clean-up actions
    cleanup();

    exit(signum);
}

void initialize() {
    srand(time(0));  // Seed random number generator

    // Register signal handler for graceful termination
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);
}

long getSystemMemoryLimit() {
    struct rlimit limit;
    if (getrlimit(RLIMIT_AS, &limit) < 0) {
        perror("Could not get system memory limit");
        exit(EXIT_FAILURE);
    }

    return limit.rlim_cur / 10;  // Use only 10% of the total system memory for safety
}

void populateRecords(Record* records, int recordCount, int keyRange) {
    long nameLength = 0;
    size_t nameListSize = sizeof(names)/sizeof(char*);

    // Populate each record with random values and names from the predefined list
    for (int i = 0; i < recordCount; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % keyRange;

        size_t nameIndex = rand() % nameListSize;  // Select a random name from the list
        records[i].name = strdup(names[nameIndex]);  // Duplicate the selected name for each record

        nameLength += strlen(records[i].name);
    }

    if (nameLength > 1024 * 1024) {  // If total length of names exceeds 1MB, log a warning and adjust to fit within limit
        printf("Warning: Total length of names exceeded 1MB. Truncating some names.\n");

        while (nameLength > 1024 * 1024) {
            size_t nameIndex = rand() % recordCount;  // Select a random record to truncate its name

            char* oldName = records[nameIndex].name;
            size_t lengthToTruncate = strlen(oldName);

            records[nameIndex].name[lengthToTruncate / 2] = '\0';  // Truncate the name at half its length
            nameLength -= lengthToTruncate / 2;

            free(oldName);
        }
    }
}

void logRecord(const Record* record) {
    printf("Initializing record with offset: %ld, key: %d, name: %s\n", record->offset, record->key, record->name);
}

int main() {
    initialize();

    long totalMemoryLimit = getSystemMemoryLimit();

    printf("Enter the number of records: ");
    int recordCount;
    scanf("%d", &recordCount);

    if (recordCount < 0 || recordCount > totalMemoryLimit / sizeof(Record)) {
        printf("Invalid input. Please enter a positive integer not exceeding %ld\n", totalMemoryLimit / sizeof(Record));
        return 1;
    }

    Record* records = xmalloc(recordCount * sizeof(Record));

    printf("Enter the key range: ");
    int keyRange;
    scanf("%d", &keyRange);

    if (keyRange < 0 || keyRange > 1e9) {
        printf("Invalid input. Please enter a positive integer not exceeding 1 billion\n");
        free(records);
        return 1;
    }

    populateRecords(records, recordCount, keyRange);

    for (int i = 0; i < recordCount; ++i) {
        logRecord(&records[i]);
    }

    free(records);  // Free allocated memory when done using it

    return 0;
}
```
This code uses the `xmalloc` function to allocate memory with error handling, and a signal handler is registered to perform clean-up actions upon receiving interrupt signals. The `populateRecords` function populates records with random values and names from a predefined list of names, while also ensuring that total length of all `name` strings does not exceed 1MB. Logging mechanism for each record initialization is implemented in the `logRecord` function.
