void* memory_pool = NULL; // start of memory pool
size_t allocated = 0, capacity = 0; // current allocation & total capacity
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // for thread safety 

// Memory Pool Allocation
void* allocate(size_t size) {
    pthread_mutex_lock(&lock);

    if (allocated + size > capacity) {
        // reallocate memory pool with enough space
        capacity = allocated + size;
        memory_pool = realloc(memory_pool, capacity);

        if (!memory_pool) {
