    long unique_value;
    Offset* offset_ptr;
    Key* key_ptr;
} Record;

// Define error codes
#define ERROR_INDEX (-1)
#define MEMORY_ALLOCATION_FAILURE (-2)

long initializeMemory(Offset** offsets, Key** keys, Record** records, int offsetSize, int keySize, int recordSize, 
                      const int* indexMapping) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for 'offset' and 'key' structures
    *offsets = malloc(sizeof(Offset) * offsetSize);
    *keys = malloc(sizeof(Key) * keySize);
    if (*offsets == NULL || *keys == NULL) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Initialize 'offset' structures with random unique values
    for (int i = 0; i < offsetSize; ++i) {
        (*offsets)[i].value = rand();
    }

    // Initialize 'key' structures
    for (int i = 0; i < keySize; ++i) {
        (*keys)[i].value = i;
    }

    // Allocate memory for 'record' structures and link them to 'offset' and 'key' structures based on index mapping
    *records = malloc(sizeof(Record) * recordSize);
    if (*records == NULL) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    for (int i = 0; i < recordSize; ++i) {
        // Check if index mapping exceeds the bounds of 'offset' and 'key' arrays
        if (indexMapping[i] >= offsetSize || indexMapping[i] >= keySize) {
            return ERROR_INDEX;
        }

        (*records)[i].unique_value = rand();
        (*records)[i].offset_ptr = &((*offsets)[indexMapping[i]]);
        (*records)[i].key_ptr = &((*keys)[indexMapping[i]]);
    }

    return 0; // Success
}
