    // Check if the allocation was successful
    if(new_timestamps != NULL && new_temperatures != NULL) {
        timestamps = new_timestamps;
        temperatures = new_temperatures;
    } else {
        printf("Memory allocation failed. The system will continue operating with reduced functionality.\n");
    }

    // Update sensor data
    for(int i = 0; i < num_sensors; i++) {
        sensors[i]->timestamp = timestamps[i];
        sensors[i]->temperature = temperatures[i];
    }
}

void add_sensor() {
    // Add a new sensor if there's room
    if(num_sensors < MAX_SENSORS) {
        sensors[num_sensors] = (sensor*) malloc(sizeof(sensor));

        // Check if the allocation was successful
        if(sensors[num_sensors] != NULL) {
            num_sensors++;
        } else {
            printf("Memory allocation failed. The system will continue operating with reduced functionality.\n");
        }
    }
}

void clear_memory() {
    // Free all allocated memory
    for(int i = 0; i < num_sensors; i++) {
        free(sensors[i]);
