```c
#include <stdlib.h> // For malloc and free
#include <time.h>  // For time (used in srand for rand_long)

// Structure definitions
typedef struct offset {
    long integer;
} Offset;

typedef struct key {
    int integer;
} Key;

typedef struct record {
    long integer;
    Offset* offset;
    Key* key;
    char* value;  // For simplicity, assume it's a dynamically allocated buffer
} Record;

// Function to manage memory for these structures.
int manage_memory(Offset* offsets, int num_offsets, 
                  Key* keys, int num_keys, 
                  char** values, int num_values,
                  Record* records, int num_records, 
                  int* index_mapping) {
    srand(time(0)); // For random number generation

    if (num_offsets < 0 || num_keys < 0 || num_values < 0 || num_records < 0) {
        return -1;  // Error: Negative array size.
    }

    for (int i = 0; i < num_records; ++i) {
        if (index_mapping[i] >= num_offsets || 
            index_mapping[num_keys + i] >= num_keys ||
            index_mapping[2 * num_records + i] >= num_values) {
                return -1;  // Error: Index out of bounds.
        }

        records[i].integer = rand_long();
        for (int j = 0; j < i; ++j) {
            if (records[j].integer == records[i].integer) {
                return -1;  // Error: Duplicate record integer.
            }
        }

        records[i].offset = &offsets[index_mapping[i]];
        records[i].key = &keys[index_mapping[num_records + i]];
        records[i].value = values[index_mapping[2 * num_records + i]];
    }

    return 0; // Success
}
