pthread_mutex_t lock;
char logBuffer[256]; // For simplicity we assume a fixed buffer size. In reality, you'd want to dynamically allocate and reallocate as necessary.

typedef struct transaction {
    int id;
    double timestamp;
    char *merchantName;
} transaction_t;

void* initTransactionArray(int userInputSize) {
    if (userInputSize <= 0) {
        fprintf(stderr, "Invalid input: size must be a positive integer\n");
        exit(EXIT_FAILURE);
    }

    transaction_t *transactions = malloc(sizeof(transaction_t) * userInputSize);
    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL; // Remember to free this before exit
    }

    srand(time(NULL)); // seed the random number generator

    for (int i = 0; i < userInputSize; ++i) {
        transactions[i].id = rand(); // Assumes a 32-bit int, which may not be true on all systems
        transactions[i].timestamp = ((double)clock() / CLOCKS_PER_SEC);
        // Assume merchant name index is within range and valid input. In reality you should check this first.
        int merchantNameIndex = rand() % MERCHANT_NAME_COUNT; 
        transactions[i].merchantName = strdup(merchantNames[merchantNameIndex]);

        pthread_mutex_lock(&lock); // Concurrent memory access protection.
        snprintf(logBuffer, sizeof(logBuffer), "Process %ld Initialized Transaction: {id: %d, timestamp: %f, merchantName: %s}\n", syscall(__NR_gettid), transactions[i].id, transactions[i].timestamp, transactions[i].merchantName);
        printf("%s", logBuffer);
        pthread_mutex_unlock(&lock);  // Release the lock.
    }

    return transactions;
}
