void HandleRequest(const tcp::resolver::iterator& iterator) {
    boost::asio::io_service io_service;
    tcp::socket socket(io_service);
    boost::system::error_code error = boost::asio::error::host_not_found;

    while (error && iterator != tcp::resolver::iterator()) {
        socket.close();
        socket.connect(*iterator++, error);
    }

    if (error) {
        throw boost::system::system_error(error);
    }

    // ... Handle GET request here
}

int main() {
    try {
        boost::asio::io_service io_service;
        tcp::resolver resolver(io_service);
        tcp::resolver::query query("localhost", "http");

        // Handle GET request on a separate thread to prevent blocking of the main thread
        boost::thread getRequestThread(boost::bind(&HandleRequest, resolver.resolve(query)));

        getRequestThread.join();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}
