    struct timeval timestamp;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 
FILE *logfile;
char **names; // assuming names are already predefined
int num_records, max_records = 1000;
record* records;

void initialize(long offset[], int key[], struct timeval start_time, struct timeval end_time) {
    if (offset <= 0 || key <= 0) {
        printf("Invalid input: values must be positive.\n");
        return;
    }

    num_records = offset > max_records ? max_records : offset;
    records = (record*)malloc(num_records * sizeof(record));

    if(records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for(int i = 0; i < num_records; ++i){
        int randKey = key[i % (sizeof(key)/sizeof(*key))]; // wrap around keys if necessary
        records[i].offset = offset[i % (sizeof(offset)/sizeof(*offset))]; 
        records[i].key = randKey; 
        records[i].name = names[rand() % sizeof(names) / sizeof(*names)]; // get random name from predefined list

        // generate a random timestamp within the given range
        struct timeval diff, delta;
        timersub(&end_time, &start_time, &diff);
        long mc_sec = (rand() % (diff.tv_sec * 1000000 + diff.tv_usec)) / 1000; // convert to milliseconds

        delta.tv_sec = mc_sec / 1000;
        delta.tv_usec = (mc_sec % 1000) * 1000;
        timeradd(&start_time, &delta, &(records[i].timestamp));

        pthread_mutex_lock(&lock); // lock for thread safety
        fprintf(logfile, "Initialized record %d with offset %ld, key %d, name %s, and timestamp %ld:%ld\n", i, records[i].offset, records[i].key, records[i].name, records[i].timestamp.tv_sec, records[i].timestamp.tv_usec);
        pthread_mutex_unlock(&lock);
    }
}
