int addRecord(long offset, int key, char* name, unsigned int timestamp) {
    // Validate inputs and check for overflows before adding to avoid buffer overflows
    pthread_mutex_lock(&lock);
    if (db_index < 100) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            pthread_mutex_unlock(&lock);
            return -1; // Memory allocation failed
        }

        record->offset = offset;
        record->key = key;
        record->name = name;
        record->timestamp = timestamp;

        database[db_index] = record;
        int index = db_index++;
        pthread_mutex_unlock(&lock);
        return index; // Successfully added, returns the index of the added record
    } else {
        pthread_mutex_unlock(&lock);
        return -1; // Database is full
    }
}

