["Here is an implementation for the task in C. I've used separate chaining to handle collisions, resizing when load factor exceeds a threshold (0.75), and linear probing as the hash function. I also added some basic error checking to clean up resources if any allocation fails. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t numBuckets;
    size_t bucketSize;
    size_t numRecords;
} HashTable;

HashTable* createHashTable(size_t initialNumBuckets, size_t bucketSize) {
    HashTable* hashTable = malloc(sizeof(HashTable));
    if (hashTable == NULL) return NULL;

    hashTable->buckets = calloc(initialNumBuckets, sizeof(Node*));
    if (hashTable->buckets == NULL) {
        free(hashTable);
        return NULL;
    }

    hashTable->numBuckets = initialNumBuckets;
    hashTable->bucketSize = bucketSize;
    hashTable->numRecords = 0;

    for (size_t i = 0; i < initialNumBuckets; ++i) {
        hashTable->buckets[i] = NULL;
    }

    return hashTable;
}

void destroyHashTable(HashTable* hashTable) {
    if (hashTable == NULL) return;

    for (size_t i = 0; i < hashTable->numBuckets; ++i) {
        Node* node = hashTable->buckets[i];

        while(node != NULL) {
            Node* nextNode = node->next;
            free(node);
            node = nextNode;
        }
    }

    free(hashTable->buckets);
    free(hashTable);
}

size_t hashFunction(const char* key, size_t numBuckets) {
    // Implement a basic hash function for illustration purposes. Replace with your own if necessary.
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % numBuckets;
}

int insertRecord(HashTable* hashTable, const char* key, int value) {
    if (hashTable == NULL || key == NULL) return -1;

    if ((double)hashTable->numRecords / hashTable->numBuckets > 0.75) {
        // Resizing the table when load factor exceeds 0.75
        size_t newNumBuckets = hashTable->numBuckets * 2;

        Node** newBuckets = calloc(newNumBuckets, sizeof(Node*));
        if (newBuckets == NULL) return -1;

        for (size_t i = 0; i < hashTable->numBuckets; ++i) {
            Node* node = hashTable->buckets[i];

            while(node != NULL) {
                size_t newHash = hashFunction(node->record.key, newNumBuckets);

                // Insert the node at the front of the bucket
                Node* nextNode = node->next;
                node->next = newBuckets[newHash];
                newBuckets[newHash] = node;
                node = nextNode;
            }
        }

        free(hashTable->buckets);
        hashTable->buckets = newBuckets;
        hashTable->numBuckets = newNumBuckets;
    }

    size_t hash = hashFunction(key, hashTable->numBuckets);
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return -1;

    node->record.key = strdup(key);
    if (node->record.key == NULL) {
        free(node);
        return -1;
    }

    node->record.value = value;
    node->next = hashTable->buckets[hash];
    hashTable->buckets[hash] = node;
    ++hashTable->numRecords;

    return 0;
}
```
This is a basic implementation and can be further optimized for specific use cases. It doesn't include methods to remove records or get the value associated with a given key, which would require additional functionality. Please replace `hashFunction` with your own if necessary according to your application's requirements. You may also want to add error checking for `strdup` and other functions to ensure that all allocations are successful before continuing.
