['Below is a basic implementation in C language using dynamically allocated arrays, mutex for thread safety and a simple cache mechanism. It doesn't handle errors or edge cases properly. Please refactor it according to your needs. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    char* parameters; // assuming L1 parameters are strings, adjust as needed
} mac_entity_config;

mac_entity_config** configurations = NULL;
int count = 0;
int capacity = 0;
pthread_mutex_t lock;

void resize() {
    if (count >= capacity) {
        int newCapacity = capacity == 0 ? 1 : capacity * 2;
        mac_entity_config** newConfigs = realloc(configurations, newCapacity * sizeof(mac_entity_config*));

        // Handle failed allocation.
        if (newConfigs == NULL) {
            printf("Failed to allocate memory.\n");
            exit(-1);
        }

        configurations = newConfigs;
        capacity = newCapacity;
    }
}

void add_config(mac_entity_config* config) {
    pthread_mutex_lock(&lock);

    resize();

    for (int i = 0; i < count; ++i) {
        if (configurations[i]->id == config->id) {
            configurations[i] = config; // Update the existing configuration.
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    configurations[count++] = config;
    pthread_mutex_unlock(&lock);
}

mac_entity_config* get_config(int id) {
    // Simple cache implementation - just checking first element. 
    if (count > 0 && configurations[0]->id == id) return configurations[0];

    pthread_mutex_lock(&lock);
    for (int i = 0; i < count; ++i) {
        if (configurations[i]->id == id) {
            // Cache the recently accessed configuration.
            mac_entity_config* temp = configurations[i];

            for(int j=i-1; j>=0; --j){
                configurations[j+1] = configurations[j]; 
            }

            configurations[0] = temp;

            pthread_mutex_unlock(&lock);
            return temp;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL; // No configuration found.
}

void clear() {
    for (int i = 0; i < count; ++i) free(configurations[i]);
    free(configurations);

    configurations = NULL;
    capacity = 0;
    count = 0;
}
```

Remember to initialize the mutex using `pthread_mutex_init(&lock, NULL);` and destroy it at the end of usage with `pthread_mutex_destroy(&lock);`. Don't forget to also free memory allocated for each `mac_entity_config` object when you no longer need them.
']

