pthread_mutex_t lock;

void initArray() {
    if(array != NULL) return; // Array already initialized

    pthread_mutex_init(&lock, NULL);  // Initialize the lock

    array = malloc(sizeof(record*) * capacity);
    if (array == NULL) {
        spdlog::error("Memory allocation failed");
        exit(-1);
    }
}

void addToArray(long offset, int key, char* name){
    pthread_mutex_lock(&lock);  // Lock for thread safety

    if (size >= capacity) {
        capacity *= 2;   // Double the size of array when full

        record** newArray = realloc(array, sizeof(record*) * capacity);
        if (newArray == NULL) {
            spdlog::error("Memory allocation failed");
            pthread_mutex_unlock(&lock);  // Unlock the lock before returning
            return;
        }

        array = newArray;
    }

    record* rec = malloc(sizeof(record));
    if (rec == NULL) {
        spdlog::error("Memory allocation failed");
        pthread_mutex_unlock(&lock);  // Unlock the lock before returning
        return;
    }

    rec->offset = offset;
    rec->key = key;
    rec->name = name;

    array[size++] = rec;  // Add new record to end of array

    pthread_mutex_unlock(&lock);  // Unlock the lock after modification
}

