    {
        if (inMemoryProcessing)
        {
            using var image = Image.FromFile(imagePath); // Using System.Drawing.Common library
            _metadata[imagePath] = $"{format}: In-memory processing";
        }
        else
        {
            using var fileStream = new FileStream(imagePath, FileMode.Open);
            using var archive = RarArchive.Open(fileStream); // Using SharpCompress library

            _metadata[imagePath] = $"{format}: Disk-backed processing";
