    {
        _metadata[imagePath] = newMetaData;
    }

    // Other methods like DeleteImage(), RetrieveImage() etc. would also be present here

    protected virtual void Dispose(bool disposing)
    {
        if (!disposedValue)
        {
            if (disposing)
            {
                _imageData?.Clear();
                _metadata?.Clear();
            }

            disposedValue = true;
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}
