void initialize(Record** records, size_t size) {
    *records = malloc(sizeof(Record) * size);
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        (*records)[i].offset = i * 10;
        (*records)[i].key = -1;
    }
}

void populate_names(Record* records, size_t size) {
    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        int index = rand() % NAME_COUNT;
        char* name = malloc(sizeof(char) * (strlen(names[index]) + 15)); // 15 is to handle the case of duplicate names with a unique identifier
        sprintf(name, "%s%d", names[index], i);
        records[i].name = name;
    }
}

void set_keys(Record* records, size_t size) {
    int* keys = calloc(MAX_SIZE, sizeof(int)); // Assuming that MAX_SIZE is the maximum possible key value

    for (int i = 0; i < size; ++i) {
        while (1) {
            int new_key = rand() % MAX_SIZE;

            if (!keys[new_key]) {
                keys[new_key] = 1;
                records[i].key = new_key;
                break;
            }
        }
    }

    free(keys);
}

void log_records(Record* records, size_t size) {
    FILE* fp = fopen("log.txt", "w");
    if (fp == NULL) {
        perror("Failed to open the file");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        fprintf(fp, "Record %d: Offset = %ld, Key = %d\n", i, records[i].offset, records[i].key);
    }

    fclose(fp);
}

void free_records(Record* records, size_t size) {
    for (int i = 0; i < size; ++i) {
        free(records[i].name);
    }

    free(records);
}

int main() {
    Record* records = NULL;
    size_t size = 1500;

    initialize(&records, size);
    populate_names(records, size);
    set_keys(records, size);
    log_records(records, size);
    free_records(records, size);
}
