} record;

void *allocate_and_initialize(size_t size, void **mem) {
    assert((*mem = malloc(size)) != NULL);
    return *mem;
}

void generate_values(long *offsets, int *keys, record *records, int seed, long offsetRange, int n) {
    srand(seed);

    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % offsetRange;
        keys[i] = seed++;

        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }
}

int verify_records(record *records, int n) {
    for (int i = 0; i < n - 1; ++i) {
        if (records[i].key >= records[i+1].key || 
            records[i].offset != records[i+1].offset ) {
            return 0;
        }
    }
    return 1;
}

void manage_memory(long *offsets, int *keys, record *records, size_t size) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

void manage_memory_threaded(long *offsets, int *keys, record *records, size_t size, pthread_mutex_t *lock) {
    pthread_mutex_lock(lock); 
    manage_memory(offsets, keys, records, size);
    pthread_mutex_unlock(lock);
}

int initialize_arrays(long **offsets, int **keys, record **records, int seed, long offsetRange, int n) {
    size_t size = sizeof(long) * n;

    if (allocate_and_initialize(size, (void**)offsets) == NULL || 
        allocate_and_initialize(sizeof(int) * n, (void**)keys) == NULL ||
        allocate_and_initialize(sizeof(record) * n, (void**)records) == NULL) {
            manage_memory(*offsets, *keys, *records, size);  // Clean up on error
            return -1;  
    }

    generate_values(*offsets, *keys, *records, seed, offsetRange, n);
    assert(verify_records(*records, n));

    return 0;
}
