public:
    void ManageDialogFields(const std::vector<std::string>& fieldNamesToRefresh, const std::string& url) {
        try {
            for (auto it = dialogFields.begin(); it != dialogFields.end() && !fieldNamesToRefresh.empty(); ++it) {
                auto fieldNameIt = std::find(fieldNamesToRefresh.begin(), fieldNamesToRefresh.end(), *it);

                if (fieldNameIt != fieldNamesToRefresh.end()) {
                    // If a match is found, send a message to the parent window and wait for a response
                    auto result = std::async(std::launch::async, [&url](){ 
                        // Assuming this function sends a request to the URL and returns a boolean indicating success
                        return SendMessageAndWaitForResponse(url);  
                    });

                    if (result.get()) {
                        // If the response indicates success, update the dialog field accordingly
                        *it = "Updated: " + *fieldNameIt;
                    } else {
                        std::cout << "Failed to refresh field: " << *fieldNameIt << std::endl;
                    }
                }
            }

            // If no match is found, append the field name to the end of the forward list
            for (const auto& fieldName : fieldNamesToRefresh) {
                if (std::find(dialogFields.begin(), dialogFields.end(), fieldName) == dialogFields.end()) {
                    // Ensure the size doesn't exceed the limit by removing old entries
                    while (dialogFields.size() >= MAX_SIZE) {
                        dialogFields.pop_front();
                    }

                    dialogFields.push_front(fieldName);
                }
            }
        } catch (const std::exception& e) {
            // Catch and handle exceptions gracefully
