typedef struct data_point {
    double value;
    enum category{CATEGORY1, CATEGORY2} category;
    char* timestamp; 
}data_point;

void initialize(int size) {
    // validate input
    if (size <= 0) {
        printf("Invalid size");
        return;
    }

    // allocate memory for arrays
    double* measurements = malloc(size * sizeof(double));
    enum category* categories = malloc(size * sizeof(enum category));

    if (measurements == NULL || categories == NULL) {
        printf("Memory allocation failed\n");
        free(measurements);
        free(categories);
        return;
    }

    // initialize arrays
    for (int i = 0; i < size; ++i){
        measurements[i] = rand();
        categories[i] = CATEGORY1;
    }

    data_point* points = malloc(size * sizeof(data_point));

    if (points == NULL) {
        printf("Memory allocation failed\n");
        free(measurements);
        free(categories);
        free(points);
        return;
    }

    for (int i = 0; i < size; ++i){
        points[i].value = measurements[i];
        points[i].category = categories[i];

        // get current time
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        points[i].timestamp = malloc((strlen(timestamp) + 1) * sizeof(char));
        if (points[i].timestamp == NULL){
            printf("Memory allocation failed\n");
            free(measurements);
            free(categories);
            for (int j = 0; j < i; ++j) {
                free(points[j].timestamp);
            }
            free(points);
            return;
        } 

        strncpy(points[i].timestamp, timestamp, strlen(timestamp));
    }
}
