        devices[i].configFilePath = strdup("/path/to/default/config");
        devices[i].timestamp = time(NULL);
    }

    return devices;
}

void setStatusCodes(DeviceConfig* devices, int size, const int* indices) {
    for (int i = 0; i < size; ++i) {
        if (indices[i] >= ONLINE && indices[i] <= ERROR) {
            devices[i].status = indices[i];
        } else {
            // handle out of bounds indices with default value
            devices[i].status = OFFLINE;
        }
    }
}
