            var cts = new CancellationTokenSource();
            var process = Process.Start("appcmd", $"add site /name:{siteName} /physicalPath:{directoryPath}");
            if (process == null) return null; // If the process fails, return null

            cts.CancelAfter(GetTimeoutDuration(directoryPath)); // Set timeout duration based on directory size or complexity

            await RunProcessAsync(cts, process); // Wait for the process to finish asynchronously
        }
        catch (Exception ex)
        {
            Logger.Error(ex); // Log error and handle gracefully
        }
    }

    private async Task RunProcessAsync(CancellationTokenSource cts, Process process)
    {
        while (!process.HasExited && !cts.IsCancellationRequested) await Task.Delay(100); // Wait for the process to finish

        if (process.ExitCode != 0) Logger.Error("Process exited with code " + process.ExitCode); // Handle failed processes gracefully
    }

