```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double num;
    char id[100];
    size_t counter;
} StructElement;

void allocateMemory(size_t size) {
    // Allocate memory for arrays
    double* arrDouble = (double*) malloc(size * sizeof(double));
    if (arrDouble == NULL) {
        printf("Error: Failed to allocate memory for array of doubles.\n");
        exit(1);
    }

    char (*arrChar)[100] = malloc(size * sizeof(*arrChar));
    if (arrChar == NULL) {
        printf("Error: Failed to allocate memory for array of char arrays.\n");
        free(arrDouble);
        exit(1);
    }

    StructElement* arrStruct = malloc(size * sizeof(StructElement));
    if (arrStruct == NULL) {
        printf("Error: Failed to allocate memory for array of structs.\n");
        free(arrDouble);
        free(arrChar);
        exit(1);
    }

    // Initialize arrays
    srand(time(NULL));
    double range_min = -1.0;
    double range_max = 1.0;
    for (size_t i = 0; i < size; i++) {
        double randomValue = range_min + ((double) rand() / RAND_MAX) * (range_max - range_min);
        arrDouble[i] = randomValue;

        sprintf(arrChar[i], "ID%zu", i + 1);  // Initialize char array with unique identifier

        arrStruct[i].num = randomValue;
        strcpy(arrStruct[i].id, arrChar[i]);  // Copy the id to the struct's id field
        arrStruct[i].counter = 0;  // Initialize counter to zero
    }

    // ... Use the arrays as needed...

    // Free allocated memory
    free(arrDouble);
    free(arrChar);
    free(arrStruct);
}
```
This function first allocates memory for the three arrays. If any of these allocations fail, it prints an error message and terminates the program. It then initializes each array with a random value between -1.0 and 1.0 for the `double` array and unique identifiers based on the index for the `char` array. The third array is initialized with structs that contain a copy of these values.

After using the arrays, the function frees all allocated memory to prevent memory leaks. It handles this by freeing each individual array after use, which ensures that all memory gets properly deallocated even if an error occurs during allocation or initialization. This design choice minimizes the impact of memory fragmentation and guarantees that all memory is correctly freed when it's no longer needed.
