        char *name = malloc(MAX_NAME_LENGTH);
        if(name == NULL) {
            printf("Memory allocation failed!\n");
            exit(0); 
        }

        strcpy(name, names[index]);
        records[i].offset = 0;
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].name = name;
    }

    // Free memory when done
    for(int i=0; i<num_records; ++i){
        free(records[i].name); 
    }
    free(records); 
