['Here's an example solution in C using pthread library for thread safety and logging with a hypothetical log function 'log_message'. 

```C
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

void* allocateAndInitialize(size_t numRecords, long minOffset, long maxOffset, int minKey, int maxKey, 
                             int minValue, int maxValue) {

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize random seed.
    srand(time(NULL));

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        log_message("Error: Memory allocation for offset array failed!");
        return NULL;
    }

    int* keys = (int*)malloc(numRecords * sizeof(int));
    if (!keys) {
        free(offsets);
        log_message("Error: Memory allocation for key array failed!");
        return NULL;
    }

    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    if (!records) {
        free(offsets);
        free(keys);
        log_message("Error: Memory allocation for record array failed!");
        return NULL;
    }

    // Initialize arrays.
    for (size_t i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&mutex);

        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);

        keys[i] = minKey + rand() % (maxKey - minKey + 1);

        Record* record = malloc(sizeof(Record));
        if (!record) {
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);

            log_message("Error: Memory allocation for record failed!");
            return NULL;
        }

        record->value = minValue + rand() % (maxValue - minValue + 1);
        records[i] = record;

        pthread_mutex_unlock(&mutex);
    }

    log_message("Memory allocation and initialization successful.");

    // Pack everything into a void pointer for return.
    void* ret = malloc(3 * sizeof(void*));
    ((void**)ret)[0] = offsets;
    ((void**)ret)[1] = keys;
    ((void**)ret)[2] = records;

    return ret;
}
```
Please note that the 'log_message' function used here is a hypothetical function and you need to replace it with your actual logging library. Also, remember that this is just an example and doesn't cover all the constraints and engineering trade-offs mentioned in your question due to space constraints. It would be beneficial to further break down the task into smaller tasks and implement them one by one.
