// Define a struct for the event record
typedef struct {
    int id;
    char* name;
    float value;
} EventRecord;

// Define a struct for the dynamic arrays
typedef struct {
    float* floats;
    double* timestamps;
    EventRecord* events;
    size_t floatCount;
    size_t timestampCount;
    size_t eventCount;
} DynamicArrays;

// Function to initialize the dynamic arrays
DynamicArrays* initArrays() {
    DynamicArrays* arrays = (DynamicArrays*) malloc(sizeof(DynamicArrays));
    if (arrays == NULL) {
        // Handle memory allocation error
    } else {
        arrays->floatCount = 0;
        arrays->timestampCount = 0;
        arrays->eventCount = 0;
    }
    return arrays;
}

// Function to add a float to the array
void addFloat(DynamicArrays* arrays, float value) {
    arrays->floats = (float*) realloc(arrays->floats, sizeof(float) * (arrays->floatCount + 1));
    if (arrays->floats == NULL) {
        // Handle memory allocation error
    } else {
        arrays->floats[arrays->floatCount++] = value;
    }
}

// Function to add a timestamp to the array
void addTimestamp(DynamicArrays* arrays, double timestamp) {
    arrays->timestamps = (double*) realloc(arrays->timestamps, sizeof(double) * (arrays->timestampCount + 1));
    if (arrays->timestamps == NULL) {
        // Handle memory allocation error
    } else {
        arrays->timestamps[arrays->timestampCount++] = timestamp;
    }
}

// Function to add an event record to the array
void addEvent(DynamicArrays* arrays, int id, char* name, float value) {
    if (name == NULL || strlen(name) == 0) {
        // Handle invalid input error
    } else {
        EventRecord newRecord = {id, name, value};
        arrays->events = (EventRecord*) realloc(arrays->events, sizeof(EventRecord) * (arrays->eventCount + 1));
        if (arrays->events == NULL) {
            // Handle memory allocation error
        } else {
            arrays->events[arrays->eventCount++] = newRecord;
        }
    }
}

// Function to retrieve the average of all float values
float getAverageFloats(DynamicArrays* arrays) {
    if (arrays->floatCount == 0) {
        // Handle division by zero error
    } else {
        float sum = 0;
        for (size_t i = 0; i < arrays->floatCount; ++i) {
