void readFromFile(Processor** processors, int* size) {
    FILE *file = fopen("data.txt", "r"); // open file in read mode
    if (file == NULL) {
        printf("Could not open file\n");
        exit(-1);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        double val;
        char str[30], chr;
        sscanf(line, "%lf %s %c", &val, str, &chr); // read a line from the file

        *processors = realloc(*processors, (*size + 1) * sizeof(Processor));
        if (*processors == NULL) {
            printf("Memory allocation failed\n");
            exit(-1);
        }

        Processor* newProc = malloc(sizeof(Processor));
        newProc->dbl = val;
        newProc->str = strdup(str);
        newProc->elem = malloc(sizeof(Element));
        newProc->elem->value = (float)val;
        newProc->elem->str = strdup(&chr);

        (*processors)[(*size)++] = *newProc;
    }

    fclose(file); // close the file
}
```
