```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming a record structure like this
typedef struct {
    int value;
} Record;

// Global hash table and array of long offsets
int* keys;
long* offsets;
Record** records;

// Hash table size and capacity
size_t size = 0;
size_t capacity = 1024;  // Initial capacity for the hash table
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init() {
    keys = calloc(capacity, sizeof(int));
    offsets = calloc(capacity, sizeof(long));
    records = calloc(capacity, sizeof(Record*));
}

// Simple hash function for demonstration purposes
size_t hash(int key) { return (key % capacity + capacity) % capacity; }

void insert(int key, Record* record) {
    size_t index = hash(key);
    pthread_mutex_lock(&lock);
    while (records[index] != NULL && keys[index] != key) 
        index = (index + 1) % capacity;
    if (records[index] == NULL) {
        ++size;
        // Resize hash table when load factor exceeds threshold
        if ((double) size / capacity > 0.7) resize();
    }
    keys[index] = key;
    records[index] = record;
    pthread_mutex_unlock(&lock);
}

Record* get(int key) {
    size_t index = hash(key);
    pthread_mutex_lock(&lock);
    while (records[index] != NULL && keys[index] != key) 
        index = (index + 1) % capacity;
    Record* result = records[index];
    pthread_mutex_unlock(&lock);
    return result;
}

void resize() {
    capacity *= 2;
    keys = realloc(keys, sizeof(int) * capacity);
    offsets = realloc(offsets, sizeof(long) * capacity);
    records = realloc(records, sizeof(Record*) * capacity);
    memset(keys + size, 0, (capacity - size) * sizeof(int));
    memset(offsets + size, 0, (capacity - size) * sizeof(long));
    memset(records + size, 0, (capacity - size) * sizeof(Record*));
}

void cleanup() {
    free(keys);
    free(offsets);
    for (size_t i = 0; i < capacity; ++i) if (records[i] != NULL) free(records[i]);
    free(records);
}
```

The above code is a simplified version and does not take into account all your constraints. It only demonstrates how you can implement a hash table using open addressing with linear probing for collision resolution, as well as how to handle concurrent accesses using `pthread_mutex_t` locks. For more complex memory management or custom allocation strategies, a more intricate solution would be needed. Please note that this code does not consider the cache line size and data layout issues which can significantly affect performance in multithreaded environments. You might also want to replace `calloc()` with custom allocators for better control over alignment and fragmentation.
