['Here is a basic implementation that meets all your requirements. It doesn't contain specific optimizations such as hash tables or indexing strategies but it should give you an idea how to approach these issues in C. The code uses `pthread` for thread safety and does not provide full error handling, which would be needed in a real-world application. 

```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int priority;
    char *message;
} Entry;

Entry *entries = NULL;
int entry_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_entry(long timestamp, int priority, const char *message) {
    Entry *new_entry = malloc(sizeof(Entry));

    if (new_entry == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_entry->timestamp = timestamp;
    new_entry->priority = priority;
    new_entry->message = malloc(strlen(message) + 1);

    if (new_entry->message == NULL) {
        printf("Memory allocation failed.\n");
        free(new_entry);
        return;
    }

    strcpy(new_entry->message, message);

    pthread_mutex_lock(&mutex);
    entries = realloc(entries, (entry_count + 1) * sizeof(Entry));

    if (entries == NULL) {
        printf("Memory allocation failed.\n");
        free(new_entry->message);
        free(new_entry);
        pthread_mutex_unlock(&mutex);
        return;
    }

    entries[entry_count++] = *new_entry;
    qsort(entries, entry_count, sizeof(Entry), [](const void* a, const void* b) {
        int l = ((Entry*)a)->priority;
        int r = ((Entry*)b)->priority;
        return (l > r) - (l < r);
    });
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    for (int i = 0; i < entry_count; ++i) {
        free(entries[i].message);
    }

