void parseJson(char* json) {
    cJSON *jsonObject = cJSON_Parse(json);
    if (jsonObject == NULL) {
        const char *errorPointer = cJSON_GetErrorPtr();
        if (errorPointer != NULL) {
            fprintf(stderr, "Error before: %s\n", errorPointer);
        }
        return;
    }

    UserProfile* profile = g_new0(UserProfile, 1);
    cJSON *item = NULL;

    item = cJSON_GetObjectItemCaseSensitive(jsonObject,"name");
    if (cJSON_IsString(item) && (item->valuestring != NULL)) {
        profile->name = g_strdup(item->valuestring);
    } else {
        syslog(LOG_WARNING, "Missing required field: name");
        return;
    }

    item = cJSON_GetObjectItemCaseSensitive(jsonObject,"age");
    if (cJSON_IsNumber(item)) {
        profile->age = item->valueint;
        if (profile->age > maxAge) {
            maxAge = profile->age;
            oldestPerson = profile;
        }
    } else {
        syslog(LOG_WARNING, "Missing required field: age");
        return;
    }

    item = cJSON_GetObjectItemCaseSensitive(jsonObject,"email");
    if (cJSON_IsString(item) && (item->valuestring != NULL)) {
        profile->email = g_strdup(item->valuestring);
    } else {
        syslog(LOG_WARNING, "Missing required field: email");
        return;
    }

    item = cJSON_GetObjectItemCaseSensitive(jsonObject,"registration_timestamp");
    if (cJSON_IsNumber(item)) {
        profile->registration_timestamp = item->valueint;
    } else {
        syslog(LOG_WARNING, "Missing required field: registration_timestamp");
        return;
    }

    // Add to HashTable for efficient lookups
    g_hash_table_add(userProfileTable, profile->email, profile);
}
