typedef struct {
    double temperature;
    char* city_name;
    time_t timestamp;
} weather_data;

// Function to reallocate memory in a custom strategy
void *custom_realloc(void *ptr, size_t old_size, size_t new_size) {
    void *new_ptr = NULL;

    // Check if old_size is 0 and return malloc result
    if (old_size == 0 && new_size != 0) {
        return malloc(new_size);
    }

    // Allocate a new block of memory
    new_ptr = realloc(ptr, new_size);
    if (new_ptr == NULL) {
        free(ptr);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    return new_ptr;
}

// Function to parse comma-separated city names into an array of strings
char** parse_city_names(char *cities, int count) {
    char **city_names = (char**)malloc(count * sizeof(char*));
    if (city_names == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    char *token = strtok(cities, ",");
    for (int i = 0; token != NULL && i < count; ++i) {
        city_names[i] = malloc((strlen(token) + 1) * sizeof(char));
        if (city_names[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        strcpy(city_names[i], token);
        token = strtok(NULL, ",");
    }

    return city_names;
}

// Function to simulate weather data generation
void generate_forecast(weather_data *data, int count, double min_temp, double max_temp) {
    srand((unsigned int)time(NULL)); // Use current time as seed for random generator

    for (int i = 0; i < count; ++i) {
        data[i].temperature = min_temp + ((double)rand() / RAND_MAX) * (max_temp - min_temp);
        data[i].timestamp = time(NULL);

        printf("Generated forecast for %s at %ld: Temperature is %.2f\n", 
               data[i].city_name, data[i].timestamp, data[i].temperature);
    }
}

// Main function to manage weather data
void manage_weather_data(int capacity, char *cities, double min_temp, double max_temp) {
    // Allocate memory for city names and temperatures
    char **city_names = parse_city_names(cities, capacity);

    // Allocate memory for weather data structures
    weather_data *data = (weather_data*)malloc(capacity * sizeof(weather_data));
    if (data == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize weather data structures
    for (int i = 0; i < capacity; ++i) {
        data[i].city_name = city_names[i];
    }

    // Generate simulated forecasts
    generate_forecast(data, capacity, min_temp, max_temp);

    // Free allocated memory
    for (int i = 0; i < capacity; ++i) {
        free(city_names[i]);
    }
    free(city_names);
    free(data);
}
```
