} Record;

char *names[] = {"Alice", "Bob", "Charlie", "David"}; // predefined list of names

void *name_selector(void *arg) {
    int index = (intptr_t) arg;
    char *selected_name = malloc(strlen(names[index]) + 1);
    if (selected_name == NULL) {
        printf("Failed to allocate memory for name\n");
        pthread_exit(NULL);
    }
    strcpy(selected_name, names[index]);
    return selected_name;
}

void *rand_generator(void *arg) {
    int range = (intptr_t) arg;
    unsigned char rand_buf[4]; // we use 32 bit random numbers for simplicity
    RAND_bytes(rand_buf, sizeof(rand_buf));
    return (void*)(*(uint32_t*)rand_buf % range);
}

int main() {
    int size;
    printf("Enter the size of arrays: ");
    scanf("%d", &size);

    if (size <= 0) {
        printf("Invalid input. Please enter a positive integer.\n");
        return 1;
