['Here is a high level C implementation of your problem statement using mutex for thread synchronization and memory pool for efficient resource management. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

typedef struct Record {
    int key;
    char* string;
    size_t refCount;
    pthread_mutex_t lock;
} Record;

Record** records = NULL;
size_t numRecords = 0;
pthread_mutex_t globalLock;

int allocateMemory(void** buffer, size_t size) {
    *buffer = malloc(size);
    if (*buffer == NULL) {
        printf("Failed to allocate memory\n");
        return -1;
    }
    return 0;
}

Record* createRecord(int key, const char* string, size_t bufferSize) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        printf("Failed to allocate memory for record\n");
        return NULL;
    }
    pthread_mutex_init(&record->lock, NULL);

    size_t len = strlen(string);
    if (len > bufferSize - 1) {
        printf("String length exceeds buffer size\n");
        free(record);
        return NULL;
    }
    record->key = key;
    record->refCount = 0;

    allocateMemory((void**)&record->string, len + 1);
    strncpy(record->string, string, bufferSize - 1);
    record->string[len] = '\0';

    return record;
}

int addRecord(int key, const char* string, size_t bufferSize) {
    pthread_mutex_lock(&globalLock);
    Record* newRecord = createRecord(key, string, bufferSize);
    if (newRecord == NULL) {
        pthread_mutex_unlock(&globalLock);
        return -1;
    }

    numRecords++;
    records = realloc(records, sizeof(Record*) * numRecords);
    if (records == NULL) {
        printf("Failed to allocate memory for records\n");
        pthread_mutex_unlock(&globalLock);
        return -1;
    }
    records[numRecords - 1] = newRecord;

    pthread_mutex_unlock(&globalLock);
    return numRecords - 1;
}

void incrementRefCount(int index) {
    assert(index >= 0 && index < numRecords);
    Record* record = records[index];
    pthread_mutex_lock(&record->lock);
    record->refCount++;
    pthread_mutex_unlock(&record->lock);
}

void freeRecord(Record* record) {
    if (record == NULL) return;

    if (record->string != NULL) {
        free(record->string);
    }
    pthread_mutex_destroy(&record->lock);
    free(record);
}

void cleanup() {
    for (size_t i = 0; i < numRecords; i++) {
        freeRecord(records[i]);
    }
    free(records);
    pthread_mutex_destroy(&globalLock);
}
```

This code creates a dynamic collection of records. It uses a mutex to protect the global data structures from concurrent access, ensuring that only one thread can modify the records at a time. Each record has its own mutex to ensure safety when modifying its reference count. 

The cleanup function frees all allocated memory in reverse order of their allocation. It also destroys any remaining mutexes for correct termination.

This code is not yet fully optimized and lacks error checking, you would need to add these features to make this solution robust. For example, it does not limit the total system memory usage as per requirement. This can be added by adding a global counter that keeps track of total allocation size, which can be used to check if an additional record fits into available space before allocating. 

It also lacks thread safety for concurrent write accesses (creating new records) and potential read-write contention on individual records (incrementing ref count). For now, these operations are serialized using the global mutex to avoid inconsistencies due to race conditions. It would be more efficient if we can use a lock striping or per-record locks strategy.
']

['Here is a simplified example of what such a system might look like using POSIX threading and C99:

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include <time.h>
#include <stdlib.h>

// Custom data types
typedef struct {
    int32_t key;
    char* string;
    atomic_uint_fast64_t refCount;
} AccountRecord;

// System-wide state variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
AccountRecord** accountRecords;
int recordLimit = 1000000000; // 1 billion records
size_t memPoolSize = 1 << 30; // 1 GB memory pool
void* memPool = NULL;
size_t memUsed = 0;
atomic_uint_fast64_t accountCount = 0;

// Account creation and management functions
AccountRecord* createAccount(int key, char* string) {
    if (accountCount >= recordLimit) return NULL; // Overflow condition

    pthread_mutex_lock(&mutex);
    size_t size = sizeof(AccountRecord) + strlen(string) + 1;

    if (memUsed + size > memPoolSize) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Memory limit exceeded
    }

    AccountRecord* record = malloc(size);
    if (!record) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Allocation failed
    }

    record->key = key;
    strcpy(record->string, string);
    atomic_init(&record->refCount, 0);

    accountRecords[accountCount++] = record;
    memUsed += size;

    pthread_mutex_unlock(&mutex);
    return record;
}

AccountRecord* findAccount(int key) {
    for (size_t i = 0; i < accountCount; ++i) {
        if (accountRecords[i]->key == key) {
            atomic_fetch_add(&accountRecords[i]->refCount, 1); // Increment reference count
            return accountRecords[i];
        }
    }

    return NULL; // No matching account found
}

void destroyAccount(int key) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < accountCount; ++i) {
        if (accountRecords[i]->key == key) {
            // Decrement reference count and free if 0
            if (atomic_fetch_sub(&accountRecords[i]->refCount, 1) == 1) {
                memUsed -= sizeof(AccountRecord) + strlen(accountRecords[i]->string);
                free(accountRecords[i]);

                // Shift remaining records left
                for (size_t j = i; j < accountCount - 1; ++j) {
                    accountRecords[j] = accountRecords[j + 1];
                }

                --accountCount;
            }

            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}
```

Please note that this is a simplified example and lacks many important features for production-level systems, such as error handling, memory management strategies, concurrent access controls, logging integrations, etc. Also, due to complexity of real world scenarios, the dynamic allocation strategy used here could be inefficient and may need further optimization.
