void* init(size_t limit, size_t bufferSize, unsigned maxKey) {
    srand(time(NULL));

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for 'offset' and 'key' arrays.
    long* offsets = malloc(limit * sizeof(long));
    int* keys = malloc(limit * sizeof(int));

    size_t stringSize = 0;
