    // Generate random strings and 'offset' values for each record.
    for (size_t i = 0; i < limit && stringSize <= bufferSize; ++i) {
        pthread_mutex_lock(&lock);

        offsets[i] = rand();
        keys[i] = rand() % maxKey + 1;  // Random value within given range.
        size_t strLength = rand() % bufferSize - stringSize + 2;  // Ensure total length does not exceed buffer size.

        pthread_mutex_unlock(&lock);

        records[i].key = keys[i];
        records[i].offset = offsets[i];

        // Generate random string of specified length for each record's 'char*' field.
        char *str = malloc(sizeof(char) * strLength);
        for (int j = 0; j < strLength - 1; ++j) {
            pthread_mutex_lock(&lock);

            // Generate random ASCII characters between 'A' and 'Z'.
            str[j] = rand() % ('Z' - 'A') + 'A';

            pthread_mutex_unlock(&lock);
        }

        str[strLength - 1] = '\0';  // Null-terminate the string.
        records[i].string = str;

        stringSize += strLength;
    }

    return records;
}

void cleanup(Record* records, size_t limit) {
