#include "loguru.hpp"

typedef struct record {
    int value;
} record_t;

// Global variables for locking and memory usage tracking
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_size_t memoryUsage = 0;

void manageMemoryAllocation(long *offsets, int *keys, record_t **records, 
                            size_t numOffsets, int minValue, int maxValue, size_t memoryLimit) {
    // Check if the total required memory exceeds the limit.
    const size_t requestedMemory = (numOffsets * sizeof(long)) +
                                    (numOffsets * sizeof(int)) + 
                                    (numOffsets * sizeof(record_t)); 

    if (requestedMemory > memoryLimit) {
        // Reduce the number of records by half until they fit within the limit.
        while ((numOffsets /= 2) > 0 && requestedMemory > memoryLimit) {}

        LOG_S(WARNING) << "Memory limit exceeded, reducing record count to " << numOffsets;
    }

    // Lock before allocating and initializing memory to ensure thread-safety.
    pthread_mutex_lock(&lock);

    *offsets = malloc(numOffsets * sizeof(long));
    if (*offsets == NULL) {
        LOG_F(ERROR, "Failed to allocate memory for offsets!");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(numOffsets * sizeof(int));
    if (*keys == NULL) {
        LOG_F(ERROR, "Failed to allocate memory for keys!");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(numOffsets * sizeof(record_t));
    if (*records == NULL) {
        LOG_F(ERROR, "Failed to allocate memory for records!");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    // Initialize the records with a random value within a specified range.
    for (size_t i = 0; i < numOffsets; ++i) {
        (*records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Update the memory usage tracker.
    atomic_fetch_add(&memoryUsage, requestedMemory);
    LOG_S(INFO) << "Total memory usage: " << atomic_load(&memoryUsage);

    pthread_mutex_unlock(&lock);
}
``` 

