#include <time.h>

typedef struct record {
    int* key;
    size_t sizeOfKey;
    bool active;
} Record;

Record** records;
size_t numRecords;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

bool checkUniqueKey(Record** records, size_t numRecords, int key) {
    for (size_t i = 0; i < numRecords; ++i) {
        if (*records[i]->key == key) return false;
    }
    return true;
}

int createRecord(Record** records, size_t* numRecords) {
    srand((unsigned int)time(NULL));

    while (true) {
        pthread_mutex_lock(&mutex);

        int key = getRandomInt(0, 100000);
        if (!checkUniqueKey(records, *numRecords, key)) continue;

        Record* newRecord = malloc(sizeof(Record));
        if (newRecord == NULL) {
            // Memory allocation failed, free all previously allocated records and return error status.
            for (size_t i = 0; i < *numRecords; ++i) {
                free(records[i]);
            }
            free(records);
            pthread_mutex_unlock(&mutex);
            return -1; // Return error status.
        }

        newRecord->key = malloc(sizeof(int));
        if (newRecord->key == NULL) {
            free(newRecord);
            pthread_mutex_unlock(&mutex);
            return -1; // Return error status.
        }

        *newRecord->key = key;
        newRecord->sizeOfKey = 0;
        newRecord->active = true;

        records[(*numRecords)++] = newRecord;

        pthread_mutex_unlock(&mutex);
        break; // Record successfully created, exit loop.
    }
    return 0; // Return success status.
}

void printDetails(Record** records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        printf("Record %zu: key = %d, sizeOfKey = %zu, active = %s\n", 
            i, *records[i]->key, records[i]->sizeOfKey, records[i]->active ? "true" : "false");
    }
}
