    int key;
    long offset;
} Record;

typedef struct HashTable {
    pthread_mutex_t lock;  // Protects the hash table during concurrent modifications.
    size_t capacity;
    size_t count;
    Record** records;
} HashTable;

HashTable* create_hashtable(size_t initialCapacity) {
    HashTable* h = malloc(sizeof(HashTable));
    if (h == NULL) return NULL;

    pthread_mutex_init(&h->lock, NULL);
    h->capacity = initialCapacity;
    h->count = 0;
    h->records = calloc(initialCapacity, sizeof(Record*));

    return h;
}

void destroy_hashtable(HashTable* h) {
    pthread_mutex_destroy(&h->lock);

    for (size_t i = 0; i < h->capacity; ++i) {
        if (h->records[i] != NULL) free(h->records[i]);
    }
    free(h->records);
    free(h);
}

int hash_function(size_t capacity, int key) {
    return abs(key) % capacity;
}

void insert(HashTable* h, int key) {
    pthread_mutex_lock(&h->lock);

    // Resize the hash table if necessary.
    if ((double)h->count / h->capacity > 0.75) {
        Record** oldRecords = h->records;
        size_t oldCapacity = h->capacity;

        h->capacity *= 2;
        h->records = calloc(h->capacity, sizeof(Record*));

        for (size_t i = 0; i < oldCapacity; ++i) {
            if (oldRecords[i] != NULL) {
                insert(h, oldRecords[i]->key);
                free(oldRecords[i]);
            }
        }

        free(oldRecords);
    }

    // Find a suitable place for the new record.
    int index = hash_function(h->capacity, key);
    while (h->records[index] != NULL) {
        if (h->records[index]->key == key) return;  // Ignore duplicates.
        index = (index + 1) % h->capacity;
    }

    Record* record = malloc(sizeof(Record));
    record->key = key;
    omp_set_num_threads(4);  // Use 4 threads for random number generation.
#pragma omp parallel
    {
        unsigned int seed = (unsigned) time(NULL) * omp_get_thread_num();
#pragma omp for
        for (size_t i = 0; i < h->capacity; ++i) {
            record->offset += rand_r(&seed);  // Generate a random offset value.
        }
    }

    h->records[index] = record;
    h->count++;

    pthread_mutex_unlock(&h->lock);
}
```
Please note that this code is just an example and will not run as it stands. It's meant to illustrate a general approach rather than be production-ready code. For example, the thread safety model used (pthread mutex) might not be suitable for performance-critical applications where lock contention can be a problem. You should also consider using more sophisticated data structures and algorithms, such as cuckoo hashing or hopscotch hashing, for better concurrency and to reduce memory fragmentation. Also, the logging mechanism is not implemented here. Please modify this code based on your specific requirements.
