void read_from_file(char* filename, int max_records) {
    FILE *fp = fopen(filename, "r");

    if (fp == NULL) {
        printf("Could not open the file!\n");
        return;
    }

    char buffer[256]; /* assuming each line will be no longer than 255 chars */
    int i = 0;

    while(fgets(buffer, sizeof(buffer), fp) != NULL && i < max_records) {
