#include <stdlib.h>
#include <string.h>

typedef struct data_element {
    double value;
    unsigned short key;
} DataElement;

// A simple hash function (Murmur3)
unsigned int murmurhash(unsigned int input, unsigned int seed) {
    const uint32_t c1 = 0xcc9e2d51;
    const uint32_t c2 = 0x1b873593;
    const uint32_t r1 = 15;
    const uint32_t r2 = 13;
    const uint32_t m = 5;
    const uint32_t n = 0xe6546b64;

    unsigned int k = input * c1;
    k = (k << r1) | (k >> (32 - r1));
    k *= c2;

    unsigned int hash = seed ^ m;
    hash ^= k;
    hash = (hash << r2) | (hash >> (32 - r2));
    hash = hash * m + n;

    return hash;
}

void create_data(double** doubleValues, unsigned short** keys, DataElement** records, size_t* size, size_t maxSize) {
    if(*size > maxSize || *size == 0) {
        fprintf(stderr, "Invalid size input.\n");
        exit(1);
    }

    // Allocate memory for arrays
    *doubleValues = malloc(sizeof(double) * (*size));
    *keys = malloc(sizeof(unsigned short) * (*size));
    *records = malloc(sizeof(DataElement) * (*size));

    // Handle allocation failures
    if(*doubleValues == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    for(unsigned int i = 0; i < (*size); ++i){
        // Compute a value from polynomial function based on the index
        (*doubleValues)[i] = (2 * i) * 2 - 4.5;

        // Assign keys using hash function applied to index
        (*keys)[i] = murmurhash(i, 0);

        // Initialize struct data_element records
        (*records)[i].value = (*doubleValues)[i];
        (*records)[i].key = (*keys)[i];
    }
}
```
