pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node* createNode(char *str, int priority) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;  // Handle allocation failure gracefully.

    newNode->str = strdup(str);  
    if (!newNode->str) {
        free(newNode);
        return NULL;  // Another allocation failure.
    }

    newNode->priority = priority;
    newNode->next = NULL;

    return newNode;
}

void insertSorted(char *str, int priority) {
    pthread_mutex_lock(&lock);  // Lock for thread safety.

    Node* node = createNode(str, priority);
    if (!node) {
        pthread_mutex_unlock(&lock);
        return;  // Failed to allocate memory.
    }

    int newSize = total_size + sizeof(Node) + strlen(str) + 1;
    while (newSize > max_total_size) {
        freeList();  // Clean up old nodes to prevent fragmentation.

        if (head == NULL) break;  // Handle the case where head was cleaned up by other thread.

        newSize = total_size + sizeof(Node) + strlen(str) + 1;
    }

    Node **ptr = &head;
    while (*ptr && (*ptr)->priority >= priority) 
        ptr = &((*ptr)->next);   // Find the insertion position.
    node->next = *ptr;
    *ptr = node;  // Insert new node at the found position.

    total_size += sizeof(Node) + strlen(str) + 1;  // Update total size.
    pthread_mutex_unlock(&lock);  // Unlock to allow other threads to access list.
}

Node* findByString(char *str) {
    Node *ptr = head;

    while (ptr && strcmp(ptr->str, str))  
        ptr = ptr->next;  // Search for the string in each node's string.

    return ptr;  // Return null if not found.
}

void freeList() {
    Node *node = head;
    while (node) {
        Node* temp = node;
        node = node->next;   // Move to next node before releasing memory of current one.

        free(temp->str);  // Release string and then node itself.
        free(temp);
    }

    head = NULL;  // Reset head.
}
