#include <time.h>
#include <string.h>

typedef struct {
    int value;
    double timestamp;
    char status;
} Record;

long total_memory = 0;
long current_memory = 0;
long freed_memory = 0;

void* safeMalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr != NULL) {
        total_memory += size;
        current_memory += size;
    } else {
        printf("Failed to allocate memory!\n");
    }
    return ptr;
}

void safeFree(void* ptr, size_t size) {
    free(ptr);
    current_memory -= size;
    freed_memory += size;
}

Record** manageMemory(size_t offsetsSize, size_t keysSize, size_t recordsSize, int minRand, int maxRand, char initialStatus) {
    long* offsets = (long*)safeMalloc(offsetsSize * sizeof(long));
    if (offsets == NULL) return NULL;

    int* keys = (int*)safeMalloc(keysSize * sizeof(int));
    if (keys == NULL) {
        safeFree(offsets, offsetsSize * sizeof(long));
        return NULL;
    }

    Record** records = (Record**)safeMalloc(recordsSize * sizeof(Record*));
    if (records == NULL) {
        safeFree(keys, keysSize * sizeof(int));
        safeFree(offsets, offsetsSize * sizeof(long));
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < recordsSize; ++i) {
        Record* record = (Record*)safeMalloc(sizeof(Record));
        if (record == NULL) {
            printf("Failed to allocate memory for a record!\n");
            break;
        } else {
            records[i] = record;
            keys[i] = rand() % (maxRand - minRand + 1) + minRand;
            record->value = keys[i];
            record->timestamp = ((double)clock()) / CLOCKS_PER_SEC * 1000.0;
            record->status = initialStatus;
        }
    }

    printf("Total memory allocated: %ld bytes\n", total_memory);
    printf("Currently used memory: %ld bytes\n", current_memory);
    printf("Freed memory: %ld bytes\n", freed_memory);

    return records;
}
``` 
This function does the requested task and also provides a simple logging mechanism for failed allocation attempts. Note that the logging mechanism is very basic and doesn't provide detailed information about where the failure occurred or any context related to why it happened. For robust error handling, consider using a more comprehensive logging framework such as log4c.
