```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAX_LINE_LENGTH 1024

typedef struct data_entry {
    double number;
    char *key;
    int integer;
} data_entry;

data_entry* read_config(const char* config_file, size_t *size) {
    FILE *file = fopen (config_file, "r");
    if (!file) return NULL;

    // count lines in file to allocate memory for data entries
    char line[MAX_LINE_LENGTH]; 
    *size = 0;
    while (fgets(line, sizeof(line), file)) { (*size)++; }

    rewind(file);  // go back to the start of the file

    data_entry* entries = malloc((*size) * sizeof(*entries));
    if (!entries) return NULL;

    size_t i = 0;
    while (fgets(line, sizeof(line), file)) {  // process each line in the file
        if (3 != sscanf(line, "%lf %m[^\n] %d", &entries[i].number, &entries[i].key, &entries[i].integer)) {
            for (; i > 0; i--) free(entries[i-1].key);  // handle error: deallocate memory and return NULL
            free(entries);
            fclose(file);
            return NULL;
        }
        i++;
    }

    fclose(file);
    return entries;
}
```

In this code, we read a configuration file that contains lines with three values separated by spaces: a double, a string and an integer. If any line does not contain these 3 elements, we handle the error, deallocate all previously allocated memory and return NULL to signal failure.

This is just a simplistic example to give you an idea about how to start implementing this kind of function. There are many things to consider in more complex scenarios like: concurrency, data validation, error handling etc. 

