    return rand() % (max - min + 1) + min;
}

void populateRecord(struct record* rec, const int* key) {
    for (size_t i = 0; i < 50; ++i) {
        // Generate random printable ASCII character
        rec->name[i] = randRange(' ', '~'); 
    }
    rec->name[50] = '\0'; // Ensure null termination

    // Initialize the int field with a random value within specified range
    rec->data = randRange(-100, 100);

    // Categorize the record (just for example purposes)
    rec->category = CATEGORY_A;

    rec->ptr = malloc(sizeof(int));
    if (!rec->ptr) {
        fprintf(stderr, "Memory allocation error!\n");
        exit(EXIT_FAILURE);
    }

    *rec->ptr = *key; // Initialize the pointer to point to its respective int key
}

void manageRecords(size_t num_records) {
    srand((unsigned)time(NULL)); // Seed for randomness reproducibility

    struct record* records = calloc(num_records, sizeof(struct record));
    if (!records) {
        fprintf(stderr, "Memory allocation error!\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        populateRecord(&records[i], &records[i].data); // Populate each record with random data
    }

    // ... Do something with the records ...

    // Free all allocated memory when done
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].ptr);
    }
    free(records);
}
```

This function `manageRecords` takes a single argument: the number of records to manage. It uses `calloc` to allocate memory for an array of `record` structures, which is then populated with random data using `populateRecord`. Each record's `ptr` field points to its respective `int` key. If either allocation fails, a message is printed to stderr and the program exits with failure status. After use, all allocated memory is freed using `free` to prevent leaks.
