// Error codes for directory validation failures
enum DirErrorCodes {
    E_ACCESS,  // No read access to the directory
    E_NEXIST   // Directory does not exist
};

int validateDir(char* dirPath) {
    struct stat st;

    if (stat(dirPath, &st) < 0) return E_NEXIST;
    else if ((st.st_mode & S_IFDIR) == 0) return E_NEXIST;  // Not a directory
    else if (access(dirPath, R_OK)) return E_ACCESS;       // No read access to the directory

    return 0;   // No error
}

int main() {
    char dirPath[256];
    printf("Enter a directory path: ");
    fgets(dirPath, sizeof(dirPath), stdin);

    int errCode = validateDir(dirPath);
    if (errCode) {
        switch (errCode) {
            case E_ACCESS: 
                printf("Permission denied!\n");
                break;
            case E_NEXIST: 
                printf("Directory does not exist.\n");
                break;
        }
    } else {
        printf("Valid directory path.\n");
    }

    return 0;
}
```
