} Record;

GHashTable* createSensors(int sensorCount) {
    GHashTable* hash = g_hash_table_new(g_str_hash, g_str_equal);
    if (hash == NULL) {
        printf("Failed to allocate memory for hash table\n");
        exit(-1);
    }

    srand((unsigned int)time(NULL));
    char sensorId[20];
    for (int i = 0; i < sensorCount; ++i) {
        sprintf(sensorId, "%d", rand() % 10000);

        // Initialize temperature readings and timestamps.
        Record* records = g_malloc(sizeof(Record) * 60 /* for an hour */);
        if (records == NULL) {
            printf("Failed to allocate memory for records\n");
            exit(-1);
        }

        time_t now = time(NULL);
        for (int j = 0; j < 60; ++j) {
            Record rec = {now + j * 60, (float)(rand() % 50)}; /* random temperature */
            records[j] = rec;
        }

        g_hash_table_insert(hash, sensorId, records);
    }

    return hash;
}
