['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

#define MAX_FILES 1000
#define MAX_PATHLEN 500
#define MIN_SIZE 1
#define MAX_SIZE 1024

typedef struct file_data {
    char filename[MAX_PATHLEN];
    unsigned long size;
} file_data;

file_data *readFilesFromFile(const char* inputFileName, int *successCount, int *failureCount) {
    FILE *inputFile = fopen(inputFileName, "r");
    if (inputFile == NULL) {
        printf("Failed to open file: %s\n", inputFileName);
        return NULL;
    }

    char buffer[MAX_PATHLEN];
    int lineCount = 0;

    while(fgets(buffer, MAX_PATHLEN, inputFile) != NULL && lineCount < MAX_FILES){
        strtok(buffer, "\n");  // Removing newline character

        FILE *file = fopen(buffer, "r");
        if (file == NULL) {
            (*failureCount)++;
            printf("Failed to open file: %s\n", buffer);
            continue;
        }

        struct stat st;
        stat(buffer, &st);
        unsigned long size = st.st_size;

        if (size >= MIN_SIZE && size <= MAX_SIZE) {
            (*successCount)++;
            lineCount++;
        } else {
            printf("File %s is out of size range\n", buffer);
            (*failureCount)++;
        }

        fclose(file); 
    }

    file_data *files = malloc(sizeof(file_data)*lineCount);
    if (files == NULL){
        printf("Failed to allocate memory for files\n");
        return NULL;
    }

    fseek(inputFile, 0, SEEK_SET);  // Reset file pointer
    lineCount = 0;

    while(fgets(buffer, MAX_PATHLEN, inputFile) != NULL && lineCount < MAX_FILES){
        strtok(buffer, "\n");  // Removing newline character

        FILE *file = fopen(buffer, "r");
        if (file == NULL) {
            (*failureCount)++;
            printf("Failed to open file: %s\n", buffer);
            continue;
        }

        struct stat st;
        stat(buffer, &st);
        unsigned long size = st.st_size;

        if (size >= MIN_SIZE && size <= MAX_SIZE) {
            strcpy(files[lineCount].filename, buffer); 
            files[lineCount].size = size;
            lineCount++;
        } else {
            printf("File %s is out of size range\n", buffer);
            (*failureCount)++;
        }

        fclose(file); 
    }

    fclose(inputFile);
    return files;
}
```
