```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Record structure to store timestamp, temperature, humidity and AQI readings
typedef struct {
    time_t timestamp;
    float temp;
    int humidity;
    uint32_t aqi;
} record;

// Hash table entry for sensor data
typedef struct node {
    char* key;
    record* value;
    struct node *next;
} Node;

Node** hashTable = NULL;
const int TABLE_SIZE = 1009; // Prime number for less collision
pthread_mutex_t lock[TABLE_SIZE];

void initHashTable() {
    hashTable = malloc(sizeof(Node*) * TABLE_SIZE);

    for (int i = 0; i < TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&lock[i], NULL);
    }
}

// Hash function
unsigned int hashCode(char* key) {
    unsigned long code = 5381;
    int c;

    while ((c = *key++))
        code = ((code << 5) + code) + c; // djb2 hash function

    return code % TABLE_SIZE;
}

void insert(char* key, record* data) {
    unsigned int index = hashCode(key);

    Node *node = malloc(sizeof(Node));
    node->key = key;
    node->value = data;
    pthread_mutex_lock(&lock[index]);
    node->next = hashTable[index];
    hashTable[index] = node;
    pthread_mutex_unlock(&lock[index]);
}
```
Please note that this is a simplification of the problem. A full solution would involve many other factors such as data persistence, handling multiple threads, rehashing when load factor exceeds certain threshold etc. You also need to properly handle the memory for each sensor (`malloc()` and `free()`) and you should consider using libraries like GLib or custom-made solutions to ensure thread safety, atomic operations, etc.
