// Define your memory pool here 
typedef struct MemoryPool {
    void *memory;
    size_t size;
    bool inUse;
} MemoryPool;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
MemoryPool* pools;
int poolCount = 0;

// Validate user input for memory allocation sizes
bool validateSize(size_t size) {
    if (size <= 0 || ((size & (size - 1)) != 0)) return false; // ensure it's a power of two
    else return true;
}

// Allocate and initialize arrays for timestamps, events descriptions, log entries
double* allocTimestampArray(int size) {
    if (!validateSize(size)) return NULL;
    double *timestamps = malloc(sizeof(double) * size);
    // Initialization of timestamps array
