    if (size <= 0) return NULL;
    log_entry *entries = malloc(sizeof(log_entry) * size);
    // Initialization of entries array
    for(int i = 0; i < size; ++i){
        entries[i].timestamp = 0.0;
        entries[i].event_description = NULL; 
        entries[i].level = LOG_LEVEL_INFO;
    }
    return entries;
}

// Memory pool management
void* getMemoryFromPool(size_t size){
    pthread_mutex_lock(&lock); // Locking to ensure thread safety
    for (int i = 0; i < poolCount; ++i) {
        if (!pools[i].inUse && pools[i].size >= size) {
            pools[i].inUse = true;
            pthread_mutex_unlock(&lock); // Unlocking after memory is obtained 
            return pools[i].memory;
        }
    }
    pthread_mutex_unlock(&lock); // Unlocking if no available pool found
    return NULL; // No available pool with enough size, need to allocate new one
}

void freeMemoryFromPool(void* memory){
    for (int i = 0; i < poolCount; ++i) {
        if (pools[i].memory == memory) {
            pthread_mutex_lock(&lock); // Locking to ensure thread safety
            pools[i].inUse = false;
            pthread_mutex_unlock(&lock); // Unlocking after memory is freed
            break;
        }
    }
}
```
