    INFO, WARNING, ERROR, FATAL
} log_level;

// Define a structure for log entries.
typedef struct {
    double timestamp;
    char *event_description;
    log_level level;
} log_entry;

#define HASH_TABLE_SIZE 10007 // Prime number for hash table size.

// Simple hash map implementation.
static int hash_table[HASH_TABLE_SIZE];
void insert_to_hashmap(int key, char *value) {
    int index = (key % HASH_TABLE_SIZE);
    while(hash_table[index] != NULL && hash_table[index] != -1) {
        // Collision resolution: linear probing.
        ++index;
        index %= HASH_TABLE_SIZE;
    }
    hash_table[index] = value;
}
char *get_from_hashmap(int key) {
    int index = (key % HASH_TABLE_SIZE);
    while(hash_table[index] != NULL) {
        if(hash_table[index] == key)
            return hash_table[index];
        ++index;
        index %= HASH_TABLE_SIZE;
    }
    return NULL; // Key not found.
}

void log_init() {
    int size;
    while (1) {
        printf("Enter the number of log entries: ");
        if(scanf("%d", &size) == 1 && size > 0) break;

        printf("Invalid input, please enter a positive integer.\n");
        while(getchar() != '\n'); // Clear input buffer.
    }

    log_entry *logs = malloc(sizeof(log_entry) * size);
    if (logs == NULL) {
        printf("Failed to allocate memory for logs.\n");
        return;
    }

    for(int i = 0; i < size; ++i) {
        logs[i].timestamp = get_time();

        int index;
