```rust
use std::collections::HashMap;
use std::time::Duration;
use reqwest::header::HeaderValue;
use url::Url;
use tokio::sync::Mutex;

pub struct HttpClient {
    client: Mutex<reqwest::Client>,
    base_url: Url,
    headers: HashMap<String, HeaderValue>,
}

impl HttpClient {
    pub async fn new(base_url: Url) -> Self {
        let client = reqwest::ClientBuilder::new()
            .danger_accept_invalid_certs(true)  // Disable certificate validation for secure connections.
            .timeout(Duration::from_secs(5))     // Set a timeout for both request execution and connection establishment.
            .redirect(reqwest::redirect::Policy::limited(3))    // Limit the maximum depth of HTTP redirects.
            .build()
            .unwrap();
        Self { client: Mutex::new(client), base_url, headers: HashMap::new() }
    }

    pub async fn get(&self, path: &str) -> Result<reqwest::Response, reqwest::Error> {
        let mut url = self.base_url.clone();
        url.set_path(path);
        let client = self.client.lock().await;
        client.get(url).headers(self.headers.clone()).send().await // Add more parameters as needed, such as query params, body etc.
    }
}
```
