['This problem requires knowledge of JSON parsing in C, dynamic memory allocation and deallocation, sorting algorithms, multi-threading and handling race conditions in C.

Here is a rough sketch of how one might tackle this task:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <jansson.h>  // Requires jansson library for JSON parsing
#include <pthread.h>  // POSIX threads for concurrency control

typedef struct {
    double value;
    char *content;
} Item;

int item_compare(const void *a, const void *b) {
    const Item *itemA = a;
    const Item *itemB = b;
    return (itemA->value > itemB->value) - (itemA->value < itemB->value);
}

void sort_items(Item *items, size_t count) {
    qsort(items, count, sizeof(Item), item_compare);
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Lock for concurrency control

void handle_incoming_data(char *json) {
    pthread_mutex_lock(&lock);  // Ensure only one thread can access the data at a time

    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        pthread_mutex_unlock(&lock);
        return;
    }

    if(!json_is_array(root)) {
        fprintf(stderr, "Error: root is not an array\n");
        json_decref(root);
        pthread_mutex_unlock(&lock);
        return;
    }

    size_t count = json_array_size(root);
    Item *items = calloc(count, sizeof(Item));  // Allocate memory for items

    for (size_t i = 0; i < count; i++) {
        json_t *data = json_array_get(root, i);

        if(!json_is_object(data)) {
            fprintf(stderr, "Error: array element is not an object\n");
            continue;
        }

        json_t *value = json_object_get(data, "value");
        json_t *content = json_object_get(data, "content");

        if(!json_is_real(value) || !json_is_string(content)) {
            fprintf(stderr, "Error: inconsistent data\n");
            continue;
        }

        items[i].value = json_real_value(value);
        items[i].content = strdup(json_string_value(content));  // Dynamically allocate memory for string content
    }

    sort_items(items, count);  // Sort the items

    stream_to_client(items, count);  // Stream sorted list to client

    for (size_t i = 0; i < count; i++) {
        free(items[i].content);  // Free dynamically allocated memory for string content
    }

    free(items);  // Free the array of items

    json_decref(root);  // Decrement reference count, destroy JSON object

    pthread_mutex_unlock(&lock);  // Allow other threads to access data
}
```
This code snippet uses jansson library for parsing JSON and pthread library for handling concurrency control. Error checking is performed to ensure the incoming JSON feed is valid and all necessary fields are present. Dynamically allocated memory for string content is handled efficiently with strdup() and free(). The entire array of items is sorted using qsort(), an efficient sorting function from the C standard library.
']

