    if (*records == NULL) {
        printf("Memory allocation failed for records.\n");
        free(*keys);
        free(*offsets);
        return;
    }

    srand((unsigned int) time(NULL)); // seeding the random number generator
    for (size_t i = 0; i < num_offsets; ++i) {
        (*records)[i] = malloc(sizeof(Record));

        if ((*records)[i] == NULL) {
            printf("Memory allocation failed for record %zu.\n", i);

            // Free previously allocated memory to avoid leaks.
            for (size_t j = 0; j < i; ++j) 
                free((*records)[j]);

            free(*keys);
            free(*offsets);
