} Record;

char *names[] = {"Alice", "Bob", "Charlie", "Dave", "Eve"};
int names_count = 5; // Size of the 'names' array.
pthread_mutex_t mutex;
FILE* logfile;
clock_t start, end;
double cpu_time_used;

void error_exit(char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int allocate_memory(size_t size, void **ptr) {
    if ((*ptr = malloc(size)) == NULL) return 0;
    memset(*ptr, 0, size);
    return 1;
}

char* generate_name(int index) {
    char* name = strdup(names[index % names_count]);
    if (name == NULL) error_exit("strdup");
    int id = rand(); // Generate a unique identifier.
    size_t len = snprintf(NULL, 0, "%s%d", name, id);
    char* buffer = malloc(len + 1);
    if (buffer == NULL) error_exit("malloc");
    snprintf(buffer, len + 1, "%s%d", name, id);
    free(name);
    return buffer;
}

void populate_record(Record *record, int key_range) {
    record->key = rand() % key_range;
    record->value = (double)rand() / RAND_MAX * 2.0 - 1.0; // Generate a random float between -1 and 1.
}

void log_record(Record *record, int index) {
    if (pthread_mutex_lock(&mutex) != 0) error_exit("pthread_mutex_lock");
    start = clock();
    fprintf(logfile, "Thread ID: %lu, Record #%d created. Offset: %ld, Key: %d, Name: %s, Value: %f\n", pthread_self(), index, record->offset, record->key, record->name, record->value);
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    if (pthread_mutex_unlock(&mutex) != 0) error_exit("pthread_mutex_unlock");
}

void *process_record(void *arg) {
    Record* record = (Record*) arg;
    int index = ((long)arg - (long)memory) / sizeof(Record); // Calculate the index of the record.
    record->name = generate_name(index);
    populate_record(record, 100); // key_range is 100 for example.
    log_record(record, index);
    return NULL;
}

void initialize(long *offsets, int *keys, Record* records, size_t size) {
    if (pthread_mutex_init(&mutex, NULL) != 0) error_exit("pthread_mutex_init");
    logfile = fopen("log.txt", "w");
    srand(time(NULL)); // Seed the random number generator.

    if (!allocate_memory(size * sizeof(*offsets), (void**)&offsets)) error_exit("malloc");
    if (!allocate_memory(size * sizeof(*keys), (void**)&keys)) error_exit("malloc"))
    if (!allocate_memory(size * sizeof(*records), (void**)&records)) error_exit("malloc");

    for (int i = 0; i < size; ++i) {
        records[i].offset = offsets[i] = rand(); // Generate a random offset.
        pthread_t thread;
        if (pthread_create(&thread, NULL, process_record, &records[i]) != 0) error_exit("pthread_create");
    }
}

void cleanup(long *offsets, int *keys, Record* records, size_t size) {
    for (int i = 0; i < size; ++i) free(records[i].name);
    fclose(logfile);
    pthread_mutex_destroy(&mutex);
    free(offsets);
    free(keys);
    free(records);
}
```
