class RecordManager {
private:
    std::unordered_map<std::string, Record*> records;
    std::vector<Record> buffer;
    std::recursive_mutex mtx;
public:
    ~RecordManager() {  // This is to prevent memory leakage
        for (auto& it : records) delete it.second;
    }

    void addOrUpdate(const char* name, double value) {
        std::lock_guard<std::recursive_mutex> lock(mtx);
        try {
            if (records.find(name) == records.end()) {
                Record* rec = new Record{name, value};  // Memory allocation
                records[name] = rec;
            } else {
                records[name]->value *= value;
            }
        } catch (const std::exception& e) {
            std::cerr << "Caught exception: " << e.what() << '\n';  // Error handling
        }
    }

    void processBatch(std::function<void(Record*)> func) {
        std::lock_guard<std::recursive_mutex> lock(mtx);
        for (auto& record : records) {
            try {
                func(record.second);  // Batch processing of records
            } catch (const std::exception& e) {
                std::cerr << "Caught exception: " << e.what() << '\n';  // Error handling
            }
        }
