// Define a structure that represents a range of numbers (inclusive or exclusive) and contains methods for generating random integers/floats
typedef struct {
    int min, max;
    int inclusive;
} NumberRange;

NumberRange* create_number_range(int min, int max, int inclusive) {
    NumberRange *r = malloc(sizeof(NumberRange));
    r->min = min;
    r->max = max;
    r->inclusive = inclusive;
    return r;
}

void destroy_number_range(NumberRange *r) {
    free(r);
}

int random_integer(const NumberRange* r) {
    int range = (r->max - r->min) + r->inclusive;
    return r->min + rand() % range;
}

double random_float(const NumberRange *r) {
    double fraction = ((double)rand()) / RAND_MAX;
    return r->min + (fraction * (r->max - r->min));
}

// Define a function to override printf for displaying the range settings
void print_range(const NumberRange* r, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);

    printf("Min: %d, Max: %d, Inclusive: %s", r->min, r->max, r->inclusive ? "Yes" : "No");

    vprintf(fmt, args);

    va_end(args);
}

