#include <stdatomic.h>

typedef struct {
    long timestamp;
    double precision_measurement;
    atomic_bool data_validity; // flag to indicate validity of the record
} data_item;

// each node in linked list
typedef struct Node{
    int key;
    size_t offset;
    data_item *data; 
    struct Node* next;
}Node;

// memory pool for allocating records
typedef struct {
    Node **nodes;
    int count;
    pthread_mutex_t lock; // for thread-safe access to the memory pool
} MemoryPool;

MemoryPool *initializeMemoryPool(size_t size){
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if(!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->count = 0;
    pool->nodes = calloc(size, sizeof(Node*)); // pre-allocate memory for 'size' nodes
    if(!pool->nodes) {
        free(pool);
        return NULL;
    }

    return pool;
}

// allocate a node from the memory pool
Node *allocateRecordFromPool(MemoryPool *pool){
    pthread_mutex_lock(&pool->lock);
    Node* node = malloc(sizeof(Node));
    if(!node) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; 
    }

    // allocate memory for data_item and initialize it
    node->data = calloc(1, sizeof(data_item));
    if(!node->data) {
        free(node);
        pthread_mutex_unlock(&pool->lock);
        return NULL; 
    }

    pool->nodes[pool->count] = node; // add the allocated record to the memory pool
    pool->count++;
    pthread_mutex_unlock(&pool->lock);

    return node;
}

// deallocate all nodes in the memory pool
void freeMemoryPool(MemoryPool *pool){
    pthread_mutex_lock(&pool->lock);
    for(int i = 0; i < pool->count; ++i){
        Node* node = pool->nodes[i];
        if (node) { // skip NULL pointers in case of error during allocation
            free(node->data);
            free(node);
        }
    }

    pthread_mutex_unlock(&pool->lock);
    free(pool->nodes);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
``` 
This is a simplified version, more complex scenarios would need to consider error handling for allocating memory, dealing with concurrency issues, and so forth. The exact implementation will depend on the specific requirements of your use case.
