    // Random number generation objects
    std::default_random_engine generator;
    std::uniform_int_distribution<long> timestamp_dist;
    std::uniform_real_distribution<double> measurement_dist;
public:
    DataManager(size_t size, long min_timestamp, long max_timestamp, double min_measurement, double max_measurement) 
        : timestamps(size), measurements(size), timestamp_dist(min_timestamp, max_timestamp), measurement_dist(min_measurement, max_measurement) { }

    void initialize() {
        for (size_t i = 0; i < timestamps.size(); ++i) {
            list.push_front({timestamps[i] = timestamp_dist(generator), measurements[i] = measurement_dist(generator), true});
        }
    }

    // Insert a string after the first occurrence of another string in the forward list
    void insertAfter(std::forward_list<std::string>& flist, const std::string& target, const std::string& toInsert) {
        auto pos = flist.begin();
        for (; pos != flist.end(); ++pos) {
            if (*pos == target) {
                break;
            }
        }

        // If the end was reached, insert at the end of the list
        if (pos == flist.end()) {
            flist.insert_after(flist.before_begin(), toInsert);
        } else {
            flist.insert_after(pos, toInsert);
        }
    }
};
```
