typedef struct {
    int value;
} Record;

typedef struct Node {
    _Atomic(struct Node*) next;
    Record record;
} Node;

typedef struct HashTable {
    size_t size;
    _Atomic(Node*) *nodes;
} HashTable;

HashTable* createHashTable(size_t size) {
    HashTable* table = malloc(sizeof(*table));
    if (!table) return NULL;

    table->size = size;
    table->nodes = calloc(size, sizeof(Node*));

    if (!table->nodes) {
        free(table);
        return NULL;
    }

    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* node = atomic_load(&table->nodes[i]);

        while (node != NULL) {
            Node* nextNode = atomic_load(&node->next);

            free(node);

            node = nextNode;
        }
    }

    free(table->nodes);
    free(table);
}

// Simple hash function (replace with a better one)
size_t getHash(int key, size_t tableSize) {
    return abs(key) % tableSize;
}

Node* createNode(Record record) {
    Node* node = malloc(sizeof(*node));

    if (!node) return NULL;

    atomic_init(&node->next, NULL);
    node->record = record;

    return node;
}

void insertIntoHashTable(int key, Record record, HashTable* table) {
    size_t hash = getHash(key, table->size);
    Node *newNode = createNode(record), 
        *currentHead = atomic_load(&table->nodes[hash]);

    while (!atomic_compare_exchange_weak(&table->nodes[hash], &currentHead, newNode)) {
        newNode->next = currentHead;

        currentHead = atomic_load(&table->nodes[hash]);
    }
}
```
This code implements a simple hash table with chaining for collision resolution. Note that it's not perfect - it doesn't handle load factor thresholds, resizing the table when necessary, and logging operations. It also uses a very simplistic hashing function which might lead to poor performance in some cases.

