#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>

typedef struct {
    double file_size;
    time_t creation_time;
    time_t last_modified_time;
} FileMetadata;

typedef struct {
    double value;
    int index;
    char* label;
    FileMetadata *file_metadata;
} DataEntry;

char *labels[] = {"Label1", "Label2", "Label3"};  // Your labels here.

DataEntry* initialize(int arraySize, const char* directory) {
    DIR *dir = opendir(directory);
    if (!dir) {
        perror("Can't open directory");
        return NULL;
    }

    DataEntry *data_entries = malloc(sizeof(DataEntry) * arraySize);
    if (data_entries == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        struct stat st;
        if (stat(path, &st) == 0) {
            int i = 0;
            for (; i < arraySize && data_entries[i].file_metadata != NULL; i++);

            FileMetadata *fm = malloc(sizeof(FileMetadata));
            if (fm == NULL) {
                fprintf(stderr, "Memory allocation error\n");
                continue;
            }

            fm->file_size = st.st_size;
            fm->creation_time = st.st_ctime;
            fm->last_modified_time = st.st_mtime;

            data_entries[i].file_metadata = fm;
        } else {
            perror("Can't read file");
        }
    }

    closedir(dir);

    srand((unsigned int) time(NULL));
    for (int i = 0; i < arraySize; i++) {
        data_entries[i].index = rand();
        data_entries[i].label = strdup(labels[i % 3]); // Use modulo to loop over labels.
    }

    return data_entries;
}
```
The function initialize will initialize the DataEntry array with random index and predefined labels, also it will store file metadata of files in specified directory. It uses an array of strings "labels" for populating label field. You need to replace these with your own values. Also note that this is a simple implementation, you need to add error handling, memory cleanup code for production grade code.
