    Record** records;
    int record_count;
    int alloc_counter;
} DB;

DB* create_db(int num_records, long min_timestamp, long max_timestamp, double prob) {
    srand((unsigned int)time(NULL));

    DB* db = (DB*)malloc(sizeof(DB));
    if (!db) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    db->record_count = num_records;
    db->alloc_counter = 0;

    db->records = (Record**)malloc(num_records * sizeof(Record*));
    if (!db->records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(db);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        db->records[i] = (Record*)malloc(sizeof(Record));

        if (!db->records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; j++) free(db->records[j]);
            free(db->records);
            free(db);
            return NULL;
        }

        db->records[i]->timestamp = min_timestamp + (rand() % (max_timestamp - min_timestamp + 1));
        if ((double) rand() / RAND_MAX <= prob / 100.0) {
            db->records[i]->node = (Node*)malloc(sizeof(Node));

            if (!db->records[i]->node) {
                fprintf(stderr, "Memory allocation failed\n");
                free(db->records[i]);
                for (int j = 0; j < i; j++) free(db->records[j]);
                free(db->records);
                free(db);
                return NULL;
            }

            db->alloc_counter++;
        } else {
            db->records[i]->node = NULL;
        }
    }

    return db;
}

void destroy_db(DB* db) {
    for (int i = 0; i < db->record_count; i++) {
        free(db->records[i]->node);
        free(db->records[i]);
    }

    free(db->records);
    free(db);
}

double calculate_average(DB* db) {
    double sum = 0;

    for (int i = 0; i < db->record_count; i++) {
        sum += db->records[i]->data;
    }

    return sum / db->record_count;
}
