['```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <errno.h>

typedef struct item {
    short count;
    bool status;
} Item;

typedef struct entry {
    char key;
    float value;
    Item* data;
    struct entry* next;
} Entry;

typedef struct node {
    pthread_mutex_t lock;
    int size;
    Entry** entries;
} Node;

Node* initDHT(int numNodes, int totalSize, int keyRange, float insertProb) {
    srand((unsigned int)time(NULL));

    Node* nodes = (Node*)malloc(numNodes * sizeof(Node));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numNodes; ++i) {
        nodes[i].entries = (Entry**)calloc(totalSize, sizeof(Entry*));
        if (!nodes[i].entries) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        pthread_mutex_init(&nodes[i].lock, NULL);
    }

    for (int i = 0; i < totalSize; ++i) {
        if ((float)rand() / RAND_MAX > insertProb) continue;

        char key = rand() % (keyRange + 1);
        float value = (float)rand() / RAND_MAX * 10.0f;

        int nodeIndex = i % numNodes;
        Node* node = &nodes[nodeIndex];

        pthread_mutex_lock(&node->lock);
        ++node->size;
        Entry* entry = (Entry*)malloc(sizeof(Entry));
        if (!entry) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        Item* item = (Item*)malloc(sizeof(Item));
        if (!item) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        entry->key = key;
        entry->value = value;
        entry->data = item;
        node->entries[i % totalSize] = entry;
        pthread_mutex_unlock(&node->lock);
    }

    return nodes;
}

void freeDHT(Node* nodes, int numNodes) {
    for (int i = 0; i < numNodes; ++i) {
        pthread_mutex_destroy(&nodes[i].lock);

        for (int j = 0; j < totalSize; ++j) {
            Entry* entry = nodes[i].entries[j];
            if (entry) {
                free(entry->data);
                free(entry);
            }
        }

        free(nodes[i].entries);
    }

    free(nodes);
}
``` 
This is a basic implementation of the problem. Memory allocation and deallocation are handled efficiently, but thread synchronization could be further optimized by using conditional variables to avoid busy waiting. Error handling is minimal - in real-world scenarios it would be important to handle memory allocation failures more gracefully and provide meaningful error messages. Also, node load balancing and recovery mechanisms were not implemented due to the complexity of these features which would greatly increase code length.
