    node->records = realloc(node->records, sizeof(Record*)*(node->size+1));
    if (node->records == NULL) {
        printf("Memory allocation error!");
        return;
    }
    node->records[node->size] = record;
    node->size++;
}

double calculateAverage(Record *records, size_t n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += records[i].value;
    }
    return sum / n;
}

void freeMemory(Record *records, size_t r_size, Node **nodes, size_t n_size) {
    for (int i = 0; i < r_size; i++) {
        if (records[i].node != NULL) {
            freeNode((Node*)records[i].node);
        }
        free(records + i);
    }
    free(records);

    for (int i = 0; i < n_size; i++) {
        if (nodes[i] != NULL) {
            freeNode(nodes[i]);
        }
    }
    free(nodes);
}
```
