#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "external_log_library.h" // assume we have a library for logging

typedef struct {
    long offset;
    int key;
    char* name;
} Record;

void *allocateMemory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation failure here
        exit(1);
    }
    return ptr;
}

Record* createRecord(long offset, int key, char* name) {
    Record *record = allocateMemory(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->name = strdup(name); // Deep copy to prevent modification of the original string

    return record;
}

void populateRecords(Record* records, int num_records, char** names, int name_list_size) {
    srand(time(NULL)); // Seed for random number generator

    for (int i = 0; i < num_records; ++i) {
        int index = rand() % name_list_size;
        records[i] = createRecord(i, rand(), names[index]);

        // Log the record initialization
        log_message("Initializing record %d with offset:%ld key:%d name:%s", i, records[i].offset, records[i].key, records[i].name);
    }
}

void cleanup(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].name); // Free memory of each name allocated in createRecord function
    }

    free(records); // Free memory of the records array itself
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Global lock for multithreading
void *recordProcessingThread(void *arg) {
    Record* record = (Record*) arg;

    pthread_mutex_lock(&mutex); // Lock before accessing shared resource to ensure thread-safety
    log_message("Processing record with offset:%ld key:%d name:%s", record->offset, record->key, record->name);
    pthread_mutex_unlock(&mutex); // Unlock after accessing shared resource to allow other threads to access it

    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        printf("Usage: %s num_records name_list_size\n", argv[0]);
        exit(1);
    }

    int num_records = atoi(argv[1]);
    int name_list_size = atoi(argv[2]);
    if (num_records <= 0 || name_list_size <= 0) {
        printf("Both num_records and name_list_size should be positive integers\n");
        exit(1);
    }

    // Assume we have a predefined list of names
    char* names[] = {"Alice", "Bob", "Charlie", "David"}; 

    Record *records = allocateMemory(sizeof(Record) * num_records);
    populateRecords(records, num_records, names, name_list_size);

    pthread_t threads[num_records];
    for (int i = 0; i < num_records; ++i) {
        if (pthread_create(&threads[i], NULL, recordProcessingThread, &records[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL); // Wait for all threads to complete
    }

    cleanup(records, num_records);
}
