['Here is a simple representation of how you could solve this problem using C language:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    long offset;
    int key;
    char* name;
} Record;

// Pre-defined names array
char *names[] = {"Alice", "Bob", "Charlie"};

pthread_mutex_t mutex;
int totalMemory = 0;
int maxMemory = 0;

void exportRecords(Record* records, int size, const char* filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return;
    }

    for (int i = 0; i < size; i++) {
        fprintf(file, "%ld,%d,%s\n", records[i].offset, records[i].key, records[i].name);
    }

    fclose(file);
}

void* processRecords(int size, int keyRange) {
    // Mutex locking for thread-safe access to shared resources
    pthread_mutex_lock(&mutex);

    Record *records = malloc(sizeof(Record) * size);

    if (records == NULL) {
        printf("Failed to allocate memory\n");
        return;
    }

    // Memory allocation and initialization
    for (int i = 0; i < size; i++) {
        records[i].offset = i * sizeof(Record);

        // Random key assignment
        srand(time(NULL));
        records[i].key = rand() % keyRange;

        // Initialize name field with pre-defined names
        int index = rand() % (sizeof(names) / sizeof(char*));
        records[i].name = malloc(strlen(names[index]) + 1);
        strcpy(records[i].name, names[index]);
    }

    totalMemory += size * sizeof(Record);
    if (totalMemory > maxMemory) {
        maxMemory = totalMemory;
    }

    // Error handling and cleanup
    for (int i = 0; i < size; i++) {
        free(records[i].name);
    }
    free(records);

    pthread_mutex_unlock(&mutex);
}

void printMemoryReport() {
    printf("Total memory used: %d\n", totalMemory);
    printf("Peak memory usage: %d\n", maxMemory);
}
```

