typedef struct {
    int value;
} record_t;

long process_data(int record_count, int min_value, int max_value, long max_sum) {
    if (record_count <= 0) return -1;

    // allocate memory for arrays
    long *offsets = malloc(sizeof(long) * record_count);
    if (!offsets) return -1; 

    int *keys = malloc(sizeof(int) * record_count);
    if (!keys) {
        free(offsets);
        return -1;
    }

    record_t *records = malloc(sizeof(record_t) * record_count);
    if (!records) {
        free(offsets);
        free(keys);
        return -1;
    }

    // initialize keys with sequential integers starting from 1
    for (int i = 0; i < record_count; ++i) {
        keys[i] = i + 1;
    }

    srand(time(NULL)); // seed the random number generator

    long sum = 0;
    for (int i = 0; i < record_count; ++i) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = value;
        sum += value;  // update the sum of values

        if (sum > max_sum) { // check for sum constraint violation
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // cleanup
    free(offsets);
    free(keys);
    free(records);

    return sum; 
}
```
