  constructor() {
    this.tests = [];
  }

  addTest(testSuite) {
    this.tests.push(testSuite);
  }

  runAllTestsInParallel() {
    // Parallel execution using Promise.all and async/await to handle concurrency, error handling with try/catch blocks for test failures
    const promises = this.tests.map(async (test) => {
      mockedLibrary.reset();
      test.start();
      let result;
      try {
        await jest.require(test.moduleName);
        result = true;
      } catch (e) {
        console.error(`Test failed with error: ${e}`);
        result = false;
      } finally {
        test.end(result);
        this._logDetails(test);
      }
    });
    return Promise.all(promises);
  }

  _logDetails(test) {
    console.log({
      module: test.moduleName,
      startTime: test._startTime,
      endTime: test._endTime,
      pass: test.testPassed ? 'PASS' : 'FAIL',
    });
  }
}
