// assuming there's a logger library like liblog4cpp
#include "logger.h" 

typedef struct {
    long offset;
    int key;
    char* name;
} Record;

char *names[] = {"Alice", "Bob", "Charlie", "David", "Eve", NULL}; // list of predefined names, NULL terminated
int hash_function(const char *name) {
    int hash = 5381;
    for (unsigned int i = 0; name[i] != '\0'; ++i)
        hash = ((hash << 5) + hash) + name[i]; /* hash * 33 + c */
    return hash % sizeof(names); // use modulo to make sure the index is within array bounds
}

void init_records(Record **records, int n_records, long *offsets, int *keys) {
    *records = calloc(n_records, sizeof(Record));
    assert(*records != NULL); // if memory allocation failed, terminate the program

    for (int i = 0; i < n_records; ++i) {
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];
        int hash = abs(hash_function(names[i % sizeof(names)])); // calculate the hash value, and take absolute to avoid negative index
        (*records)[i].name = strdup(names[hash]);  // copy string from predefined list
    }
}

void set_keys(Record *records, int n_records, int min, int max) {
    for (int i = 0; i < n_records; ++i) {
        records[i].key = rand() % (max - min + 1) + min; // set key to a random value between min and max
    }
}

void memory_monitoring(struct rusage *usage, long threshold) {
    getrusage(RUSAGE_SELF, usage);
    if (usage->ru_maxrss > threshold) { // high memory usage
        logger.warn("High memory usage detected.");
        // you can add custom actions here, for example log a warning or trigger an early exit
    }
}

