["Here's a high-level example code for managing dynamic lists in C. It should be noted that this is a complex task which requires detailed consideration and might not work perfectly as some tradeoffs cannot be avoided. Here, we assume the usage of pthread library for threads handling, atomic operations and locks (which might be replaced with lock-free data structures based on requirements). For simplicity, this code does not include all error checking, logging, or memory management tasks mentioned in your list.

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdatomic.h>

typedef struct Record {
    int value;
    long* offset_ptr;
} Record;

typedef struct MemoryPool {
    Record* records;
    size_t max_size;
    atomic_int count;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool create_pool(size_t max_size) {
    MemoryPool pool = { .records = malloc(max_size * sizeof(Record)), 
                        .max_size = max_size, 
                        .count = 0 };
    pthread_mutex_init(&pool.mutex, NULL);
    return pool;
}

void* allocate(MemoryPool* pool, size_t size) {
    if (pool->count + size > pool->max_size * 0.75) return NULL; // Ensure no fragmentation

    pthread_mutex_lock(&pool->mutex);

    Record* newRecord = &pool->records[atomic_fetch_add(&pool->count, size)];

    for (size_t i = 0; i < size; ++i) {
        newRecord[i].value = rand(); // Fill with random values
        newRecord[i].offset_ptr = NULL;
    }

    pthread_mutex_unlock(&pool->mutex);
    return (void*)newRecord;
}

void deallocate(MemoryPool* pool, void* record) {
    if (!record) return; // Ignore null pointers

    Record* r = (Record*)record;

    pthread_mutex_lock(&pool->mutex);

    for (size_t i = 0; i < pool->count; ++i) {
        if (&r[i] == &pool->records[i]) { // Mark as deallocated
            r[i].value = 0;
            r[i].offset_ptr = NULL;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
}
``` 

This is a very simplified version of what you asked for. It does not cover all the aspects you mentioned (such as garbage collection, pointer offsets, zero or negative record counts handling etc.), and many considerations are left out intentionally to avoid cluttering this example. Please adjust it according to your needs.
