Please note that this is a simplified code snippet for educational purposes only and does not cover all the requirements mentioned in detail or in production quality. In an actual application, you would need to implement error handling, thread safety, and memory management properly. Also, the hashing function used here is very basic and may lead to hash collisions if the number of names is too large compared to the size of the record array.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    _Atomic(long) offset;
    int key;
    char* name;
} record;

record* records = NULL;
unsigned long num_records = 0;
pthread_mutex_t lock;
char** names = NULL;  // Assume this is dynamically loaded and managed

int hash(long offset, int mod) {
    return offset % mod;
}

void* populateRecords() {
    pthread_mutex_lock(&lock);

    srand((unsigned int)time(NULL));  // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = atomic_load_explicit(&records[i-1].offset, memory_order_relaxed) + 1;  // Atomic increment of offset
        records[i].key = rand_r(NULL);  // Generate a random key

        int index = hash(atomic_load_explicit(&records[i].offset, memory_order_relaxed), num_records);  // Distribute names evenly across the array
        records[i].name = names[index];  // Assign a name to each record
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    int input;
    printf("Enter number of records: ");
    scanf("%d", &input);

    if (input <= 0) {  // Check for valid input
        fprintf(stderr, "Error: Invalid input. Falling back to default value.\n");
        num_records = 10;  // Default value
    } else {
        num_records = input;
    }

    records = malloc(sizeof(record) * num_records);  // Allocate memory for the array of records
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        return -1;  // Return an error code
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, &populateRecords, NULL) != 0) {
        fprintf(stderr, "Error: Failed to create thread.\n");
        free(records);  // Clean up before returning
        return -1;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Error: Failed to join thread.\n");
        free(records);
        return -1;
    }

    // Rest of the code here...

    free(records);  // Don't forget to free allocated memory after use

    return 0;
}
```
