std::vector<record> records;  // Vector of structs
std::vector<std::string> namesList = {"Alice", "Bob", "Charlie" /* ... */ };
const int DEFAULT_SIZE = 1000;
int currentSize = DEFAULT_SIZE;

void initialize(long offset[], int key[], std::string name[], int size) {
    if (size <= 0 || size > availableSystemResources()) {
        throw std::invalid_argument("Invalid input. Size must be positive and less than system resources.");
    }

    // Dynamically allocate memory for arrays
    offset = new long[size];
    key = new int[size];
    name = new std::string[size];
