void populateRecordArray(int userSize) {
    if (userSize <= 0) {
        BOOST_LOG_TRIVIAL(error) << "Invalid size. Defaulting to 1000.";
        userSize = DEFAULT_SIZE;
    } else {
        currentSize = userSize; // Update the global current size
    }

    // Resize vector dynamically
    records.resize(userSize);

    std::random_device rd; 
    std::mt19937 gen(rd());
