    Node tail = null;

    public void addNode(int i, Record r) {
        Node new_node = new Node(i, r);

        if (head == null && tail == null) {
            head = new_node;
            tail = new_node;
        } else {
            tail.next = new_node;
            tail = new_node;
        }
    }

    public void executeCommand(String command, String dir) throws IOException, InterruptedException {
        File[] files = Paths.get(dir).toFile().listFiles();

        for (File file : files) {
            if (!file.isDirectory()) {
                Files.delete(Paths.get(file.getAbsolutePath())); // Deletes all files in directory
            }
        }

        ProcessBuilder builder = new ProcessBuilder("/bin/bash", "-c", command);
        Process process = builder.start();

        BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;

        while ((line = outputReader.readLine()) != null) {
            logger.info("Command Output: " + line); // Logs command output
        }

        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        while ((line = errorReader.readLine()) != null) {
            logger.error("Command Error: " + line); // Logs command errors
        }
    }
}
