```c
#include <stdlib.h>

typedef struct Record {
    int value;
} Record;

typedef struct MemoryManager {
    Record* records;
    size_t budget;
    size_t count;
    size_t allocated;
} MemoryManager;

MemoryManager* createMemoryManager(size_t initialBudget) {
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    if (manager == NULL) return NULL;

    manager->records = malloc(initialBudget * sizeof(Record));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    manager->budget = initialBudget;
    manager->count = 0;
    manager->allocated = initialBudget;

    return manager;
}

void destroyMemoryManager(MemoryManager* manager) {
    free(manager->records);
    free(manager);
}

int addRecord(MemoryManager* manager, int value) {
    if (manager->count >= manager->allocated) {
        Record* newRecords = realloc(manager->records, 2 * manager->allocated * sizeof(Record));

        if (newRecords == NULL) return -1;

        manager->records = newRecords;
        manager->allocated *= 2;
    }

    manager->records[manager->count].value = value;
    manager->count++;

    return 0;
}

int updateRecord(MemoryManager* manager, size_t index, int newValue) {
    if (index >= manager->count) return -1;

    manager->records[index].value = newValue;
    return 0;
}

int removeRecord(MemoryManager* manager, size_t index) {
    if (index >= manager->count) return -1;

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->records[i] = manager->records[i + 1];
    }

    if ((manager->allocated >= 4 * manager->count) && (manager->allocated / 2 >= manager->budget)) {
        Record* newRecords = realloc(manager->records, manager->allocated / 2 * sizeof(Record));

        if (newRecords == NULL) return -1;

        manager->records = newRecords;
        manager->allocated /= 2;
    }

    manager->count--;
    return 0;
}
```
