#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <string.h>

EVP_CIPHER_CTX* initializeCipher(const char* password) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32]; // AES-256 key size
    unsigned char iv[16];  // IV size

    /* Generate the key and IV */
    if (EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, strlen(password), 1, key, iv) == 0) {
        return NULL; // Failed to generate the key and IV
    }

    /* Create and initialize the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) {
        return NULL; // Failed to create the context
    }

    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        return NULL; // Failed to initialize the encryption operation
    }

    /* Set the padding */
    EVP_CIPHER_CTX_set_padding(ctx, 1);

    return ctx;
}
```

This function takes a password as input and uses it along with SHA256 hashing to generate an AES-256 key. It then creates an EVP_CIPHER_CTX object for encryption using the generated key and IV, enabling AES-256-CBC cipher mode.

