// Assuming 1024 as the maximum cache size for simplicity
const int MAX_CACHE_SIZE = 1024;
int hitCount = 0, missCount = 0;
sem_t sem;
std::unordered_map<std::string, std::pair<double, bool>> cache; // Cache map, stores key-value pairs. 
// Value is a pair where first element is the mean value and second is hit/miss status (true for hit)
std::queue<std::string> lruQueue; // Queue to maintain LRU order

void readConfig(const std::string& filename, const std::string& delimiter = "\t") {
    if (!sem_wait(&sem)) { 
        std::ifstream file(filename);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                size_t pos = 0;
                int fieldCount = 5; // Assuming we need to take first 5 fields for mean calculation
                double sum = 0.0, value;
                bool allFieldsPresent = true;
                while (fieldCount > 0 && (pos = line.find(delimiter)) != std::string::npos) {
                    try {
                        value = std::stod(line.substr(0, pos));
                        sum += value;
                        --fieldCount;
                    } catch (std::invalid_argument& e) {
                        allFieldsPresent = false;
                        break;
                    }
                    line.erase(0, pos + delimiter.length());
                }
                if (!allFieldsPresent || fieldCount > 1) continue; // Skip lines with missing fields
                try {
                    value = std::stod(line); // Checking last field
                    sum += value;
                } catch (std::invalid_argument& e) {
                    allFieldsPresent = false;
                }

                if (!allFieldsPresent) continue; // Skip lines with non-numeric fields

                double meanValue = sum / 5.0; // Calculating mean
                std::cout << line << "\t" << meanValue << std::endl;

                sem_post(&sem); // Release the semaphore after processing
            }
            file.close();
        } else {
            std::cerr << "Unable to open file";
        }
    }
}

int main() {
    if (sem_init(&sem, 0, 1) == -1) { // Initialize the semaphore with initial value of 1
        perror("Semaphore Initialization Failed");
        return EXIT_FAILURE;
    }

    readConfig("config.txt");

    std::cout << "Hit/Miss Ratio: " << static_cast<double>(hitCount) / (hitCount + missCount) * 100  << "%\n";

    if (sem_destroy(&sem)) { // Clean up the semaphore
        perror("Semaphore Destruction Failed");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```
