use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct DirectoryName {
    name: String,
}

fn create_and_manage_directory_structure() -> Result<(), std::io::Error> {
    // Initialize logger
    TermLogger::init(LevelFilter::Info, ConfigBuilder::new().build())
        .unwrap();
    log::info("Initializing directory creation");

    // Read from file to get directory names (you would need csv crate for this)
    let mut rdr = File::open("directory_names.csv")?;

    loop {
        match rdr.lines().next() {
            Some(Ok(line)) => {
                // Process each line
                let name: DirectoryName = serde_json::from_str(&line)?;

                // Check if the directory exists, create it otherwise
                let dir_path = Path::new("directory/").join(name.name);
                match dir_path.exists() {
                    true => log::info("Directory {} already exists", name.name),
                    false => {
                        create_dir_all(&dir_path)?;
                        log::info("Created directory {}", name.name);
                    }
                }
            },
            Some(Err(_)) | None => break,
        }
    }

    // Set environment variable
    match env::var("DIRECTORY_PATH") {
        Ok(_) => log::info("Environment variable already exists"),
        Err(_) => {
            env::set_var("DIRECTORY_PATH", &dir_path.to_string_lossy().into_owned());
            log::info("Set environment variable to {}", dir_path);
        }
    };

    Ok(())
}
