void init_data(dataset *d, int size) {
    d->size = size;

    // Allocate memory for offsets and keys arrays
    d->offsets = malloc(sizeof(long) * size);
    if (d->offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    d->keys = malloc(sizeof(int) * size);
    if (d->keys == NULL) {
        free(d->offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records array and initialize fields
    d->records = malloc(sizeof(record) * size);
    if (d->records == NULL) {
        free(d->offsets);
        free(d->keys);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    int i;
    for (i = 0; i < size; i++) {
        d->offsets[i] = rand(); // Random offset generation

        int key;
        do {
            key = rand() % INT_MAX; 
        } while (!validate_key(d, key)); // Check for conflicts with existing keys
        d->keys[i] = key;

        record *r = &d->records[i];
        r->offset = d->offsets[i];
        r->key = d->keys[i];

        // Name assignment based on index, ensure within bounds
        int name_index = i % num_names; 
        r->name = names[name_index];
    }
}

void read_data(dataset *d, FILE* fp) {
    pthread_mutex_lock(&lock); // Thread safety

    long offset;
    int key;
    char name[256];
    while (fscanf(fp, "%ld %d %s", &offset, &key, name) == 3) {
        if (!validate_key(d, key)) { // Check for conflicts with existing keys
            log(1, "Duplicate key detected");
            continue;
        }

        d->size++;
        d->offsets = realloc(d->offsets, sizeof(long) * d->size);
        d->keys = realloc(d->keys, sizeof(int) * d->size);
        d->records = realloc(d->records, sizeof(record) * d->size);

        d->offsets[d->size - 1] = offset;
        d->keys[d->size - 1] = key;

        record *r = &d->records[d->size - 1];
        r->offset = offset;
        r->key = key;
        r->name = strdup(name); // Duplicate the string for memory safety
    }

    pthread_mutex_unlock(&lock); // Unlock mutex after operation
}

void free_data(dataset *d) {
    int i;
    for (i = 0; i < d->size; i++) {
        free(d->records[i].name);

        // Free the memory allocated for metadata field here. 
