```c
#include <stdlib.h>
#include <string.h>
#include <glib.h>
#include <pthread.h>

typedef struct item {
    int id;
    char name[50];
    size_t length;
} Item;

static GList *floatValues = NULL;
static GSList *timestampValues = NULL;
static GQueue *itemPointers = NULL;

pthread_mutex_t mutexFloat = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutexTimestamp = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutexItems = PTHREAD_MUTEX_INITIALIZER;

void initLists() {
    floatValues = g_list_append(floatValues, GFLOAT_TO_BE(0.0)); // Start with a dummy element to simplify code
    timestampValues = g_slist_prepend(timestampValues, GDOUBLE_TO_BE(0.0)); // Start with a dummy element to simplify code
    itemPointers = g_queue_new(); // The queue will be empty at the beginning
}

void addFloatValue(float value) {
    pthread_mutex_lock(&mutexFloat);
    floatValues = g_list_prepend(floatValues, GFLOAT_TO_BE(value)); // Add new values to the front of list
    pthread_mutex_unlock(&mutexFloat);
}

void addTimestampValue(double timestamp) {
    pthread_mutex_lock(&mutexTimestamp);
    timestampValues = g_slist_prepend(timestampValues, GDOUBLE_TO_BE(timestamp)); // Add new values to the front of list
    pthread_mutex_unlock(&mutexTimestamp);
}

void addItemPointer(const char *baseName, int index) {
    Item *item = malloc(sizeof(Item));
    if (item == NULL) return; // Handle allocation failure gracefully

    item->id = index;
    snprintf(item->name, 50, "%s%d", baseName, index);
    item->length = strlen(item->name);

    pthread_mutex_lock(&mutexItems);
    g_queue_push_tail(itemPointers, item); // Add new items to the back of queue
    pthread_mutex_unlock(&mutexItems);
}

void cleanupLists() {
    g_list_free_full(floatValues, free);
    g_slist_free_full(timestampValues, free);

    while (!g_queue_is_empty(itemPointers)) {
        Item *item = (Item *)g_queue_pop_head(itemPointers);
        free(item); // Free individual items to prevent memory leaks
    }
    g_queue_free(itemPointers);
}
``` 

