    Record *records = malloc(sizeof(Record) * recordCount);
    if (records == NULL) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    for (int i = 0; i < recordCount; i++) {
        records[i].name = malloc(strlen(names[i % 5]) + /* Add suffix length */ + 1); // Example: 2 digit suffix.
        if (records[i].name == NULL) {
            printf("Memory allocation failed for record #%d.\n", i);
            while(--i >= 0){ // Cleanup already allocated records.
                free(records[i].name);
            }
            free(offsets);
            free(keys);
            return;
        }

        strcpy(records[i].name, names[i % 5]);
        sprintf(records[i].name + strlen(names[i % 5]), "%02d", i); // Add unique suffix.

        int key;
        do {
            key = rand() % maxLimit + 1; // Assumes keys within 1-maxLimit range. Adjust as per your requirement.
        } while (hashTable[key] == 1);

        hashTable[key] = 1;

        records[i].offset = 0; // Initialize offset and value to 0 for simplicity. 
        records[i].value = 0; // You can initialize these fields with actual values in production code.
        records[i].key = key;
    }

    printf("Records initialized successfully.\n");

    /* Logging and cleanup */
    for (int i = 0; i < recordCount; i++) {
        printf("Record #%d: Offset=%ld, Key=%d, Name=%s, Value=%.2f\n", 
               i, records[i].offset, records[i].key, records[i].name, records[i].value);

        free(records[i].name); // Free memory for name.
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manageRecords(5, 10);
    return 0;
}
