    records = realloc(records, sizeof(record_t)*newSize);
}

void createRecord(int keyIndex, int offset) {
    pthread_mutex_lock(&lock); // lock for thread safety

    if (keyIndex >= numNames || recordCount >= 1000) {
        fprintf(logFile, "Error: Invalid name index or maximum records reached.\n");
        return;
    } 

    resizeRecords(recordCount + 1); // resize to accommodate new record

    record_t* rec = &records[recordCount++];
    rec->offset = offset;
    rec->key = keyIndex;
    rec->name = malloc(strlen(names[keyIndex]) + 1);
    strcpy(rec->name, names[keyIndex]); 

    fprintf(logFile, "Created record: %ld, %d, %s\n", rec->offset, rec->key, rec->name);

    pthread_mutex_unlock(&lock); // unlock after modification
}
