```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

// A custom memory pool to reduce frequent allocations and deallocations
Record* record_pool = NULL;
size_t record_pool_size = 0;
size_t record_pool_next = 0;

pthread_mutex_t mutex; // For thread safety

void* allocate_record() {
    if (record_pool == NULL || record_pool_next >= record_pool_size) {
        size_t old_size = record_pool_size;
        record_pool_size += 1024; // Increase by 1024 records at a time
        Record* new_pool = realloc(record_pool, record_pool_size * sizeof(Record));

        if (new_pool == NULL) {
            return NULL;
        }

        record_pool = new_pool;

        // Initialize the newly allocated records
        for (size_t i = old_size; i < record_pool_size; ++i) {
            srand(time(NULL)); // Seed random number generator
            record_pool[i].value = rand() % 1000 + 1; // Random value between 1 and 1000
        }
    }

    return &record_pool[record_pool_next++];
}

void free_record(Record* record) {
    --record_pool_size;

    if (record_pool_size == 0) {
        free(record_pool);
        record_pool = NULL;
    } else {
        // Swap the freed record with the last one and decrement size
        *record = record_pool[record_pool_size];
        --record_pool_next;
    }
}

void* allocate_resources(long* offsets, int num_offsets, int* keys, int num_keys, Record** records) {
    pthread_mutex_lock(&mutex); // Lock for thread safety

    *offsets = malloc(num_offsets * sizeof(long));
    if (*offsets == NULL) goto error;

    *keys = calloc(num_keys, sizeof(int));
    if (*keys == NULL) goto error;

    *records = malloc(num_keys * sizeof(Record*));
    if (*records == NULL) goto error;

    for (int i = 0; i < num_keys; ++i) {
        Record* record = allocate_record();

        if (record == NULL) goto error;

        (*records)[i] = record;
    }

    pthread_mutex_unlock(&mutex); // Unlock after successful allocation
    return NULL;

error:
    // Cleanup in case of errors
    free(*offsets);
    *offsets = NULL;

    free(*keys);
    *keys = NULL;

    for (int i = 0; i < num_keys; ++i) {
        if ((*records)[i] != NULL) {
            free_record((*records)[i]);
            (*records)[i] = NULL;
        }
    }

    free(*records);
    *records = NULL;

    pthread_mutex_unlock(&mutex); // Unlock after cleanup
    return "Memory allocation failed";
}
``` 

