    long* offsets = malloc(size * sizeof(long));
    if (offsets == NULL) return NULL; // Out of memory error

    int* keys = calloc(size, sizeof(int));
    if (keys == NULL) {
        free(offsets);
        return NULL; // Out of memory error
    }

    record** records = malloc(size * sizeof(record*));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Out of memory error
    }

    for (int i = 0; i < size; ++i) {
        records[i] = malloc(sizeof(record));

        if (records[i] == NULL) {
            // Free all previously allocated records and their contents 
            for (--i; i >= 0; --i) {
                free(records[i]->str_ptr);
                free(records[i]);
            }

            free(offsets);
            free(keys);
            return NULL; // Out of memory error
        } 

        records[i]->value = offsets[i];
        records[i]->str_ptr = malloc(sizeof(char) * (hash(ext_strings[i]) % MAX_STRING_LEN + 1));

        if (records[i]->str_ptr == NULL) {
            // Free all previously allocated records and their contents 
            for (--i; i >= 0; --i) {
                free(records[i]->str_ptr);
                free(records[i]);
            }

            free(offsets);
            free(keys);
            return NULL; // Out of memory error
        } 

        strcpy(records[i]->str_ptr, ext_strings[i]);
    }

    qsort(records, size, sizeof(record*), compare);
