typedef struct log_entry {
    long timestamp;
    double temperature;
    int valid;
} log_entry;

void* read_data(void *arg) {
    const char* filename = (const char*) arg;

    // Arrays for data storage
    long *timestamps = NULL;
    double *temperatures = NULL;
    log_entry *entries = NULL;
    size_t capacity = 0, count = 0;

    FILE* file = fopen(filename, "r");

    if (file == NULL) {
        perror("Error opening the file");
        return NULL;
    }

    char line[128]; // Buffer for CSV lines
    long timestamp; 
    double temperature; 
    int valid = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%ld,%lf", &timestamp, &temperature) == 2) {
            // Valid entry
            valid = 1;
        } else {
            // Invalid or malformed entry
            continue;
        }

        // Grow arrays if needed
        if (count >= capacity) {
            size_t newCapacity = capacity * 2 + 8;

            long* newTimestamps = realloc(timestamps, newCapacity * sizeof(*newTimestamps));
            double* newTemperatures = realloc(temperatures, newCapacity * sizeof(*newTemperatures));
            log_entry* newEntries = realloc(entries, newCapacity * sizeof(*newEntries));

            if (newTimestamps == NULL || newTemperatures == NULL || newEntries == NULL) {
                fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));

                free(timestamps);
                free(temperatures);
                free(entries);

                return NULL;
            }

            timestamps = newTimestamps;
            temperatures = newTemperatures;
            entries = newEntries;
        }

        // Save values to the arrays
        timestamps[count] = timestamp;
        temperatures[count] = temperature;
        entries[count].timestamp = timestamp;
        entries[count].temperature = temperature;
        entries[count].valid = valid;
    }

    fclose(file);

    return (void*)entries;
}
