```C
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    char identifier;
    int value;
    struct record* next;
    struct record* prev;
} record_t;

void generateLinkedList(long max_offsets, int max_keys, int min_value, int max_value) {
    long *offsets = (long*)malloc(max_offsets * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed\n");
        return;
    }

    int *keys = (int*)calloc(max_keys, sizeof(int));
    if (!keys) {
        printf("Memory allocation failed\n");
        free(offsets);
        return;
    }

    srand((unsigned int)time(NULL));

    for (long i = 0; i < max_offsets; ++i) 
        offsets[i] = rand() % (max_offsets + 1);

    for (int i = 0; i < max_keys; ++i) {
        int key;
        do {
            key = rand() % max_keys;
        } while(++keys[key] > 1);
    }

    record_t *records = (record_t*)malloc(max_keys * sizeof(record_t));
    if (!records) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    for (int i = 0; i < max_keys; ++i) {
        records[i].identifier = 'A' + rand() % 26;
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    for (int i = 0; i < max_keys; ++i) {
        if(i > 0) {
            records[i].prev = &records[i-1];
            records[i-1].next = &records[i];
        } else 
            records[i].prev = NULL;

        if(i < max_keys - 1) 
            records[i].next = &records[i+1];
        else 
            records[i].next = NULL;
    }

    record_t* node = &records[0];
    while (node != NULL) {
        printf("Identifier: %c, Value: %d\n", node->identifier, node->value);
        node = node->next;
    }

    free(offsets);
    free(keys);
    free(records);
}
```
This code first allocates memory for the offsets and keys arrays. It then populates these arrays with random values, ensuring that each key is unique. After this, it initializes the records array with records structs containing a randomly generated character identifier and value within a specified range. These records are linked together in a doubly-linked list. Finally, the function traverses this list starting from the head node and prints the identifier and value of each record.

Note: This code assumes that `max_keys` is less than or equal to `max_offsets`, as it seems the indices into the offset array correspond directly with the keys. If this assumption does not hold in your case, you would need a separate mechanism for mapping keys to indices. Also remember to free up all allocated memory after use to prevent memory leaks.
