void addEvent(time_t timestamp, EventType type, char* message) {
    // Create a new event and initialize its fields.
    Event* new_event = (Event*)malloc(sizeof(Event));
    if (new_event == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);  // Exit program with error code.
    }
    new_event->timestamp = timestamp;
    new_event->type = type;

    // Allocate memory for message and copy contents to prevent corruption when freeing memory.
    size_t msg_len = strlen(message);
    new_event->message = (char*)malloc((msg_len+1)*sizeof(char));  // +1 for null terminator
    if (new_event->message == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);  // Exit program with error code.
    }
    strcpy(new_event->message, message);

    new_event->next = head;
    head = new_event;
}

