    size_t msgLen;
    struct Event* next;
} Event;

Event* initializeList() {
    return NULL; // Starts with an empty list
}

void addEvent(Event** headRef, time_t timestamp, enum EventType event_type, char* message) {
    Event* newNode = malloc(sizeof(Event));

    if (newNode == NULL) exit(0); // Malloc failed.

    newNode->timestamp = timestamp;
    newNode->event_type = event_type;
    newNode->message = message;
    newNode->msgLen = strlen(message);
    newNode->next = *headRef; // New node points to current head.

    *headRef = newNode; // Head now points to this new node.
}

void printList(Event* head) {
    Event* ptr = head;
    while (ptr != NULL) {
        printf("Timestamp: %ld, ", ptr->timestamp);
        switch(ptr->event_type){
            case INFO:
                printf("Type: INFO");
                break;
            case WARNING:
                printf("Type: WARNING");
                break;
            case ERROR:
                printf("Type: ERROR");
                break;
        }
        printf(", Message: %s\n", ptr->message);

        ptr = ptr->next; // Move to the next node.
    }
}
```
