// Predefined list of names for name indexing
char* names[] = {"John", "Paul", "George", "Ringo"};
#define NAMES_COUNT (sizeof(names)/sizeof(*names))

// Memory pool manager with support for fixed-size and variable-size blocks
typedef struct memory_block {
    size_t size;
    struct memory_block *next;
} memory_block;

memory_block* g_mempool = NULL;
pthread_mutex_t g_lock;

void* allocate(size_t size) {
    pthread_mutex_lock(&g_lock);

    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Allocation failed.\n");
        exit(ALLOCATION_FAILED);
    }

    // Add to memory pool
    memory_block *new_block = malloc(sizeof(memory_block));
    new_block->size = size;
    new_block->next = g_mempool;
    g_mempool = new_block;

    pthread_mutex_unlock(&g_lock);
    return ptr;
}

void deallocate() {
    pthread_mutex_lock(&g_lock);

    // Free all memory blocks in the pool
    while (g_mempool != NULL) {
        memory_block *next = g_mempool->next;
        free(g_mempool);
        g_mempool = next;
    }

    pthread_mutex_unlock(&g_lock);
}

int main() {
    int arraySize, i, randomMin = 100, randomMax = 999;

