#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    int value;
    struct Record* next;
} Record;

Record* head = NULL;
pthread_mutex_t lock;

void insert(int key, int value) {
    pthread_mutex_lock(&lock);

    Record* new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = head;
    head = new_record;

    pthread_mutex_unlock(&lock);
}

void update(int key, int newValue) {
    pthread_mutex_lock(&lock);

    Record* record = head;
    while (record != NULL) {
        if (record->key == key) {
            record->value = newValue;
            break;
        }

        record = record->next;
    }

    pthread_mutex_unlock(&lock);
}

int retrieve(int key) {
    pthread_mutex_lock(&lock);

    Record* record = head;
    while (record != NULL) {
        if (record->key == key) break;

        record = record->next;
    }

    int value = (record != NULL) ? record->value : -1; // -1 indicates not found

    pthread_mutex_unlock(&lock);

    return value;
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    Record* prev = NULL;
    Record* record = head;
    while (record != NULL) {
        if (record->key == key) break;

        prev = record;
        record = record->next;
    }

    // If the node to be deleted is head node 
    if (prev == NULL) {
        Record* next_node = head->next;
        free(head);
        head = next_node;
    } else {
        prev->next = record->next;
        free(record);
    }

    pthread_mutex_unlock(&lock);
}
``` 
This code represents a basic singly linked list with insert, update, retrieve and delete operations protected by mutex lock for thread safety. The key to the memory management is done via malloc() calls which will fail (and set errno) if there's not enough memory available. This can be checked by checking the return value of malloc().
"]

