    }
}

void updateRecords(MoSTState *state, size_t index, int value) {
    pthread_mutex_lock(&state->lock);  // Lock the mutex to safely update.

    state->records[index]->value = value;

    pthread_mutex_unlock(&state->lock);  // Unlock the mutex after updating.
}

void freeState(MoSTState *state, size_t arraySize) {
    for (size_t i = 0; i < arraySize; ++i) {
        free(state->records[i]);  // Free each record individually.
    }

    free(state->offsets);
    free(state->keys);
    free(state->records);

    pthread_mutex_destroy(&state->lock);  // Destroy the mutex.
    free(state);
}
```
This solution assumes a POSIX compliant operating system (like Linux, BSDs etc.). In Windows you may need to use `VirtualAlloc` for aligned memory allocation and other functions instead of standard C library ones. Also it does not include error checking on `fread()` or similar file operations. You'd probably want to add that based on your specific requirements.
