    srand((unsigned int) time(NULL));  // seed the random number generator

    for (int i = 0; i < nrecords; ++i) {
        records[i].offset = offset_range[0] + rand() % (offset_range[1]-offset_range[0]+1);
        records[i].key = key_min + rand() % (key_max - key_min + 1);

        int index = rand() % numNames;  // generate a random name index
        char* compressedName = compressString(names[index], strlen(names[index]));
        if (!compressedName) {
